class _LazyMod(object):
    __slots__ = ('_name', '_mod')
    def __init__(self, name):
        self._name = name
        self._mod = None
    def _load(self):
        if self._mod is None:
            from importlib import import_module
            self._mod = import_module(self._name, package=_PKG)
        return self._mod
    def __getattr__(self, attr):
        # Note: __getattr__ is only called for attrs not found normally,
        # so self._name / self._mod access through __slots__ works as
        # expected without recursion.
        return getattr(self._load(), attr)

class _LazyAttr(object):
    """Same idea but for `from .mod import single_func` patterns. Acts
    as a callable that resolves the underlying function on first call."""
    __slots__ = ('_module', '_attr', '_fn')
    def __init__(self, module, attr):
        self._module = module
        self._attr = attr
        self._fn = None
    def __call__(self, *args, **kwargs):
        if self._fn is None:
            from importlib import import_module
            mod = import_module(self._module, package=_PKG)
            self._fn = getattr(mod, self._attr)
        return self._fn(*args, **kwargs)

