def _monitor_playback(event, level=xbmc.LOGINFO, **payload):
    record = {'event': str(event or ''), 'ts': int(time.time())}
    for key, value in dict(payload or {}).items():
        if value in (None, '', [], {}, ()): 
            continue
        try:
            if isinstance(value, (dict, list, tuple)):
                record[key] = value
            else:
                record[key] = str(value)
        except Exception:
            continue
    try:
        # v5.10.321: tokens in a played URL (X-Plex-Token, api_key) stay out of the log
        from .log import _redact as _hide
        xbmc.log('[DexHubMonitor] %s' % _hide(json.dumps(record, ensure_ascii=False, sort_keys=True)), level)
    except Exception:
        pass
    try:
        path = _playback_monitor_path()
        folder = os.path.dirname(path)
        if folder and not os.path.exists(folder):
            os.makedirs(folder, exist_ok=True)
        try:
            if path and os.path.exists(path) and os.path.getsize(path) > 262144:
                with open(path, 'rb') as fh:
                    data = fh.read()[-131072:]
                with open(path, 'wb') as fh:
                    fh.write(data)
        except Exception:
            pass
        with open(path, 'a', encoding='utf-8') as fh:
            fh.write(json.dumps(record, ensure_ascii=False, sort_keys=True) + '\n')
    except Exception:
        pass

def _is_internal_navigation_path(path):
    value = str(path or '').strip()
    if not value.startswith('plugin://plugin.video.dexhub/'):
        return False
    markers = (
        'action=streams', 'action=episode_streams', 'action=item_open',
        'action=series_meta', 'action=play_item', 'action=cw_resume',
        'action=cw_play_from_start', 'action=play', 'action=tmdb_player',
        'action=kodi_route_browse',
    )
    return any(marker in value for marker in markers)

def _player_has_real_media(player=None):
    player = player or xbmc.Player()
    has_video = False
    try:
        has_video = bool(player.isPlayingVideo())
    except Exception:
        has_video = False
    try:
        has_video = has_video or bool(xbmc.getCondVisibility('Player.HasVideo'))
    except Exception:
        pass
    if not has_video:
        return False
    playing_file = ''
    try:
        # getPlayingFile() logs a noisy Kodi exception when nothing is playing;
        # only call it after Player.HasVideo/isPlayingVideo is already true.
        playing_file = player.getPlayingFile() or ''
    except Exception:
        playing_file = ''
    if playing_file and _is_internal_navigation_path(playing_file):
        return False
    return True

_DISPATCH_PROP = 'dexhub.dispatch.in_flight'

def _dispatch_in_flight(key, window_seconds=2.5):
    """Return True if another plugin invocation just claimed `key`.

    Stamps `key` with the current timestamp on a miss, so a second
    invocation within `window_seconds` is suppressed.

    v3.9.17: window dropped from 6s to 2.5s. The original 6-second clamp made
    legitimate retries (user picked the wrong source, backed out, clicked the
    same item again) silently fail. 2.5s is long enough to catch double-tap
    bouncing but short enough that a deliberate retry feels responsive.
    """
    if not key:
        return False
    now = time.time()
    try:
        win = xbmcgui.Window(WINDOW_ID)
        raw = win.getProperty(_DISPATCH_PROP) or ''
        if raw and '|' in raw:
            prev_key, prev_ts = raw.split('|', 1)
            try:
                prev_ts_f = float(prev_ts)
            except Exception:
                prev_ts_f = 0.0
            if prev_key == key and (now - prev_ts_f) < window_seconds:
                return True
        win.setProperty(_DISPATCH_PROP, '%s|%.3f' % (key, now))
    except Exception:
        return False
    return False

