def _source_art_identity_key(payload=None):
    """Best-effort identity for source/search artwork.

    Kodi/skins keep Window(10000) properties alive longer than the plugin
    invocation. Never reuse those properties unless they belong to the same
    title/id; otherwise the previous playback poster/clearlogo leaks into the
    next source picker or search page.
    """
    data = payload or {}
    try:
        media_type = str(data.get('media_type') or data.get('type') or '').strip().lower()
        canonical = str(data.get('canonical_id') or data.get('id') or '').strip()
        video_id = str(data.get('video_id') or '').strip()
        tmdb_id = str(data.get('tmdb_id') or '').strip()
        imdb_id = str(data.get('imdb_id') or '').strip()
        tvdb_id = str(data.get('tvdb_id') or '').strip()
        season = str(data.get('season') or '').strip()
        episode = str(data.get('episode') or '').strip()
        title = str(data.get('show_title') or data.get('originaltitle') or data.get('title') or data.get('name') or '').strip().lower()
        return '|'.join([media_type, canonical, video_id, tmdb_id, imdb_id, tvdb_id, season, episode, title])
    except Exception:
        return ''

def _home_source_props_match(meta, home=None):
    try:
        home = home or xbmcgui.Window(10000)
        current = home.getProperty('dexhub.source.key') or ''
    except Exception:
        return False
    wanted = _source_art_identity_key(meta)
    return bool(current and wanted and current == wanted)

def play_item(media_type='', canonical_id='', title='', video_id='', season='', episode='', resume_seconds='0', resume_percent='', preferred_provider_name='', tmdb_id='', imdb_id='', tvdb_id='', source_provider_id='', source_mode='', ui_poster='', ui_fanart='', ui_clearlogo='', ui_seed_key=''):
    media_type = str(media_type or 'movie').strip().lower()
    _dispatch_key = 'play_item|%s|%s|%s|%s|%s' % (
        media_type, canonical_id or '', video_id or '',
        str(season or ''), str(episode or ''),
    )
    if _dispatch_in_flight(_dispatch_key):
        # v3.9.17: surface a brief toast so the user knows the click registered.
        # Before, a duplicate dispatch returned silently and looked like a
        # broken UI ("I press OK and nothing happens").
        try:
            xbmc.log('[DexHub] play_item: duplicate dispatch suppressed (%s)' % _dispatch_key, xbmc.LOGINFO)
            xbmcgui.Dialog().notification(
                'Dex Hub',
                tr('جاري التحميل…'),
                xbmcgui.NOTIFICATION_INFO, 1500, sound=False
            )
        except Exception:
            pass
        return
    if not _quick_same_source_enabled(source_provider_id, preferred_provider_name) and _maybe_redirect_default_player(media_type=media_type, canonical_id=canonical_id, title=title or canonical_id, season=season, episode=episode, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id):
        return
    return _dispatch_dexhub_play(
        media_type=media_type,
        canonical_id=canonical_id,
        title=title or canonical_id,
        video_id=video_id,
        season=season,
        episode=episode,
        resume_seconds=resume_seconds,
        resume_percent=resume_percent,
        preferred_provider_name=preferred_provider_name,
        tmdb_id=tmdb_id,
        imdb_id=imdb_id,
        tvdb_id=tvdb_id,
        source_provider_id=source_provider_id,
        source_mode=source_mode,
        ui_seed=_ui_seed_from_route(ui_poster=ui_poster, ui_fanart=ui_fanart, ui_clearlogo=ui_clearlogo, ui_seed_key=ui_seed_key),
    )

def _remember_source_choice(ctx):
    if not _get_bool_setting('remember_last_source', False):
        return
    if not isinstance(ctx, dict):
        return
    scope = _source_scope_key(ctx.get('media_type'), ctx.get('canonical_id'), ctx.get('video_id'))
    if not scope.strip('|'):
        return
    payload = {
        'provider_name': str(ctx.get('provider_name') or '').strip(),
        'provider_id': str(ctx.get('provider_id') or '').strip(),
        'stream_url_host': (urlparse(str(ctx.get('stream_url') or '')).netloc or '').lower(),
        'saved_at': int(time.time()),
    }
    data = _load_source_pref_map()
    data[scope] = payload
    items = sorted(data.items(), key=lambda kv: int(((kv[1] or {}).get('saved_at') or 0)), reverse=True)[:600]
    _save_source_pref_map(dict(items))

def _last_source_choice(media_type='', canonical_id='', video_id=''):
    if not _get_bool_setting('remember_last_source', False):
        return {}
    return _load_source_pref_map().get(_source_scope_key(media_type, canonical_id, video_id), {}) or {}

