def _playback_provider_signature(ctx=None):
    ctx = ctx or {}
    bits = []
    for key in ('server_type', 'provider_id', 'provider_name', 'provider_base_url', 'stream_url'):
        value = str((ctx or {}).get(key) or '').strip().lower()
        if value:
            bits.append(value)
    return ' '.join(bits)

def _is_plex_like_playback(ctx=None):
    sig = _playback_provider_signature(ctx)
    if not sig:
        return False
    return any(marker in sig for marker in ('plex', 'plexio', 'emby', 'jellyfin',
                                            'silo', 'streambridge', 'dexbridge'))

def _is_cancellable_plex_selector(ctx=None, stream_url=''):
    """True for PlexBridge/Plexio plugin URLs that open a second picker.

    Kodi treats cancelling a plugin URL that was handed to Player.play as a
    failed media resolve and shows a scary playback-error dialog.  The bridge
    did not fail in that case; the user simply backed out of its nested list.
    """
    sig = '%s %s' % (_playback_provider_signature(ctx), str(stream_url or '').lower())
    return (str(stream_url or '').lower().startswith('plugin://') and
            any(marker in sig for marker in ('plexbridge', 'plexio')))

def _guard_cancellable_selector_failure(ctx, stream_url):
    """Close only the false Kodi error created after cancelling a nested picker.

    The guard arms only after a select dialog was actually observed, so normal
    playback failures and direct Plex/Emby errors remain visible and logged.
    """
    if not _is_cancellable_plex_selector(ctx, stream_url):
        return

    def _worker():
        saw_selector = False
        selector_closed_at = 0.0
        for _ in range(900):  # at most 90 seconds while the picker is open
            xbmc.sleep(100)
            try:
                player = xbmc.Player()
                if _player_has_real_media(player):
                    return
                active = bool(
                    xbmc.getCondVisibility('Window.IsActive(selectdialog)') or
                    xbmc.getCondVisibility('Dialog.IsActive(selectdialog)'))
                if active:
                    saw_selector = True
                    selector_closed_at = 0.0
                    continue
                if saw_selector and not selector_closed_at:
                    selector_closed_at = time.monotonic()
                if saw_selector and selector_closed_at and time.monotonic() - selector_closed_at >= 0.8:
                    if (xbmc.getCondVisibility('Window.IsActive(okdialog)') or
                            xbmc.getCondVisibility('Dialog.IsActive(okdialog)')):
                        xbmc.executebuiltin('Dialog.Close(okdialog,true)')
                        xbmc.log('[DexHub] suppressed false playback failure after Plex selector cancel',
                                 xbmc.LOGINFO)
                        return
                    # Give Kodi a short window to create the error dialog.
                    if time.monotonic() - selector_closed_at > 4.0:
                        return
            except Exception:
                return

    # This is optional error-dialog polish. Keep it in the shared bounded lane
    # so repeated selector opens cannot accumulate 90-second native threads.
    _submit_optional(
        _worker,
        key='selector-cancel:%s' % abs(hash(str(stream_url or ''))),
    )

def _apply_unique_ids(item, ids, info=None):
    ids = ids or {}
    imdb_id = ids.get('imdb_id') or ''
    tmdb_id = ids.get('tmdb_id') or ''
    tvdb_id = ids.get('tvdb_id') or ''
    if info is not None and imdb_id and not info.get('imdbnumber'):
        info['imdbnumber'] = imdb_id
    try:
        if imdb_id:
            item.setProperty('imdb_id', imdb_id)
            item.setProperty('IMDBNumber', imdb_id)
        if tmdb_id:
            item.setProperty('tmdb_id', tmdb_id)
        if tvdb_id:
            item.setProperty('tvdb_id', tvdb_id)
        unique_ids = {}
        if imdb_id:
            unique_ids['imdb'] = imdb_id
        if tmdb_id:
            unique_ids['tmdb'] = tmdb_id
        if tvdb_id:
            unique_ids['tvdb'] = tvdb_id
        if unique_ids:
            # v3.9.71: prefer the modern InfoTag.setUniqueIDs on Kodi 20+;
            # the legacy ListItem.setUniqueIDs is removed in Kodi 22 and
            # appears to native-crash instead of raising on some alpha
            # builds — same root cause as the deprecated setInfo path.
            _applied_via_tag = False
            try:
                _km = _KODI_MAJOR
            except Exception:
                _km = 19
            if _km >= 20:
                try:
                    _tag = item.getVideoInfoTag()
                    _tag.setUniqueIDs(unique_ids, 'imdb' if imdb_id else ('tmdb' if tmdb_id else 'tvdb'))
                    _applied_via_tag = True
                except Exception:
                    _applied_via_tag = False
            if (not _applied_via_tag) and hasattr(item, 'setUniqueIDs'):
                item.setUniqueIDs(unique_ids, 'imdb' if imdb_id else ('tmdb' if tmdb_id else 'tvdb'))
    except Exception:
        pass

_PENDING_ITEMS = []

_META_MEM = {}

_META_MEM_ORDER = []

_META_MEM_MAX = 384

_META_MEM_LOCK = threading.Lock()

def _meta_mem_key(media_type, canonical_id, source_provider_id=''):
    return '%s:%s:%s' % (media_type or '', canonical_id or '', _meta_cache_discriminator(source_provider_id))

def _meta_mem_get(media_type, canonical_id, source_provider_id=''):
    key = _meta_mem_key(media_type, canonical_id, source_provider_id)
    ttl = max(60, int(meta_ttl() or 3600))
    with _META_MEM_LOCK:
        row = _META_MEM.get(key)
        if not row:
            return None
        saved_at, payload = row
        if (time.time() - saved_at) > ttl:
            _META_MEM.pop(key, None)
            try:
                _META_MEM_ORDER.remove(key)
            except ValueError:
                pass
            return None
        return dict(payload or {})

def _meta_mem_put(media_type, canonical_id, payload, source_provider_id=''):
    if not payload:
        return
    key = _meta_mem_key(media_type, canonical_id, source_provider_id)
    with _META_MEM_LOCK:
        if key not in _META_MEM:
            _META_MEM_ORDER.append(key)
        _META_MEM[key] = (time.time(), dict(payload))
        while len(_META_MEM_ORDER) > _META_MEM_MAX:
            old = _META_MEM_ORDER.pop(0)
            _META_MEM.pop(old, None)

def _favorite_properties(is_favorite=None):
    # Skin quirk fix: some skins draw a heart overlay if the standard
    # IsFavorite/IsFavourite property EXISTS at all, even when its value is
    # 'false'. Only publish the standard properties for real favorites.
    if not bool(is_favorite):
        return {}
    return {
        'IsFavorite': 'true',
        'IsFavourite': 'true',
        'DexHub.IsFavorite': 'true',
        'DexHub.IsFavourite': 'true',
    }

def _art_value_looks_rating_proxy(value):
    text = str(value or '').lower()
    return any(token in text for token in (
        'easyratingsdb.com', 'easyratingsdb', 'erdb',
        'ratingposterdb.com', 'rating-poster', 'ratingposter', 'rpdb',
        'poster-ratings', 'ratings-poster',
        # v3.9.21: modern poster-decoration services
        'btttr.cc', 'betterposters',
        'top-streaming.stream', 'top-posters', 'topposters',
        'aiometadata', 'aioratings',
        'mdblist.com/poster',
    ))

def _art_value_looks_overlay_proxy(value):
    text = str(value or '').lower()
    return _art_value_looks_rating_proxy(text) or any(token in text for token in (
        'plexio', 'plexbridge', 'plex.dexworld', 'plexio.dexworld',
        'sb.dexworld', 'dexbridge',
        '/:/transcode', 'composite', 'overlay', 'photo/:/transcode',
        '/photo/', '/composite/',
        '/items/', '/emby/', '/jellyfin/',
    ))

def _normalize_kodi_item_art(art):
    """Mirror fragile overlay posters to the art keys Kodi skins commonly read.

    Important: do not mirror poster into fanart. ERDB/Plexio may provide a
    separate backdrop, and copying the vertical poster there changes the
    background. Only fill poster-like slots.
    """
    if not art:
        return art

    # Kodi callers historically pass either an art mapping or a single image
    # path.  The providers/accounts menus use media_path(...), which returns a
    # string.  Calling dict(string) raises ValueError and crashes the directory.
    # Normalize scalar paths to Kodi's standard art mapping first.
    if isinstance(art, (str, bytes)):
        value = art.decode('utf-8', 'replace') if isinstance(art, bytes) else art
        value = str(value or '').strip()
        if not value:
            return {}
        art = {
            'icon': value,
            'thumb': value,
            'poster': value,
        }
    elif not isinstance(art, dict):
        try:
            art = dict(art)
        except (TypeError, ValueError):
            value = str(art or '').strip()
            if not value:
                return {}
            art = {'icon': value, 'thumb': value, 'poster': value}

    out = dict(art)
    poster = out.get('poster') or out.get('tvshow.poster') or out.get('season.poster') or out.get('thumb') or out.get('icon')
    if poster:
        out.setdefault('poster', poster)
        out.setdefault('tvshow.poster', poster)
        out.setdefault('season.poster', poster)
        out.setdefault('thumbnail', poster)
        out.setdefault('cover', poster)
        out.setdefault('image', poster)
        out.setdefault('tvshow.thumb', poster)
        if _art_value_looks_overlay_proxy(poster):
            out['thumb'] = poster
            out['icon'] = poster
            out['thumbnail'] = poster
            out['cover'] = poster
            out['image'] = poster
            out['tvshow.thumb'] = poster
        else:
            out.setdefault('thumb', poster)
            out.setdefault('icon', poster)
    return out

_METAHUB_POSTER = 'https://images.metahub.space/poster/large/%s/img'

_METAHUB_BG     = 'https://images.metahub.space/background/large/%s/img'

_METAHUB_LOGO   = 'https://images.metahub.space/logo/medium/%s/img'

_PROXY_HEALTH = {}                # domain → (is_healthy: bool, expires_at: float)

_PROXY_HEALTH_LOCK = threading.Lock()

_PROXY_HEALTH_TTL = 300.0         # 5 minutes — short enough to recover quickly

_PROXY_PROBE_TIMEOUT = 1.5        # 1.5s budget per probe; cheap

def _proxy_url_domain(url):
    try:
        return (urlparse(url).netloc or '').lower()
    except Exception:
        return ''

def _probe_proxy_health(url):
    """Single HEAD probe with a tight timeout. Returns True if the server
    answered with a non-error status; False on any failure."""
    try:
        from urllib.request import Request, urlopen
        req = Request(url, method='HEAD',
                      headers={'User-Agent': 'DexHub-poster-probe/1.0'})
        with urlopen(req, timeout=_PROXY_PROBE_TIMEOUT) as resp:
            code = getattr(resp, 'status', None) or resp.getcode()
            return 200 <= int(code) < 400
    except Exception:
        return False

def _is_proxy_healthy(url):
    """Decide if a poster proxy domain is currently usable.

    Looks the domain up in the TTL cache; on miss, probes once and
    caches the result. Subsequent items from the same domain pay zero
    probe cost.
    """
    domain = _proxy_url_domain(url)
    if not domain:
        return True
    now = time.time()
    with _PROXY_HEALTH_LOCK:
        cached = _PROXY_HEALTH.get(domain)
        if cached and now < cached[1]:
            return cached[0]
    # v3.9.154: mirror the verdict in a Window property so every warm
    # reuselanguageinvoker interpreter shares ONE probe per TTL instead of
    # each paying the 1.5s HEAD on its first catalog — badges show with the
    # results instead of after them.
    _prop_key = 'dexhub.proxyhealth.%s' % domain
    try:
        _raw = xbmcgui.Window(WINDOW_ID).getProperty(_prop_key) or ''
        if _raw:
            _verdict, _expiry = _raw.split('|', 1)
            if now < float(_expiry):
                _h = (_verdict == '1')
                with _PROXY_HEALTH_LOCK:
                    _PROXY_HEALTH[domain] = (_h, float(_expiry))
                return _h
    except Exception:
        pass
    healthy = _probe_proxy_health(url)
    _until = now + _PROXY_HEALTH_TTL
    with _PROXY_HEALTH_LOCK:
        _PROXY_HEALTH[domain] = (healthy, _until)
    try:
        xbmcgui.Window(WINDOW_ID).setProperty(_prop_key, '%s|%s' % ('1' if healthy else '0', _until))
    except Exception:
        pass
    xbmc.log(
        '[DexHub] poster-proxy %s probed: %s' %
        (domain, 'healthy' if healthy else 'UNREACHABLE — falling back to clean'),
        xbmc.LOGINFO,
    )
    return healthy

def _extract_imdb_id(meta):
    """Return the imdb id (tt1234567) for a meta dict, if derivable."""
    raw = meta or {}
    for key in ('imdb_id', 'imdb', 'id'):
        candidate = str(raw.get(key) or '').strip()
        if candidate.startswith('tt'):
            # For series episodes the id is "tt0123:season:episode" — strip
            # to the bare series id; the poster is the series poster anyway.
            return candidate.split(':')[0]
    return ''

def _clean_meta_art(meta):
    """Return a dict of clean (no-overlay) art URLs derived from metahub.space.

    Only fills slots where we can compute a reliable URL — the caller
    decides whether to use these as primary or fallback.
    """
    imdb = _extract_imdb_id(meta)
    if not imdb:
        return {}
    return {
        'poster':    _METAHUB_POSTER % imdb,
        'thumb':     _METAHUB_POSTER % imdb,
        'fanart':    _METAHUB_BG     % imdb,
        'landscape': _METAHUB_BG     % imdb,
        'clearlogo': _METAHUB_LOGO   % imdb,
    }

def _poster_reliability_mode():
    """Return the user's choice for handling decorated/overlay poster URLs.

    Values:
      'auto'      — default: detect decoration proxies and substitute
                    metahub.space clean URLs for any poster that looks
                    overlay-wrapped. Trades rating badges for reliability.
      'clean'     — force clean URLs everywhere, even when the proxy is
                    healthy. Disables all rating overlays.
      'decorated' — preserve current behavior; use whatever the catalog
                    provided, even if it's an overlay-decorated URL. Best
                    when the user really wants badges and accepts that
                    some posters won't load.
    """
    try:
        raw = (ADDON.getSetting('poster_reliability_mode') or 'Always clean (no badges)').strip()
    except Exception:
        raw = 'Smart fallback (recommended)'
    # Map the human-readable Kodi label to an internal mode constant.
    # Done with substring matches so future label rewording (e.g. minor
    # translation tweaks) doesn't break the routing.
    low = raw.lower()
    if ('clean' in low and 'no badges' in low) or 'نظيف' in low:
        return 'clean'
    if ('decorated' in low and 'keep' in low) or 'مزي' in low or 'مزخرف' in low:
        return 'decorated'
    return 'auto'

def _apply_poster_reliability(art, meta):
    """Final poster pass — decorated URL stays primary, clean URL goes in
    fallback slots only.

    The default mode is "Auto (badges + fallback)" — we keep the catalog's
    decorated URL on the `poster` key (so RPDB ratings, BetterPosters badges,
    4K/HDR pills all render when the proxy is healthy) and put a clean
    metahub.space URL on `thumb`/`icon`/`thumbnail`/`cover`/`image`. Most
    Kodi skins (Aura, Estuary MOD V2, Arctic Fuse, Estouchy) walk this
    fallback chain when the primary `poster` 404s or times out, so the
    user still sees a usable poster even if the proxy is down.

    Modes:
      'auto'      — decorated stays primary; clean fills thumb-family
                    slots as a safety net. (default)
      'clean'     — strip every decoration even when proxy works. No
                    badges anywhere. For users who explicitly don't want
                    ratings overlays.
      'decorated' — preserve current behavior exactly; no fallback. Badge
                    URLs are mirrored to every slot (matches v3.9.20 and
                    earlier). Use only if a skin has explicit issues with
                    differing poster/thumb URLs.
    """
    if not art:
        return art
    mode = _poster_reliability_mode()
    poster = (art.get('poster') or '').strip()
    if not poster:
        return art

    looks_decorated = _art_value_looks_overlay_proxy(poster)

    # 'clean' mode: always strip if a clean URL is derivable.
    if mode == 'clean':
        clean = _clean_meta_art(meta or {})
        if not clean.get('poster'):
            return art
        out = dict(art)
        for key in ('poster', 'thumb', 'thumbnail', 'cover', 'image',
                    'tvshow.poster', 'season.poster', 'tvshow.thumb', 'icon'):
            if out.get(key):
                out[key] = clean['poster']
            else:
                out.setdefault(key, clean['poster'])
        if not out.get('fanart') and clean.get('fanart'):
            out['fanart'] = clean['fanart']
            out.setdefault('landscape', clean['fanart'])
        return out

    # 'decorated' mode: legacy — leave everything as-is.
    if mode == 'decorated':
        return art

    # 'auto' mode (default): build a local-proxy URL when the poster
    # proxy server (service.py) is up. The proxy hands Kodi a single URL
    # that transparently falls back decorated → clean upstream, so even
    # skins that don't honour Kodi's poster→thumb fallback chain
    # (Estuary, Confluence, etc.) get a working poster in every case.
    #
    # When the proxy is unavailable (port couldn't bind, service not yet
    # up), we degrade to the v3.9.23 HEAD-probe heuristic: probe the
    # proxy domain once, cache for 5 min, decide decorated-vs-clean for
    # this and subsequent items from the same domain.
    if not looks_decorated:
        return art
    clean = _clean_meta_art(meta or {})
    if not clean.get('poster'):
        return art

    out = dict(art)

    # Path A: local image proxy is alive — use it.
    try:
        from . import poster_proxy as _proxy
        proxy_url = _proxy.build_url(poster, clean['poster'])
    except Exception:
        proxy_url = ''

    if proxy_url:
        # All poster-family slots point at the proxy URL. Kodi loads a
        # single endpoint that always responds; the proxy decides
        # decorated-vs-clean internally with a 3s upstream budget.
        out['poster']        = proxy_url
        out['tvshow.poster'] = proxy_url
        out['season.poster'] = proxy_url
        # Thumb stays clean so the artwork cache for thumb is separately
        # warm — and any code path that explicitly reads `thumb` (like
        # picture-in-picture overlays) still gets a usable image even
        # if the proxy is briefly slow.
        out['thumb']         = clean['poster']
        out['thumbnail']     = clean['poster']
        out['cover']         = clean['poster']
        out['image']         = clean['poster']
        out['icon']          = clean['poster']
        out['tvshow.thumb']  = clean['poster']
        if not out.get('fanart') and clean.get('fanart'):
            out['fanart'] = clean['fanart']
            out.setdefault('landscape', clean['fanart'])
        return out

    # Path B: no proxy available — fall back to HEAD-probe heuristic.
    proxy_alive = _is_proxy_healthy(poster)
    if proxy_alive:
        out['poster']        = poster
        out['tvshow.poster'] = poster
        out['season.poster'] = poster
        out['thumb']         = clean['poster']
        out['thumbnail']     = clean['poster']
        out['cover']         = clean['poster']
        out['image']         = clean['poster']
        out['icon']          = clean['poster']
        out['tvshow.thumb']  = clean['poster']
    else:
        for key in ('poster', 'thumb', 'thumbnail', 'cover', 'image',
                    'tvshow.poster', 'season.poster', 'tvshow.thumb', 'icon'):
            out[key] = clean['poster']
    if not out.get('fanart') and clean.get('fanart'):
        out['fanart'] = clean['fanart']
        out.setdefault('landscape', clean['fanart'])
    return out

def _kodi_major_version():
    try:
        ver = xbmc.getInfoLabel('System.BuildVersion') or ''
        return int(str(ver).split('.', 1)[0])
    except Exception:
        return 19

_KODI_MAJOR = _kodi_major_version()

def _safe_playback_handoff_enabled():
    """Kodi 22/CoreELEC safe playback mode.

    Piers alpha builds can native-crash during the transition from a custom
    source dialog into fullscreen playback when the handoff ListItem carries
    too many skin-specific/global artwork aliases. Keep the source picker rich,
    but make the actual player item closer to TMDb Helper/Kodi defaults.
    """
    try:
        raw = (ADDON.getSetting('safe_playback_handoff') or 'true').strip().lower()
        enabled = raw in ('true', '1', 'yes', 'on')
    except Exception:
        enabled = True
    return bool(_KODI_MAJOR >= 22 and enabled)

def _kodi22_playlist_handoff_enabled():
    """Use an EmbyCon-style playlist handoff on Kodi 22/CoreELEC.

    Kodi 22 alpha/CoreELEC has shown native crashes with direct URL
    Player.play(url, listitem) and with large playback ListItems. EmbyCon is
    stable on the same systems because it builds a one-item PlayList and calls
    Player.play(playlist). Keep this behind the existing safe handoff setting
    so older Kodi versions and advanced users are unaffected.
    """
    try:
        return _KODI_MAJOR >= 22 and _safe_playback_handoff_enabled()
    except Exception:
        return False

def _kodi22_minimal_item_enabled():
    """Strip EVERY VideoInfoTag mutation from the playback handoff on Kodi 22.

    v3.9.192 — the crash that restarts the box on play.

    The existing safe mode only skipped InfoTag.setArtwork(). Two other native
    InfoTag mutations still ran on the exact same handoff:

        _videoinfotag_apply(...)      full tag: title, plot, genres, CAST...
        getVideoInfoTag().setUniqueIDs(...)   the "re-assert" pass

    Kodi 22 BETA on CoreELEC can die inside those native calls before the first
    frame is drawn — Kodi is then restarted by the system, which is exactly the
    "device restarts when I press play" report. ListItem.setArt() and the
    ListItem properties are NOT part of that native path and stay in place, so
    skins keep their artwork and Dex Hub's own subtitle bridge keeps the IDs.

    Turn this off to get the rich InfoTag back on builds that tolerate it.
    """
    try:
        # v5.10.94: default OFF. DPlex proved the full ListItem/InfoTag path
        # safe on the Kodi 22 devices this addon targets, and the minimal item
        # hides title and ids from Kodi's own subtitle dialog and every
        # subtitle addon. The setting stays as an opt-in crash guard.
        raw = (ADDON.getSetting('kodi22_minimal_item') or 'false').strip().lower()
        enabled = raw in ('true', '1', 'yes', 'on')
    except Exception:
        enabled = False
    return bool(_kodi22_playlist_handoff_enabled() and enabled)

def _native_resume_hint_allowed():
    """Whether Kodi may receive a native ResumeTime/InfoTag resume point.

    Kodi 22 alpha can crash in its native resume-dialog path when a playlist
    resolves back into a plugin URL (see CVideoPlayActionProcessor::
    OnResumeSelected in the crash report).  Dex Hub already applies the same
    position after real media starts, so suppress only the redundant native
    hint on the safe Kodi 22 playlist route.
    """
    return not _kodi22_playlist_handoff_enabled()

def _videoinfotag_apply(item, info, ids=None, cast=None):
    """Map a flat info dict + ids + cast list onto the modern VideoInfoTag API.

    Skins on Kodi 20+ render rich items (cast posters, ratings, votes, premiere
    dates, MPAA chips, IMDB number) only when this API is used. Old setInfo
    drops or hides several of those fields. Falls back gracefully on any
    individual setter that raises.

    cast format: [{'name': 'Actor', 'role': 'Character', 'thumbnail': 'url'},...]
    """
    try:
        tag = item.getVideoInfoTag(offscreen=True)
    except Exception:
        return False

    def _try(fn, *args):
        try:
            fn(*args)
        except Exception:
            pass

    # Media type sets the icons & rendering mode in the skin. Always set first.
    mt = (info or {}).get('mediatype') or ''
    if mt:
        _try(tag.setMediaType, mt)

    if (info or {}).get('title') is not None:
        _try(tag.setTitle, str(info['title']))
    if (info or {}).get('originaltitle') is not None:
        _try(tag.setOriginalTitle, str(info['originaltitle']))
    if (info or {}).get('plot') is not None:
        _try(tag.setPlot, str(info['plot']))
    if (info or {}).get('plotoutline') is not None:
        _try(tag.setPlotOutline, str(info['plotoutline']))
    if (info or {}).get('tagline') is not None:
        _try(tag.setTagLine, str(info['tagline']))
    if (info or {}).get('mpaa') is not None:
        _try(tag.setMpaa, str(info['mpaa']))
    if (info or {}).get('studio') is not None:
        s = info['studio']
        _try(tag.setStudios, s if isinstance(s, (list, tuple)) else (str(s),))
    if (info or {}).get('country') is not None:
        c = info['country']
        _try(tag.setCountries, c if isinstance(c, (list, tuple)) else [str(c)])
    if (info or {}).get('director') is not None:
        d = info['director']
        if isinstance(d, str):
            d = [x.strip() for x in d.split(',') if x.strip()]
        _try(tag.setDirectors, list(d) if d else [])
    if (info or {}).get('writer') is not None:
        w = info['writer']
        if isinstance(w, str):
            w = [x.strip() for x in w.split(',') if x.strip()]
        _try(tag.setWriters, list(w) if w else [])
    if (info or {}).get('genre') is not None:
        g = info['genre']
        if isinstance(g, str):
            g = [x.strip() for x in re.split(r'[,/]', g) if x.strip()]
        _try(tag.setGenres, list(g) if g else [])
    if (info or {}).get('year') is not None:
        try:
            _try(tag.setYear, int(info['year']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('premiered') is not None:
        _try(tag.setPremiered, str(info['premiered']))
    if (info or {}).get('rating') is not None:
        try:
            _try(tag.setRating, float(info['rating']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('votes') is not None:
        try:
            _try(tag.setVotes, int(info['votes']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('duration') is not None:
        try:
            _try(tag.setDuration, int(info['duration']))
        except (ValueError, TypeError):
            pass
    # POV-style resume support for Kodi 20+: put the resume point on
    # the VideoInfoTag, not only on ListItem properties, so home widgets
    # and skins render/play continued items correctly.
    if (info or {}).get('resumetime') is not None or (info or {}).get('totaltime') is not None:
        try:
            _rt = float((info or {}).get('resumetime') or 0.0)
            _tt = float((info or {}).get('totaltime') or (info or {}).get('duration') or 0.0)
            if _rt > 0 and _tt > 0:
                _try(tag.setResumePoint, _rt, _tt)
        except Exception:
            pass
    if (info or {}).get('trailer') is not None:
        _try(tag.setTrailer, str(info['trailer']))
    if (info or {}).get('imdbnumber') is not None:
        _try(tag.setIMDBNumber, str(info['imdbnumber']))
    if (info or {}).get('playcount') is not None:
        try:
            _try(tag.setPlaycount, int(info['playcount']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('tvshowtitle') is not None:
        _try(tag.setTvShowTitle, str(info['tvshowtitle']))
    if (info or {}).get('season') is not None:
        try:
            _try(tag.setSeason, int(info['season']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('episode') is not None:
        try:
            _try(tag.setEpisode, int(info['episode']))
        except (ValueError, TypeError):
            pass

    # Unique IDs — modern keys (no _id suffix), default IMDb when present
    if ids:
        clean_ids = {}
        if ids.get('imdb_id'):
            clean_ids['imdb'] = str(ids['imdb_id'])
        if ids.get('tmdb_id'):
            clean_ids['tmdb'] = str(ids['tmdb_id'])
        if ids.get('tvdb_id'):
            clean_ids['tvdb'] = str(ids['tvdb_id'])
        if clean_ids:
            mt_key = str((info or {}).get('mediatype') or '').strip().lower()
            if mt_key in ('episode', 'tvshow', 'season'):
                # TMDb Helper's playerstring reads tvshow.* unique IDs for
                # episodes; keep the plain keys too for a4k/OpenSubtitles.
                if 'imdb' in clean_ids:
                    clean_ids.setdefault('tvshow.imdb', clean_ids['imdb'])
                if 'tmdb' in clean_ids:
                    clean_ids.setdefault('tvshow.tmdb', clean_ids['tmdb'])
                if 'tvdb' in clean_ids:
                    clean_ids.setdefault('tvshow.tvdb', clean_ids['tvdb'])
            default_key = 'imdb' if 'imdb' in clean_ids else ('tmdb' if 'tmdb' in clean_ids else 'tvdb')
            _try(tag.setUniqueIDs, clean_ids, default_key)

    # Stream details — many skins show codec/runtime chips from InfoTag.
    stream_details = (info or {}).get('streamdetails') or {}
    if isinstance(stream_details, dict):
        try:
            if hasattr(tag, 'addVideoStream') and isinstance(stream_details.get('video'), dict):
                v = stream_details.get('video') or {}
                _try(tag.addVideoStream, int(v.get('width') or 0), int(v.get('height') or 0), float(v.get('aspect') or 0), int(v.get('duration') or 0), str(v.get('codec') or ''), str(v.get('stereomode') or ''))
        except Exception:
            pass

    # Cast with thumbnails — this is what makes the right-side panel
    # in modern skins look "TMDb Helper-grade" instead of an empty list.
    if cast:
        try:
            actor_objects = []
            for entry in cast:
                if not isinstance(entry, dict):
                    continue
                name = str(entry.get('name') or '').strip()
                if not name:
                    continue
                role = str(entry.get('role') or entry.get('character') or '').strip()
                thumb = str(entry.get('thumbnail') or entry.get('photo') or entry.get('profile_path') or '').strip()
                order = entry.get('order')
                try:
                    order_int = int(order) if order is not None else len(actor_objects)
                except (ValueError, TypeError):
                    order_int = len(actor_objects)
                try:
                    actor_objects.append(xbmc.Actor(name, role, order_int, thumb))
                except Exception:
                    # Older Kodi 20 builds had Actor signature variants.
                    try:
                        actor_objects.append(xbmc.Actor(name=name, role=role, order=order_int, thumbnail=thumb))
                    except Exception:
                        pass
            if actor_objects:
                _try(tag.setCast, actor_objects)
        except Exception:
            pass
    return True

def _apply_sort_methods(content=None, sortable=True):
    # Issue #8 fix: Kodi remembers the user's last sort choice for a path. If
    # they accidentally tap "Sort by name" once, every catalog page in the
    # addon opens alphabetical from then on. Solution: don't register the
    # alphabetical sort at all on listing pages — Kodi can only fall back to
    # one of OUR registered methods. UNSORTED is first → it becomes the
    # default and the addon's natural order (newest-first for almost every
    # Stremio catalog) is preserved as "last release" feel.
    methods = [xbmcplugin.SORT_METHOD_UNSORTED]
    # v4.6.9: recency listings (search history) must register UNSORTED ONLY.
    # content=None used to append the alphabetical method, and Kodi's
    # per-path sort memory then showed the history "from letter A" instead
    # of most-recent-first — burying the word the user just searched.
    if not sortable:
        try:
            xbmcplugin.addSortMethod(HANDLE, xbmcplugin.SORT_METHOD_UNSORTED)
        except Exception:
            pass
        return
    if content in ('movies', 'tvshows', 'episodes', 'seasons'):
        methods.extend([
            xbmcplugin.SORT_METHOD_VIDEO_YEAR,
            xbmcplugin.SORT_METHOD_VIDEO_RATING,
            xbmcplugin.SORT_METHOD_DATE,
            xbmcplugin.SORT_METHOD_DURATION,
        ])
    # Allow alphabetical only on non-media listings (provider/category menus).
    if content in (None, 'files', 'addons'):
        methods.append(xbmcplugin.SORT_METHOD_LABEL_IGNORE_THE)
    seen = set()
    for method in methods:
        if method in seen:
            continue
        seen.add(method)
        try:
            xbmcplugin.addSortMethod(HANDLE, method)
        except Exception:
            pass

def _flush_pending_items():
    """Push all buffered items to Kodi in ONE IPC call."""
    global _PENDING_ITEMS
    if not _PENDING_ITEMS:
        return
    # v5.10.120: a widget of Arctic Fuse 3 opens a series on Dex Hub's
    # title page in the skin, not in the add-on's seasons listing
    try:
        from .skinui import widgetclick as _widgetclick
        _PENDING_ITEMS = _widgetclick.adapt(_PENDING_ITEMS)
    except Exception:
        pass
    try:
        xbmcplugin.addDirectoryItems(HANDLE, _PENDING_ITEMS, len(_PENDING_ITEMS))
    except Exception:
        # Fall back to per-item add if the batch path fails (very rare).
        for path, item, is_folder in _PENDING_ITEMS:
            try:
                xbmcplugin.addDirectoryItem(HANDLE, path, item, isFolder=is_folder)
            except Exception:
                pass
    _PENDING_ITEMS = []

def _provider_is_rating_proxy(provider):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    haystack = ' '.join([
        str(provider.get('name') or ''),
        str(provider.get('id') or ''),
        str(provider.get('base_url') or ''),
        str(provider.get('manifest_url') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()
    return any(h in haystack for h in (
        'easyratingsdb.com', 'easyratingsdb', 'erdb proxy', 'erdb',
        'ratingposterdb.com', 'rating poster', 'ratingposter', 'rpdb'
    ))

def _provider_is_plexio(provider):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    haystack = ' '.join([
        str(provider.get('name') or ''),
        str(provider.get('id') or ''),
        str(provider.get('base_url') or ''),
        str(provider.get('manifest_url') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()
    return any(h in haystack for h in ('plexio', 'plexbridge', 'com.stremio.plexio', 'com.stremio.plexbridge', 'sb.dexworld', 'dexbridge'))

def _provider_prefers_native_art(provider):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    haystack = ' '.join([
        str(provider.get('name') or ''),
        str(provider.get('id') or ''),
        str(provider.get('base_url') or ''),
        str(provider.get('manifest_url') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()
    # Plex / Emby / Plexio / DexBridge all build poster URLs that include
    # auth tokens or session-bound paths. Kodi's image loader strips query
    # strings, expires the cache aggressively, and chokes on long URLs —
    # so for ANY of these providers we prefer remote (TMDb-based) art.
    return any(h in haystack for h in ('plex', 'plexio', 'emby', 'jellyfin', 'silo', 'dexbridge'))

_ART_URL_KEYS = (
    'poster', 'thumbnail', 'thumb', 'image', 'posterUrl', 'posterURL',
    'imageUrl', 'imageURL', 'thumbUrl', 'thumbURL', 'background', 'fanart',
    'landscape', 'banner', 'backdrop', 'clearlogo', 'logo', 'clearart',
    'parentThumb', 'grandparentThumb', 'art', 'key'
)

def _safe_http_origin(raw):
    """Keep only scheme + host so configured manifest tokens never reach UI."""
    try:
        parsed = urlparse(str(raw or '').strip())
        host = (parsed.netloc or '').split('@')[-1]
        if parsed.scheme.lower() in ('http', 'https') and host:
            return '%s://%s' % (parsed.scheme.lower(), host)
    except Exception:
        pass
    return ''

def _provider_origin(provider):
    provider = provider or {}
    for raw in (provider.get('base_url'), provider.get('manifest_url')):
        origin = _safe_http_origin(raw)
        if origin:
            return origin
    return ''

def _provider_meta_source_id(provider):
    try:
        provider_id = (provider or {}).get('id') or ''
        source_id = (_meta_source.get_meta_source_for(provider_id) if provider_id else 'auto') or 'auto'
        # Plexio auto must mean Plexio/native artwork, not a hidden TMDb/Cinemeta
        # swap. Explicit picks (TMDb Helper / another metadata addon / native)
        # are still honored below by meta_source.override_* and _resolve_meta_art.
        if source_id == 'auto' and _provider_is_plexio(provider):
            return 'native'
        return source_id
    except Exception:
        return 'auto'

def _provider_uses_explicit_meta_art(provider):
    source_id = _provider_meta_source_id(provider)
    return source_id not in ('', 'auto')

def _meta_art_is_strict(meta):
    return str((meta or {}).get('_dexhub_art_strict') or '').strip().lower() in ('1', 'true', 'yes', 'on')

def _meta_source_id_from_meta(meta):
    return str((meta or {}).get('_dexhub_meta_source_id') or '').strip()

def _target_meta_source_id(target_key):
    try:
        return (_meta_source.get_meta_source_for(target_key) if target_key else 'auto') or 'auto'
    except Exception:
        return 'auto'

def _target_meta_source_is_explicit(target_key):
    return _target_meta_source_id(target_key) not in ('', 'auto')

def _is_virtual_meta_target(target_key):
    return str(target_key or '').strip().startswith('virtual.')

def _source_context_requires_exact_meta(source_provider_id):
    sid = str(source_provider_id or '').strip()
    if not sid:
        return False
    if _is_virtual_meta_target(sid):
        return _target_meta_source_is_explicit(sid)
    try:
        provider = store.get_provider(sid)
    except Exception:
        provider = None
    return _provider_uses_explicit_meta_art(provider or {'id': sid})

def _meta_cache_discriminator(source_provider_id=''):
    try:
        source_map = ADDON.getSetting('provider_meta_map') or '{}'
    except Exception:
        source_map = '{}'
    return '|'.join([
        str(source_provider_id or ''),
        str(source_map or '{}'),
        str(ADDON.getSetting('global_meta_source_id') or ''),
        str(ADDON.getSetting('global_meta_source_all') or ''),
        str(ADDON.getSetting('global_poster_source_id') or ''),
        str(ADDON.getSetting('metadata_generation') or ''),
        str(_tmdb_art_db.helper_language() or ''),
        str(poster_source_mode() or ''),
    ])

def _meta_provider_first(providers, source_provider_id=''):
    providers = [p for p in (providers or []) if p]
    sid = str(source_provider_id or '').strip()
    if not sid:
        return providers
    head = []
    tail = []
    seen = set()
    for p in providers:
        pid = str((p or {}).get('id') or '')
        if not pid or pid in seen:
            continue
        seen.add(pid)
        if pid == sid:
            head.append(p)
        else:
            tail.append(p)
    if not head:
        try:
            p = store.get_provider(sid)
        except Exception:
            p = None
        if p:
            head.append(p)
    return head + tail

def _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=''):
    return _meta_provider_first(_provider_order_for_id(media_type, canonical_id), source_provider_id=source_provider_id)

def _resolve_meta_art(provider, media_type, meta, fallback_art=None, force_remote=False, lazy=False):
    # v3.9.21 wrapper — runs the existing resolver, then applies the user's
    # poster reliability filter (auto/clean/decorated) so decorated overlay
    # URLs from RPDB/BetterPosters/TOP Posters get swapped for direct
    # metahub.space CDN URLs when needed. The wrapper preserves every
    # existing source-priority code path below; it only post-processes
    # the final art dict.
    #
    # v3.9.31 — lazy mode: when `lazy=True`, skip the heavy enrichment
    # passes (TMDB/Fanart cross-lookup, meta_cache deep reads, bucket
    # art priority HTTP-free fallback). Used for items past the visible
    # threshold (#13+) in folder renders. They still get correct
    # poster/fanart from the meta dict itself, just not the cross-source
    # enrichment that costs 5-15ms per item.
    if lazy:
        return _resolve_meta_art_fast(provider, media_type, meta, fallback_art)
    art = _resolve_meta_art_inner(provider, media_type, meta,
                                    fallback_art=fallback_art,
                                    force_remote=force_remote)
    if _meta_art_is_strict(meta):
        return art
    try:
        art = _apply_poster_reliability(art, meta)
    except Exception as exc:
        xbmc.log('[DexHub] poster reliability filter failed: %s' % exc, xbmc.LOGDEBUG)
    # Global artwork policy applies everywhere. A folder-specific policy is
    # applied afterwards and therefore acts as an intentional exception.
    try:
        art = _apply_global_art_priority(art, media_type, meta, provider)
    except Exception as exc:
        xbmc.log('[DexHub] global art priority failed: %s' % exc, xbmc.LOGDEBUG)
    try:
        art = _apply_bucket_art_priority(art, media_type, meta, provider)
    except Exception as exc:
        xbmc.log('[DexHub] bucket art priority failed: %s' % exc, xbmc.LOGDEBUG)
    try:
        art = _better_posters.apply(
            art, (extract_ids(meta or {}) or {}).get('imdb_id') or '',
            media_type, ADDON)
    except Exception as exc:
        xbmc.log('[DexHub] BetterPosters URL pass failed: %s' % exc, xbmc.LOGDEBUG)
    return art

def _resolve_meta_art_fast(provider, media_type, meta, fallback_art=None):
    """v3.9.31 — minimal art resolution for items past the visible
    threshold in a folder render.

    Skipped vs full path:
      - TMDB enrichment (HTTP)
      - Fanart.tv enrichment (HTTP)
      - meta_cache cross-provider lookups
      - bucket art priority resolution
      - meta_source override negotiation

    Kept:
      - poster reliability filter (cheap regex, prevents decorated URL leaks)
      - poster_proxy wrapping (preserves the local CDN handle)

    The trade-off is calibrated: most catalog responses already carry a
    poster URL in meta.poster. Skipping enrichment loses the "promoted"
    Fanart.tv hi-res poster, but for the 60+ items past the visible
    fold the user will scroll past most without ever seeing them.
    Items that DO come into view via scroll keep this lazy art (no
    container refresh trigger), which is an explicit trade-off — the
    speed gain is large enough to justify it.
    """
    fb = fallback_art or {}
    poster = (meta or {}).get('poster') or fb.get('poster') or fb.get('thumb') or ''
    fanart = ((meta or {}).get('background')
              or (meta or {}).get('fanart')
              or fb.get('fanart') or '')
    # v5.10.97: never the provider's logo (see _without_title_logo)
    logo   = (meta or {}).get('clearlogo') or (meta or {}).get('logo') or ''
    art = {
        'poster':   poster,
        'fanart':   fanart,
        'thumb':    poster,
        'icon':     poster,
        'banner':   fanart,
        'landscape': fanart,
        'clearlogo': logo,
    }
    if not _meta_art_is_strict(meta):
        try:
            art = _apply_poster_reliability(art, meta)
        except Exception:
            pass
    if _meta_art_is_strict(meta):
        return art
    try:
        art = _better_posters.apply(
            art, (extract_ids(meta or {}) or {}).get('imdb_id') or '',
            media_type, ADDON)
    except Exception:
        pass
    return art

def _art_slot_targets():
    return {
        'poster': ['poster', 'thumb', 'icon', 'tvshow.poster', 'season.poster'],
        'background': ['fanart'],
        'landscape': ['landscape'],
        'banner': ['banner'],
        'clearlogo': ['clearlogo', 'logo', 'tvshow.clearlogo'],
        'clearart': ['clearart', 'tvshow.clearart'],
    }

def _apply_global_art_priority(art, media_type, meta, current_provider):
    if _meta_art_is_strict(meta):
        return art
    try:
        from . import meta_source as _ms
    except Exception:
        return art
    if _ms.art_configuration_mode() != 'unified':
        return art
    out = None
    meta_id = (meta or {}).get('id') or (meta or {}).get('imdb_id') or ''
    for art_type, slot_keys in _art_slot_targets().items():
        priority = _ms.get_global_art_priority(art_type)
        if not priority:
            continue
        chosen_url = _pick_art_by_priority(
            art_type, priority, media_type, meta_id, meta, current_provider,
        )
        if not chosen_url:
            continue
        if out is None:
            out = dict(art)
        for key in slot_keys:
            out[key] = chosen_url
    return out if out is not None else art

def _apply_bucket_art_priority(art, media_type, meta, current_provider):
    """Walk the configured per-bucket priority list for each art type
    (poster, background, clearlogo) and replace the slot if a higher-
    priority provider has the art available.

    Reads the active bucket from the Window property
    ``dexhub.render_bucket`` set by _hub_render_media_rows().
    """
    if _meta_art_is_strict(meta):
        return art
    try:
        bucket = xbmcgui.Window(WINDOW_ID).getProperty('dexhub.render_bucket') or ''
    except Exception:
        bucket = ''
    if not bucket:
        return art       # no bucket context = not in a folder render → no-op
    try:
        from . import meta_source as _ms
    except Exception:
        return art
    if _ms.art_configuration_mode() != 'custom':
        return art

    # Map our internal art-type names to the keys we set on Kodi ListItems.
    # Multiple keys may correspond to one art type (poster has 5-6 mirrors).
    art_slot_targets = _art_slot_targets()
    # For each art type with a configured priority list, walk it.
    out = None
    meta_id = (meta or {}).get('id') or (meta or {}).get('imdb_id') or ''

    for art_type, slot_keys in art_slot_targets.items():
        priority = _ms.get_bucket_art_priority(bucket, art_type)
        if not priority:
            continue
        chosen_url = _pick_art_by_priority(
            art_type, priority, media_type, meta_id, meta, current_provider,
        )
        if not chosen_url:
            continue
        # Lazy-init the output dict the first time we actually change something
        # — keeps the no-config no-op case allocation-free.
        if out is None:
            out = dict(art)
        for k in slot_keys:
            out[k] = chosen_url
    return out if out is not None else art

def _pick_art_by_priority(art_type, priority_pids, media_type, meta_id, meta, current_provider):
    """For the given art_type, try each provider in priority order until
    one yields a usable URL. Returns '' when nothing matches.

    Resolution order per provider:
      1) The meta we already have on hand (cheapest — zero HTTP cost)
         IF it came from this provider.
      2) The meta_cache for this provider — single SQLite lookup.
      3) Skipped if neither has art (no synchronous HTTP fetch on
         render — we'd be introducing 5-10 round trips per row).

    We accept the trade-off that a provider higher in priority that
    hasn't been fetched yet will silently miss. The bucket prefetch +
    catalog sync paths warm the cache for pinned providers, so for the
    user's actually-configured priority list this is rarely a miss.
    """
    # Map our art_type to the field name in a Stremio meta dict.
    field_map = {
        'poster': 'poster',
        'background': 'background',
        'landscape': 'landscape',
        'banner': 'banner',
        'clearlogo': 'logo',
        'clearart': 'clearart',
    }
    field = field_map.get(art_type)
    if not field:
        return ''

    current_pid = (current_provider or {}).get('id') or ''

    for pid in priority_pids:
        if not pid:
            continue

        # Built-in sources are valid artwork providers too.
        if pid == 'native':
            native_field = {
                'poster': 'poster', 'background': 'background',
                'landscape': 'landscape', 'banner': 'banner',
                'clearlogo': 'clearlogo', 'clearart': 'clearart',
            }.get(art_type, field)
            value = str((meta or {}).get(native_field) or '').strip()
            if not value and art_type == 'background':
                value = str((meta or {}).get('fanart') or '').strip()
            if not value and art_type == 'clearlogo':
                value = str((meta or {}).get('logo') or '').strip()
            if value:
                return value
            continue
        if pid == 'tmdb_helper':
            try:
                from . import meta_source as _ms
                ids = _ms.extract_ids(meta or {})
                helper_meta = _ms._fetch_from_tmdb_helper(ids, meta or {}, media_type) or {}
                aliases = {
                    'poster': ('poster', 'thumbnail', 'thumb'),
                    'background': ('background', 'fanart'),
                    'landscape': ('landscape', 'background', 'fanart'),
                    'banner': ('banner', 'landscape', 'background'),
                    'clearlogo': ('clearlogo', 'logo'),
                    'clearart': ('clearart',),
                }.get(art_type, (field,))
                for alias in aliases:
                    value = str(helper_meta.get(alias) or '').strip()
                    if value:
                        return value
            except Exception:
                pass
            continue

        # ─── Tier 1: meta we already have, if it's from this provider ───
        if pid == current_pid and isinstance(meta, dict):
            url = str(meta.get(field) or '').strip()
            if url:
                return url

        # ─── Tier 2: meta_cache lookup for this provider ───
        try:
            from . import meta_cache as _mc
            cached = _mc.get_one(media_type, pid, meta_id) if meta_id else None
            if cached and isinstance(cached, dict):
                url = str(cached.get(field) or '').strip()
                if url:
                    return url
        except Exception:
            pass

    return ''

def _resolve_meta_art_inner(provider, media_type, meta, fallback_art=None, force_remote=False):
    # If the user explicitly selected a metadata source, the artwork resolver
    # must NOT re-enrich from TMDb/direct afterwards. The meta object reaching
    # this function has already been replaced by meta_source.override_*; render
    # its own artwork exactly as-is. This is what makes "Plexio → Cinemeta",
    # "Plexio → Trakt", or "Plexio → TMDb Helper" affect posters 100%.
    meta_source_id = _meta_source_id_from_meta(meta)
    if _meta_art_is_strict(meta) or (meta_source_id and meta_source_id not in ('auto', 'native')):
        # Strict explicit source: the poster/thumb/icon must come only from the
        # selected metadata payload, including its own background and logo.
        return native_meta_art(meta, media_type, fallback_art={})
    source_id = _provider_meta_source_id(provider)
    if source_id == 'native':
        if _provider_is_plexio(provider):
            return composite_style_meta_art(meta, media_type, fallback_art=fallback_art)
        return native_meta_art(meta, media_type, fallback_art=fallback_art)
    if source_id not in ('', 'auto'):
        return native_meta_art(meta, media_type, fallback_art={})

    if _provider_is_rating_proxy(provider):
        native = native_meta_art(meta, media_type, fallback_art=fallback_art)
        enriched = enrich_meta_art(meta, media_type, fallback_art=fallback_art)
        # ERDB/RPDB must own the vertical poster, while the backdrop should not
        # be replaced by the vertical overlay poster when a better fanart exists.
        for key in ('poster', 'thumb', 'icon', 'thumbnail', 'cover', 'image', 'tvshow.poster', 'season.poster', 'tvshow.thumb'):
            if native.get(key):
                enriched[key] = native.get(key)
        if native.get('clearlogo'):
            for key in ('clearlogo', 'logo', 'tvshow.clearlogo', 'clearart'):
                if native.get(key):
                    enriched[key] = native.get(key)
        has_native_backdrop = any((meta or {}).get(k) for k in ('background', 'fanart', 'backdrop', 'landscape'))
        if has_native_backdrop:
            for key in ('fanart', 'landscape', 'banner'):
                if native.get(key):
                    enriched[key] = native.get(key)
        return enriched

    if force_remote:
        return enrich_meta_art(meta, media_type, fallback_art=fallback_art)
    # Plexio already returns Stremio-ready poster/background URLs from the
    # configured manifest/catalog/meta route. Treat it like Stremio does and
    # render the addon's native artwork in auto mode; otherwise Kodi may swap
    # to TMDb/Helper or leave the tokenized Plex image unwrapped.
    # However, when the poster is NOT an overlay/composite URL (e.g. plain
    # TMDb poster from catalog), use hybrid art so fanart/clearlogo can still
    # be enriched from remote sources.
    if _provider_is_plexio(provider):
        # DPlex/Composite visual behavior: keep the active metadata poster,
        # but fill clearlogo/background from item-native/TMDb Helper artwork.
        return composite_style_meta_art(meta, media_type, fallback_art=fallback_art)
    # Preserve native Plex/Plexio/Emby posters when the user selected
    # "محلي فقط". Their local posters often carry collection/status overlays
    # that disappear when we swap to TMDb art. Tokenized URLs are already
    # wrapped with image:// in native_meta_art(), so they can load reliably.
    if _provider_prefers_native_art(provider):
        if posters_prefer_local():
            return native_meta_art(meta, media_type, fallback_art=fallback_art)
        return enrich_meta_art(meta, media_type, fallback_art=fallback_art)
    if posters_prefer_local():
        return hybrid_meta_art(meta, media_type, fallback_art=fallback_art)
    return enrich_meta_art(meta, media_type, fallback_art=fallback_art)

def _prefer_item_art(art, meta, media_type='movie', fallback_art=None):
    """Merge item-native artwork without breaking the selected art source.

    Remote/TMDb/Trakt art wins when local posters are not preferred; native
    provider art then only fills missing fields. When local posters are enabled,
    native Plex/Emby/Plexio art may override.
    """
    if _meta_art_is_strict(meta):
        merged = dict(art or {})
        if merged.get('clearlogo'):
            merged['logo'] = merged.get('clearlogo')
            merged['tvshow.clearlogo'] = merged.get('clearlogo')
            merged['clearart'] = merged.get('clearlogo')
        return merged
    merged = dict(art or {})
    try:
        native = native_meta_art(meta or {}, media_type, fallback_art=fallback_art or {}) or {}
    except Exception:
        native = {}
    prefer_native = posters_prefer_local()
    for key in ('poster', 'thumb', 'icon', 'fanart', 'landscape', 'banner', 'clearlogo', 'logo', 'tvshow.clearlogo', 'clearart'):
        value = native.get(key)
        if not value:
            continue
        if prefer_native or not merged.get(key):
            merged[key] = value
    if merged.get('clearlogo'):
        merged['logo'] = merged.get('clearlogo')
        merged['tvshow.clearlogo'] = merged.get('clearlogo')
        merged['clearart'] = merged.get('clearlogo')
    if merged.get('poster') and not merged.get('fanart'):
        merged['fanart'] = merged.get('poster')
    if merged.get('fanart') and not merged.get('landscape'):
        merged['landscape'] = merged.get('fanart')
    return merged

def _item_fallback_art(provider=None, media_type='movie', catalog=None, name=''):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    pname = provider.get('name') or manifest.get('name') or 'Provider'
    base_art = provider_art(pname, manifest, base_url=provider.get('base_url') or '')
    # Use the addon/provider poster for catalog items when item art is missing.
    # Category icons like 4K/search are fine for catalog folders, but not for movie/series posters.
    if catalog:
        cat_art = catalog_art(name or catalog.get('name') or catalog.get('id') or media_type, media_type, manifest, catalog)
        merged = dict(base_art)
        # Keep fanart/background hints from the catalog when available, but poster/icon from provider.
        for key in ('fanart', 'landscape', 'banner'):
            if cat_art.get(key):
                merged[key] = cat_art.get(key)
        return _without_title_logo(merged)
    return _without_title_logo(base_art)


def _without_title_logo(art):
    """v5.10.97: an item never inherits its add-on's logo as its title logo.

    Fallback art stands in for a movie or show that has none of its own; the
    provider's logo in the clearlogo slot made every such title (and the
    source search screen opened for it) show the add-on's logo instead of
    the title's own logo or name.
    """
    art = dict(art or {})
    for key in ('clearlogo', 'tvshow.clearlogo', 'logo', 'clearart'):
        art.pop(key, None)
    return art

def _content_background(art=None, fallback=None):
    art = art or {}
    fallback = fallback or {}
    return (
        art.get('fanart') or art.get('landscape') or art.get('banner') or art.get('poster') or art.get('thumb') or
        fallback.get('fanart') or fallback.get('landscape') or fallback.get('poster') or fallback.get('thumb') or
        addon_fanart()
    )

def _bucket_meta_map_path():
    return os.path.join(_profile_path(), 'bucket_meta_map.json')

def _load_bucket_meta_map():
    try:
        with xbmcvfs.File(_bucket_meta_map_path(), 'r') as fh:
            data = fh.read()
        return json.loads(data) if data else {}
    except Exception:
        return {}

def get_bucket_meta_source(bucket):
    """Return the meta source override for a bucket, or empty string
    if no override is set (caller should fall back to provider-level
    or global default)."""
    if not bucket:
        return ''
    return (_load_bucket_meta_map() or {}).get(bucket, '')

