def _meta_rating_value(meta):
    meta = meta or {}
    for key in ('imdbRating', 'rating', 'voteAverage', 'score'):
        value = meta.get(key)
        try:
            if value not in (None, ''):
                return float(str(value).replace(',', '.'))
        except Exception:
            continue
    return 0.0

_PLEX_SERVERS_MEMO = {'at': 0.0, 'servers': None}

_PLEX_SERVERS_MEMO_TTL = 300.0

def _plex_servers_budgeted(budget_seconds=2.5, down_memo_seconds=90.0):
    """plex_client.servers() under a hard wall-clock budget, with a down-memo.

    v3.9.241 (kodi.log 2026-07-14): with the Plex box unreachable,
    servers() + servers(force=True) burned ~60s EACH against dead endpoints —
    121s ON THE DISPATCH THREAD before the source picker could appear. The
    user kept pressing resume while waiting, and every press paid the same
    121s and then opened ITS OWN picker: the stacked-dialogs symptom.

    The fetch now runs in a worker joined for `budget_seconds`; on timeout or
    error the server is memoised as down for `down_memo_seconds`, so the NEXT
    press skips Plex instantly instead of re-paying. The worker communicates
    through a private dict — it never touches shared lists after the join, so
    a late finisher cannot race the picker build. Success clears the memo.

    v5.10.15: a SUCCESSFUL discovery is now memoised too. The kodi.log for
    5.10.14 shows this call costing 3.19s on the first search after boot and
    ~0.19s afterwards — it runs before the loading screen is drawn, so the
    user stares at a black screen for its whole duration. The server list is
    stable for minutes at a time, so a 5-minute positive memo removes that
    cost from every search but the first. The budget also drops from 6s to
    2.5s: a LAN Plex server that has not answered in 2.5s is not going to make
    this search useful, and its own target still gets a full try inside the
    scan where it belongs.
    """
    now = time.time()
    memo_at = float(_PLEX_SERVERS_MEMO.get('at') or 0.0)
    memo_servers = _PLEX_SERVERS_MEMO.get('servers')
    if memo_servers is not None and (now - memo_at) < _PLEX_SERVERS_MEMO_TTL:
        # v5.10.198: an account linked or removed in another invocation
        # since this memo (server_accounts) is not answered from it
        from . import server_accounts as _accounts
        if _accounts.stamp() <= memo_at:
            return list(memo_servers)

    try:
        down_until = float(xbmcgui.Window(10000).getProperty('dexhub.plex.down_until') or 0.0)
    except Exception:
        down_until = 0.0
    if now < down_until:
        xbmc.log('[DexHub] Plex Native targets skipped: marked down for %.0fs more'
                 % (down_until - now), xbmc.LOGINFO)
        return []

    out = {}

    def _worker():
        try:
            srv = plex_client.servers()
            if not srv:
                srv = plex_client.servers(force=True)
            out['servers'] = srv or []
        except Exception as exc:
            out['exc'] = exc

    try:
        t = threading.Thread(
            target=_worker, name='DexHubPlexServers', daemon=True)
        t.start()
    except RuntimeError as exc:
        xbmc.log('[DexHub] Plex discovery worker unavailable: %s' % exc,
                 xbmc.LOGWARNING)
        try:
            xbmcgui.Window(10000).setProperty(
                'dexhub.plex.down_until',
                str(time.time() + down_memo_seconds),
            )
        except Exception:
            pass
        return []
    t.join(budget_seconds)
    if t.is_alive() or out.get('exc'):
        reason = out.get('exc') or ('no reply within %.0fs' % budget_seconds)
        xbmc.log('[DexHub] Plex Native target discovery failed: %s' % reason,
                 xbmc.LOGWARNING)
        try:
            xbmcgui.Window(10000).setProperty(
                'dexhub.plex.down_until', str(time.time() + down_memo_seconds))
        except Exception:
            pass
        return []
    try:
        xbmcgui.Window(10000).setProperty('dexhub.plex.down_until', '')
    except Exception:
        pass
    _servers = out.get('servers') or []
    # Positive memo: only a successful discovery is cached, so a transient
    # failure still retries on the next search instead of being remembered.
    _PLEX_SERVERS_MEMO['servers'] = list(_servers)
    _PLEX_SERVERS_MEMO['at'] = time.time()
    return _servers

