_ART_WARM_SEEN = set()

_ART_WARM_LOCK = threading.Lock()

def _warm_server_art(tmdb_id, imdb_id, media_type, title, year):
    """Resolve TMDb art in the background so the NEXT render is a cache hit."""
    key = '%s|%s|%s' % (media_type, tmdb_id, imdb_id)
    with _ART_WARM_LOCK:
        if key in _ART_WARM_SEEN or len(_ART_WARM_SEEN) > 400:
            return
        _ART_WARM_SEEN.add(key)

    def _run():
        try:
            _tmdb_direct.art_for(tmdb_id=tmdb_id, imdb_id=imdb_id,
                                 media_type=media_type, title=title, year=year)
        except Exception:
            pass

    _submit_optional(_run, key='art:%s' % key)

def _server_meta_source(backend):
    """Resolve the meta-source policy for a Plex/Emby server row.

    The server backends are treated as first-class meta targets ('plex_server' /
    'emby_server'), so they obey the SAME policy as everything else:

        per-server override  ->  global `default_meta_source`

    'native' means "keep the server's own artwork" — which is what you want when
    a library has custom posters, overlays (4K/HDR/Atmos badges), or bespoke art
    that TMDb simply does not have.
    """
    target = 'emby_server' if backend in ('emby', 'jellyfin') else 'plex_server'
    try:
        return (_meta_source.get_meta_source_for(target) or 'auto')
    except Exception:
        return 'auto'

def _server_tmdb_art(item, fallback, backend='plex'):
    """Resolve Plex/Emby row art according to the meta-source policy.

    Why (v3.9.232): server art means one AUTHENTICATED request per tile against
    the user's own — often remote — box. That is slow, and nothing else in Kodi
    can reuse it. TMDb art is a canonical image.tmdb.org URL, byte-identical to
    what TMDb Helper requests, so Kodi's TEXTURE CACHE is shared: titles TMDb
    Helper has already drawn paint instantly here, and posters are w500 (~70 KB)
    instead of a full-size server transcode.

    v3.9.234: this now honours `default_meta_source` (and a per-server override)
    instead of a separate boolean, so picking "TMDb Helper" once applies to the
    WHOLE addon — Stremio catalogs and Plex/Emby libraries alike. Choose
    'native' for a server whose posters carry overlays you want to keep.

    This never blocks the listing: only CACHED art is used on the render path;
    on a miss the server art is kept for this pass and TMDb is warmed in the
    background so the next visit is instant.
    """
    source_id = _server_meta_source(backend)
    # 'native' = the server's own art wins (custom posters / overlays / badges).
    if source_id == 'native':
        return fallback
    # Legacy escape hatch: the old boolean still force-disables the TMDb path.
    if not _setting_bool('server_art_from_tmdb', True):
        return fallback

    ids = item.get('ids') or {}
    tmdb_id = str(ids.get('tmdb_id') or '').strip()
    imdb_id = str(ids.get('imdb_id') or '').strip()
    if not tmdb_id and not imdb_id:
        return fallback

    media = item.get('media_type') or 'movie'
    if media in ('season', 'episode'):
        # v5.10.107: a season's or an episode's own ids (Plex and Emby give
        # them their own) name no show on TMDb: looked up as a show they
        # brought another show's art. They keep the server's own art.
        return fallback
    # Seasons/episodes inherit the SHOW poster: TMDb per-episode stills are not
    # what these rows want, and the show poster is what the user recognises.
    mt = 'tv' if media in ('show', 'season', 'episode') else 'movie'
    _title = item.get('raw_title') or item.get('title') or ''
    _year = item.get('year') or ''
    # v5.10.198: the server first (Settings, Metadata: Servers' metadata):
    # its own poster, backdrop and logo stay, TMDb fills only what it lacks;
    # a title with all three is not looked up at all
    from .meta_policy import server_first as _server_first
    keep = _server_first()
    if keep and all((fallback or {}).get(key) for key in ('poster', 'fanart', 'clearlogo')):
        return fallback

    # TIER 1 — TMDb Helper's OWN SQLite cache (ItemDetails.db), opened read-only.
    # This is the lightest possible source: no network, no API key, no second
    # copy of the data. Anything TMDb Helper has already browsed is served from
    # its own DB, and because the URLs it stores rebuild to the exact same
    # image.tmdb.org/t/p/w500 paths, Kodi's texture cache is shared too — those
    # posters are usually ALREADY on disk and paint with no download at all.
    bundle = {}
    try:
        bundle = _tmdb_art_db.get_art_bundle_from_db(
            tmdb_id=tmdb_id, media_type=mt, imdb_id=imdb_id,
            title=_title, year=_year) or {}
    except Exception:
        bundle = {}

    # TIER 2 — Dex Hub's own TMDb cache, cached-only (never blocks the listing).
    # This is a GAP-FILLER, not a contradiction of a 'tmdb_helper' choice: both
    # tiers resolve to identical image.tmdb.org URLs, so a title TMDb Helper has
    # not browsed yet still gets TMDb art instead of falling back to a heavy
    # server transcode. Only 'native' keeps the server's own artwork.
    if not bundle.get('poster'):
        try:
            bundle = _tmdb_direct.art_cached_only(
                tmdb_id=tmdb_id, imdb_id=imdb_id, media_type=mt,
                title=_title, year=_year) or {}
        except Exception:
            bundle = {}

    if keep and (bundle.get('poster') or bundle.get('fanart') or bundle.get('clearlogo')):
        out = dict(fallback or {})
        if bundle.get('poster') and not out.get('poster'):
            out['poster'] = out['thumb'] = out['icon'] = bundle['poster']
        if bundle.get('fanart') and not out.get('fanart'):
            out['fanart'] = bundle['fanart']
            if not out.get('landscape') or out.get('landscape') in (out.get('poster'), out.get('thumb')):
                out['landscape'] = bundle['fanart']
        if bundle.get('clearlogo') and not out.get('clearlogo'):
            out['clearlogo'] = bundle['clearlogo']
        if not all(out.get(key) for key in ('poster', 'fanart', 'clearlogo')):
            _warm_server_art(tmdb_id, imdb_id, mt, _title, _year)
        return out
    if bundle.get('poster') and not keep:
        out = dict(fallback or {})
        out['poster'] = bundle['poster']
        out['thumb'] = bundle['poster']
        out['icon'] = bundle['poster']
        if bundle.get('fanart'):
            out['fanart'] = bundle['fanart']
            out['landscape'] = bundle['fanart']
        if bundle.get('clearlogo'):
            out['clearlogo'] = bundle['clearlogo']
        return out

    # Both cached tiers missed: keep the server art for THIS render (never
    # block a listing) and warm Dex Hub's TMDb cache off-thread so the next
    # visit is instant. TMDb Helper's DB fills itself as the user browses it.
    _warm_server_art(tmdb_id, imdb_id, mt, _title, _year)
    return fallback

def _plex_item_art(item):
    # v5.10.82, after DPlex: posters fitted by the server (720 box, JPEG),
    # backdrops capped at 1080p, and Plex's own clearLogo, with
    # tvshow.clearlogo for episodes so Arctic Fuse 3 shows the show's logo.
    poster = plex_client.poster_url(item, item.get('thumb') or item.get('parent_thumb') or '', 720, 720)
    fanart = plex_client.poster_url(item, item.get('art') or item.get('thumb') or '', 1920, 1080)
    clearlogo = plex_client.artwork_url(item, item.get('clear_logo') or '')
    fallback = {'poster': poster, 'thumb': poster, 'fanart': fanart, 'landscape': fanart}
    if clearlogo:
        fallback['clearlogo'] = clearlogo
    art = _server_tmdb_art(item, fallback, backend='plex')
    if clearlogo and isinstance(art, dict):
        if not art.get('clearlogo'):
            art = dict(art, clearlogo=clearlogo)
        if item.get('media_type') == 'episode' and not art.get('tvshow.clearlogo'):
            art = dict(art, **{'tvshow.clearlogo': art.get('clearlogo') or clearlogo})
    inherit = item.get('_show_art') if isinstance(item.get('_show_art'), dict) else None
    if inherit and isinstance(art, dict) and item.get('media_type') in ('season', 'episode'):
        # v5.10.107: a show's seasons and episodes carry its logo, poster and
        # backdrop, so a skin's season and episode views show them
        art = dict(art)
        logo = inherit.get('clearlogo') or ''
        if logo:
            art.setdefault('tvshow.clearlogo', logo)
            if not art.get('clearlogo'):
                art['clearlogo'] = logo
        if inherit.get('poster'):
            art.setdefault('tvshow.poster', inherit['poster'])
        if inherit.get('fanart'):
            art.setdefault('tvshow.fanart', inherit['fanart'])
            if not art.get('fanart'):
                art['fanart'] = inherit['fanart']
    return art

def _fill_art(art, more):
    """``art`` with the keys it lacks taken from ``more``."""
    out = dict(more or {})
    out.update(dict((k, v) for k, v in (art or {}).items() if v))
    return out


def _server_open_art(item, backend, server, ui_seed_key='', show_ids=None, show_item=None,
                     network=True):
    """(poster, fanart, clearlogo) of a server title being opened (v5.10.107).

    The Home's own art first (what its page showed, handed over by a cache
    key, so no server address or token travels in the plugin URL), then the
    server's (the same as the title's library row: its poster, backdrop and
    clear logo, or TMDb's cached art where the meta-source policy prefers
    it), then TMDb's for what is still missing: a logo or a poster the server
    lacks, looked up by the title's ids, cached first and, with ``network``
    (the sources window, not a direct play that would wait for it), one short
    request at most. A season or an episode is looked up by its show's ids
    only: Plex gives them ids of their own, which name no show on TMDb.
    v5.10.108: ``network='async'`` asks TMDb without waiting for the answer
    (it is cached for the next time): the sources window opens at once.
    """
    seed = _ui_seed_from_route(ui_seed_key=ui_seed_key) if ui_seed_key else {}
    poster = str(seed.get('ui_poster') or '')
    fanart = str(seed.get('ui_fanart') or '')
    logo = str(seed.get('ui_clearlogo') or '')
    episode = item.get('media_type') in ('episode', 'season')
    try:
        if backend == 'plex':
            art = _plex_item_art(item) or {}
        elif backend == 'silo':
            art = {'poster': item.get('thumb') or '', 'fanart': item.get('art') or '',
                   'clearlogo': item.get('logo') or ''}
        else:
            art = dict(item.get('artwork') or {})
    except Exception:
        art = {}
    if show_item:
        # an episode: its show's logo, poster and backdrop
        try:
            if backend == 'plex':
                show_art = _plex_item_art(show_item) or {}
            elif backend == 'silo':
                show_art = {'poster': show_item.get('thumb') or '', 'fanart': show_item.get('art') or '',
                            'clearlogo': show_item.get('logo') or ''}
            else:
                show_art = dict(show_item.get('artwork') or {})
        except Exception:
            show_art = {}
        art.setdefault('tvshow.clearlogo', show_art.get('clearlogo') or '')
        art.setdefault('tvshow.poster', show_art.get('poster') or '')
        if not art.get('fanart'):
            art['fanart'] = show_art.get('fanart') or ''
    poster = poster or (art.get('tvshow.poster') if episode else '') or art.get('poster') or ''
    fanart = fanart or art.get('fanart') or ''
    # an episode's own logo would be one from its own (non-show) ids: the
    # show's logo only
    logo = logo or (art.get('tvshow.clearlogo') if episode else art.get('clearlogo')) or ''
    if logo and poster and fanart:
        return poster, fanart, logo
    ids = dict(show_ids or {}) if episode else dict(item.get('ids') or {})
    tmdb_id = str(ids.get('tmdb_id') or '').strip()
    imdb_id = str(ids.get('imdb_id') or '').strip()
    if not (tmdb_id or imdb_id):
        return poster, fanart, logo
    mt = 'tv' if (episode or item.get('media_type') == 'show') else 'movie'
    title = (item.get('show_title') if episode else item.get('raw_title') or item.get('title')) or ''
    year = '' if episode else str(item.get('year') or '')
    found = {}
    try:
        found = _tmdb_art_db.get_art_bundle_from_db(tmdb_id=tmdb_id, media_type=mt, imdb_id=imdb_id,
                                                    title=title, year=year) or {}
    except Exception:
        found = {}
    if not found.get('clearlogo') or not found.get('poster'):
        try:
            cached = _tmdb_direct.art_cached_only(tmdb_id=tmdb_id, imdb_id=imdb_id, media_type=mt,
                                                  title=title, year=year) or {}
        except Exception:
            cached = {}
        found = _fill_art(found, cached)
    if network and (not found.get('clearlogo') or not found.get('poster')):
        box = {}

        def _fetch():
            try:
                box['art'] = _tmdb_direct.art_for(tmdb_id=tmdb_id, imdb_id=imdb_id, media_type=mt,
                                                  title=title, year=year) or {}
            except Exception:
                box['art'] = {}
        worker = threading.Thread(target=_fetch, name='dexhub-open-art')
        worker.daemon = True
        worker.start()
        if network != 'async':
            worker.join(2.5)    # the request stays cached for the next time if it is late
            found = _fill_art(found, box.get('art') or {})
    poster = poster or str(found.get('poster') or '')
    fanart = fanart or str(found.get('fanart') or '')
    logo = logo or str(found.get('clearlogo') or '')
    return poster, fanart, logo


def _library_dexhub_play(item, backend, server, ui_seed_key=''):
    """Explicit library route: do not let same-source autoplay override it."""
    ids = dict(item.get('ids') or {})
    episode = item.get('media_type') == 'episode'
    show_item = None
    if episode:
        parent = item.get('series_id') or item.get('show_rating_key')
        if parent:
            try:
                show_item = _server_client(backend).metadata(server, parent)
                ids = show_item.get('ids') or ids
            except Exception:
                pass
    canonical = ids.get('imdb_id') or ('tmdb:%s' % ids['tmdb_id'] if ids.get('tmdb_id') else '')
    if not canonical:
        return error(tr('لا يوجد معرّف للعمل للبحث في Dex Hub'))
    # v5.10.107: the sources window opens with the title's own logo and art
    # (the Home's, the server's or TMDb's), not whatever its meta lookup finds
    try:
        poster, fanart, logo = _server_open_art(item, backend, server, ui_seed_key=ui_seed_key,
                                                show_ids=ids if (episode and show_item) else None,
                                                show_item=show_item, network='async')
    except Exception:
        poster, fanart, logo = '', '', ''
    seed = {'ui_fanart': fanart, 'ui_clearlogo': logo}
    if not episode:
        seed['ui_poster'] = poster      # an episode keeps its show's poster from the show's meta
    seed = dict((k, v) for k, v in seed.items() if v)
    common = dict(title=item.get('show_title') if episode else item.get('raw_title') or item.get('title'),
                  seed_ids=ids, resume_seconds=float(item.get('resume_ms' if backend == 'silo' else 'view_offset_ms') or 0) / 1000,
                  ui_seed=seed or None)
    if episode:
        return episode_streams(canonical, '%s:%s:%s' % (canonical, item.get('season'), item.get('index')),
                               item.get('season'), item.get('index'), **common)
    return streams('movie', canonical, **common)

def plex_play(server_id, rating_key, force_native=False, ui_seed_key='', preferred_version='', resume_seconds=None):
    """Resolve fresh Plex metadata, then Direct Play with companion progress.

    v5.10.107: ``ui_seed_key`` hands over the art the Home showed for the
    title; the player (and the sources window) get its clear logo too.
    """
    try:
        server = _plex_server(server_id)
        item = plex_client.metadata(server, rating_key)
    except Exception as exc:
        return _plex_error(exc)
    from .library_mode import library_direct as _library_direct
    if not force_native and not _library_direct(ADDON):
        return _library_dexhub_play(item, 'plex', server, ui_seed_key=ui_seed_key)
    part_key = ''
    selected_version = {}
    versions = [v for v in (item.get('versions') or []) if v.get('part_key')]
    from .playback_choices import saved_version
    selected_version = saved_version(versions, preferred_version, ('part_key',))
    if selected_version:
        part_key = selected_version.get('part_key') or ''
    elif len(versions) > 1:
        # DPlex-style version picker: poster + resolution/HDR/size per row.
        poster = plex_client.artwork_url(item, item.get('thumb') or '')
        try:
            rows = []
            for i, v in enumerate(versions):
                li = xbmcgui.ListItem(item.get('raw_title') or item.get('title') or 'Plex')
                try:
                    li.setLabel2(v.get('version_label') or 'Version %d' % (i + 1))
                    if poster:
                        li.setArt({'icon': poster, 'thumb': poster, 'poster': poster})
                except Exception:
                    pass
                rows.append(li)
            choice = xbmcgui.Dialog().select(tr('اختر النسخة'), rows, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(
                tr('اختر النسخة'), [v.get('version_label') or '?' for v in versions])
        if choice < 0:
            return
        selected_version = versions[choice]
        part_key = selected_version.get('part_key') or ''
    elif versions:
        selected_version = versions[0]
        part_key = selected_version.get('part_key') or ''
    try:
        stream_url = plex_client.playback_url(item, part_key=part_key)
    except Exception as exc:
        return _plex_error(exc)
    ids = item.get('ids') or {}
    media_type = item.get('media_type') or 'movie'
    show_ids = {}
    show_item = None
    if media_type == 'episode' and item.get('show_rating_key'):
        try:
            show_item = plex_client.metadata(server, item.get('show_rating_key'))
            show_ids = show_item.get('ids') or {}
        except Exception as exc:
            xbmc.log('[DexHub][TheIntroDB] Plex show identity unavailable: %s' % exc,
                     xbmc.LOGWARNING)
    try:
        _open_poster, _open_fanart, _open_logo = _server_open_art(
            item, 'plex', server, ui_seed_key=ui_seed_key,
            show_ids=show_ids if media_type == 'episode' else None, show_item=show_item, network=False)
    except Exception:
        _open_poster, _open_fanart, _open_logo = '', '', ''
    # v3.9.206: content that exists ONLY on the user's server — a Turkish
    # series with no IMDb/TMDb entry, a home recording, a rare release — used
    # to end up with an EMPTY canonical_id here. Everything downstream keys on
    # it: the playback session, the resume point, the switch-source index. So
    # the item played once and could never be resumed. A stable, namespaced
    # fallback fixes all of that without touching identified content.
    canonical_id = (ids.get('imdb_id')
                    or ('tmdb:%s' % ids.get('tmdb_id') if ids.get('tmdb_id') else '')
                    or 'plex:%s:%s' % (server_id, rating_key))
    if not canonical_id:
        canonical_id = 'plex:%s:%s' % (server_id, rating_key)
    ctx = {
        'stream_url': stream_url,
        'stream_key': 'plex:%s:%s' % (server_id, rating_key),
        'server_id': str(server_id), 'part_key': part_key,
        'provider_id': 'plex_native', 'provider_name': 'Plex Native • %s' % (server.get('name') or 'Server'),
        'server_type': 'plex', 'server_url': item.get('server_url') or '',
        'token': item.get('token') or server.get('token') or '',
        'rating_key': str(rating_key), 'client_id': plex_client.client_identifier(),
        'product': 'Dex Hub', 'product_version': ADDON.getAddonInfo('version') or '3.9.202', 'device_name': 'Kodi',
        'canonical_id': canonical_id, 'video_id': str(rating_key),
        'media_type': 'series' if media_type in ('show', 'season', 'episode') else 'movie',
        'title': item.get('raw_title') or item.get('title') or 'Plex',
        'show_title': item.get('show_title') or '',
        'year': item.get('year') or 0, 'plot': item.get('summary') or '',
        'duration_ms': item.get('duration_ms') or 0,
        'duration': int((item.get('duration_ms') or 0) / 1000),
        'resume_seconds': float(resume_seconds) if resume_seconds is not None else __import__('resources.lib.resume_policy', fromlist=['newest_seconds']).newest_seconds(item, 'plex'),
        'season': item.get('season') or 0, 'episode': item.get('index') or 0,
        'poster': _open_poster or plex_client.artwork_url(item, item.get('thumb') or ''),
        'background': _open_fanart or plex_client.artwork_url(item, item.get('art') or item.get('thumb') or ''),
        'clearlogo': _open_logo,
        'imdb_id': _normalize_imdb_id(ids.get('imdb_id')) or '', 'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'show_imdb_id': _normalize_imdb_id(show_ids.get('imdb_id')) or '',
        'show_tmdb_id': show_ids.get('tmdb_id') or '',
        'show_tvdb_id': show_ids.get('tvdb_id') or '',
        'subtitles': list(selected_version.get('subtitles') or []),
    }
    return _play_with_context(ctx, stream_key=ctx['stream_key'], use_resolved_url=False)

def _emby_error(exc):
    notify('Emby: %s' % exc)

def _silo_error(exc):
    notify('Silo: %s' % exc)

def _silo_server():
    rows = silo_client.servers()
    if not rows:
        raise Exception('لم يتم ربط Silo بعد')
    return rows[0]

_SILO_SECTION_ART = {}

_SILO_ART_BUDGET = 4.0

def _silo_art(item):
    poster = str(item.get('thumb') or '')
    fanart = str(item.get('art') or poster)
    logo = str(item.get('logo') or '')
    art = {'poster': poster, 'thumb': poster, 'icon': poster,
           'fanart': fanart, 'landscape': fanart}
    if logo:
        art['clearlogo'] = logo
        art['logo'] = logo
    return art

def silo_play(item_id, server=None, force_native=False, resume_seconds=None, ui_seed_key='', preferred_version=''):
    try:
        server = server or _silo_server()
        item = silo_client.metadata(server, item_id)
        from .library_mode import library_direct as _library_direct
        if not force_native and not _library_direct(ADDON):
            return _library_dexhub_play(item, 'silo', server, ui_seed_key=ui_seed_key)
        versions = list(item.get('versions') or [])
        from .playback_choices import saved_version
        selected = saved_version(versions, preferred_version, ('media_source_id','file_id'))
        if not selected and len(versions) > 1:
            labels = [v.get('info_line') or v.get('file') or ('Version %d' % (i + 1))
                      for i, v in enumerate(versions)]
            choice = xbmcgui.Dialog().select(tr('اختر النسخة'), labels)
            if choice < 0:
                return
            selected = versions[choice]
        elif not selected:
            selected = versions[0] if versions else {}
        resolved = silo_client.resolve_playback(
            server, item_id, selected.get('media_source_id') or selected.get('file_id') or '',
            start_position=(resume_seconds if resume_seconds is not None else (item.get('resume_ms') or 0) / 1000))
    except Exception as exc:
        return _silo_error(exc)
    ids = item.get('ids') or {}
    show_ids = {}
    show_item = None
    if item.get('media_type') == 'episode' and item.get('series_id'):
        try:
            show_item = silo_client.metadata(server, item.get('series_id'))
            show_ids = (show_item.get('ids') or {})
        except Exception:
            pass
    try:
        _open_poster, _open_fanart, _open_logo = _server_open_art(
            item, 'silo', server, ui_seed_key=ui_seed_key,
            show_ids=show_ids if item.get('media_type') == 'episode' else None, show_item=show_item,
            network=False)
    except Exception:
        _open_poster, _open_fanart, _open_logo = '', '', ''
    # v5.10.170: an episode is keyed on its SERIES. Silo gives episodes ids of
    # their own; used as the work id they sent subtitle searches (DexSubtitles,
    # Stremio subtitle add-ons) "tt<episode>:S:E", which matches nothing.
    _is_ep = item.get('media_type') == 'episode'
    _work = ({'imdb_id': show_ids.get('imdb_id') or '', 'tmdb_id': show_ids.get('tmdb_id') or '',
              'tvdb_id': show_ids.get('tvdb_id') or ''} if _is_ep else ids)
    ctx = {
        'media_type': 'series' if _is_ep else 'movie',
        'canonical_id': (_normalize_imdb_id(_work.get('imdb_id')) or
                         ('tmdb:%s' % _work.get('tmdb_id') if _work.get('tmdb_id') else 'silo:%s' % item_id)),
        'video_id': str(item_id), 'item_id': str(item_id),
        'title': item.get('title') or 'Silo', 'show_title': item.get('show_title') or '',
        'stream_url': resolved.get('url') or '', 'provider_id': 'silo_native',
        'provider_name': 'Silo Native • %s' % (server.get('name') or 'Server'),
        'server_type': 'silo', 'server_url': server.get('url') or '',
        'server_id': str(server.get('id') or ''),
        'resume_seconds': float(resume_seconds if resume_seconds is not None else
                                (item.get('resume_ms') or 0) / 1000),
        'token': server.get('token') or '', 'session_id': resolved.get('play_session_id') or '',
        'media_source_id': resolved.get('media_source_id') or '',
        'native_playback_resolved': True, 'poster': _open_poster or item.get('thumb') or '',
        'background': _open_fanart or item.get('art') or item.get('thumb') or '', 'logo': item.get('logo') or '',
        'clearlogo': _open_logo or item.get('logo') or '',
        'duration_ms': item.get('duration_ms') or 0,
        'duration': int((item.get('duration_ms') or 0) / 1000),
        'season': item.get('season') or None, 'episode': item.get('index') or None,
        'imdb_id': _normalize_imdb_id(_work.get('imdb_id')) or '',
        'tmdb_id': _work.get('tmdb_id') or '', 'tvdb_id': _work.get('tvdb_id') or '',
        'show_imdb_id': _normalize_imdb_id(show_ids.get('imdb_id')) or '',
        'show_tmdb_id': show_ids.get('tmdb_id') or '',
        'show_tvdb_id': show_ids.get('tvdb_id') or '',
        'subtitles': list((resolved.get('version') or selected).get('subtitles') or []),
        'silo_session': resolved.get('silo_session') or {},
    }
    ctx['stream_key'] = cache_store.put('stream', {
        'stream_url': ctx['stream_url'], 'name': ctx['title'],
        'provider_name_raw': ctx['provider_name'],
        'size_label': (resolved.get('version') or selected).get('size_label') or '',
        'subtitles': ctx['subtitles'],
    })
    return _play_with_context(ctx, stream_key=ctx['stream_key'], use_resolved_url=False)

def _emby_server():
    servers = emby_client.servers()
