def _stream_badges(video_bits, audio_bits, subtitles):
    wanted = ['2160P', '1080P', '720P', 'DV', 'HDR10+', 'HDR10', 'HDR', 'HEVC', 'AV1', 'ATMOS', 'TRUEHD', 'DTS-HD', 'DTS-X', 'DD+', 'DD', '5.1', '7.1', 'MULTI', 'DUBBED', 'SUBS']
    available = [str(x).upper() for x in (video_bits or []) + (audio_bits or [])]
    tags = []
    for key in wanted:
        if key in available and key not in tags:
            tags.append(key)
    if subtitles and 'SUBS' not in tags:
        tags.append('SUBS')
    return ' • '.join(tags[:8])

def _tags_from_fact_lists(video_bits, audio_bits, row=None):
    """Build the UI tag contract from already parsed values; no regex pass."""
    video = [str(x or '').upper() for x in (video_bits or [])]
    audio = [str(x or '').upper() for x in (audio_bits or [])]
    tags = {}
    source = []
    for marker in ('REMUX', 'BLURAY', 'WEB-DL', 'WEBDL', 'WEBRIP', 'HDTV', 'DVD', 'CAM'):
        if any(marker in value for value in video):
            source.append(marker)
    encode = [x for x in video if x in ('HEVC', 'H264', 'H.264', 'AVC', 'AV1', 'XVID')]
    visual = [x for x in video if x in ('DV', 'HDR10+', 'HDR10', 'HDR', 'HLG', 'IMAX', '10BIT', '3D')]
    audio_codec = [x for x in audio if x in ('ATMOS', 'TRUEHD', 'DTS-X', 'DTS-HD MA', 'DTS-HD', 'DTS', 'DD+', 'DD', 'AC3', 'FLAC', 'AAC', 'OPUS')]
    channels = [x for x in audio if x in ('7.1', '5.1', '2.0', '8CH')]
    if source:
        tags['source'] = source[:1]
    if encode:
        tags['encode'] = encode[:1]
    if visual:
        tags['visual'] = visual[:3]
    if audio_codec:
        tags['audio'] = audio_codec[:2]
    if channels:
        tags['channels'] = channels[:1]

    langs = []
    for value in _iter_stream_values((row or {}).get('languages')):
        clean = MULTI_WS_RE.sub(' ', str(value or '')).strip()
        if clean and clean not in langs:
            langs.append(clean)
    for token, label in (('ARABIC', 'عربي'), ('ENGLISH', 'EN'),
                         ('RUSSIAN', 'RU'), ('MULTI', 'Multi')):
        if token in audio and label not in langs:
            langs.append(label)
    if langs:
        tags['languages'] = langs[:4]
    return tags

def _source_type_from_formatter(value):
    raw = str(value or '').strip().lower()
    if 'usenet' in raw or raw in ('nzb', 'nntp'):
        key = 'usenet'
    elif 'debrid' in raw:
        key = 'debrid'
    elif raw in ('p2p', 'torrent') or 'torrent' in raw:
        key = 'torrent'
    elif raw:
        key = 'direct'
    else:
        return None
    return (key,) + _SOURCE_TYPE_STYLES[key]

def _stream_facts(row, provider_name, provider_origin=''):
    row = row or {}
    hints = row.get('behaviorHints') or {}
    formatted = _parse_formatter_fields(row)
    provider_domain = ''
    safe_provider_origin = ''
    safe_provider_origin = _safe_http_origin(provider_origin)
    try:
        provider_domain = urlparse(safe_provider_origin).netloc
    except Exception:
        provider_domain = ''
    if provider_domain.startswith('www.'):
        provider_domain = provider_domain[4:]
    addon_url = ''
    addon_domain = ''

    if formatted:
        # Fast AIOStreams path: use its parsed formatter values directly.
        display_name = (formatted.get('file') or
                        ((hints.get('filename') if isinstance(hints, dict) else '') or '') or
                        formatted.get('title') or _stream_display_name(row))
        video_bits = _formatter_fact_list(formatted.get('video'))
        audio_bits = _formatter_fact_list(formatted.get('audio'))
        size = _extract_size(formatted.get('size')) or str(formatted.get('size') or '').strip()
        addon_name = _normalize_ascii(formatted.get('source') or formatted.get('addon') or '')
        addon_name = addon_name.upper() if addon_name else _extract_addon_name(row, provider_name, texts=[])
        indexer_name = _normalize_ascii(formatted.get('indexer') or '').upper()
        service_name = _normalize_ascii(formatted.get('service') or '').upper()
        addon_url = _safe_http_origin(formatted.get('url'))
        try:
            addon_domain = urlparse(addon_url).netloc
        except Exception:
            addon_domain = ''
        if addon_domain.startswith('www.'):
            addon_domain = addon_domain[4:]
        site = _extract_site(row, provider_name, addon_name=addon_name)
        # v4.6.9: the raw regex scan is BACK as a fallback on the AIO path.
        # "No raw scan on the AIO path" assumed the formatter always supplies
        # video/audio facts — but when the user's AIOStreams formatter preset
        # omits or renames those labelled fields, the bits came back empty,
        # and since the badge builder only emits a tag when it appears in
        # video_bits/audio_bits, the WHOLE badge row vanished (empty in every
        # device screenshot since 4.5.x). Formatter values stay authoritative
        # whenever present; the name/raw regex pass only fills the gap.
        raw_blob = ''
        if not (video_bits or audio_bits):
            _fallback_blob = ' | '.join(_collect_stream_texts(row))[:8192]
            if not video_bits:
                video_bits = _extract_video_bits(_fallback_blob, display_name)
            if not audio_bits:
                audio_bits = _extract_audio_bits(_fallback_blob, display_name)
        source_type = _source_type_from_formatter(formatted.get('type'))
    else:
        # Lightweight compatibility fallback for ordinary Stremio addons.
        values = _collect_stream_texts(row)
        raw_blob = ' | '.join(values)[:8192]
        display_name = _stream_display_name(row)
        addon_name = _extract_addon_name(row, provider_name, texts=values)
        indexer_name = _extract_indexer_name(
            row, provider_name, texts=values, addon_name=addon_name)
        service_name = _extract_service_name(row, texts=values)
        for candidate in _identity_candidates(
                row, 'manifestUrl', 'manifest_url', 'addonUrl', 'addon_url'):
            addon_url = _safe_http_origin(candidate)
            if addon_url:
                break
        try:
            addon_domain = urlparse(addon_url).netloc
        except Exception:
            addon_domain = ''
        if addon_domain.startswith('www.'):
            addon_domain = addon_domain[4:]
        site = _extract_site(row, provider_name, addon_name=addon_name)
        size = _extract_size(
            row.get('size'), row.get('videoSize'),
            hints.get('videoSize') if isinstance(hints, dict) else None,
            hints.get('size') if isinstance(hints, dict) else None,
        ) or _extract_size(raw_blob)
        # One video and one audio pass over one bounded string. v4.2.1 ran
        # these extractors per field and then invoked a second parser again.
        video_bits = _extract_video_bits(raw_blob, display_name)
        audio_bits = _extract_audio_bits(raw_blob, display_name)
        source_type = None

    # v5.10.204: AIOStreams' own data (streamData, sent to its clients)
    # names the type, the debrid service and the indexer exactly
    _sd = row.get('streamData') if isinstance(row.get('streamData'), dict) else {}
    if _sd:
        _sd_service = _sd.get('service') if isinstance(_sd.get('service'), dict) else {}
        if _sd_service.get('id') and not service_name:
            service_name = _normalize_ascii(str(_sd_service['id'])).upper()
        if _sd.get('indexer') and not indexer_name:
            indexer_name = _normalize_ascii(str(_sd['indexer'])).upper()
        _sd_type = _source_type_from_formatter(_sd.get('type'))
        if _sd_type:
            source_type = _sd_type
    subtitles = row.get('subtitles') or []
    badges = _stream_badges(video_bits, audio_bits, subtitles)
    if formatted or (_sd and service_name):
        provider_badge = _SERVICE_BADGES.get(service_name.upper())
        if not provider_badge:
            provider_badge = (service_name[:12] if service_name else
                              _provider_badge(row, provider_name, text_blob=' '))
    else:
        provider_badge = _provider_badge(
            row, provider_name, text_blob=raw_blob)
    if source_type is None:
        source_type = _stream_source_type(
            row, provider_name, text_blob=raw_blob,
            provider_badge=provider_badge)
    # AIOStreams may expose the delivery service as ``TYPE debrid`` even when
    # the underlying result is an NZB/Usenet row.  The indexer is the stronger
    # transport signal: EASYNEWS, ALTHUB, NZBGEEK, etc. must remain USENET in
    # the chip, count and type filter.  Keep the debrid/cache service visible
    # separately in ``service_name`` instead of letting it overwrite origin.
    source_type = _source_type_with_identity(
        source_type, indexer_name, service_name, addon_name, site)
    source_identity_line = _source_identity_line(
        source_type, provider_name, addon_name=addon_name,
        indexer_name=indexer_name, service_name=service_name)
    tags = _tags_from_fact_lists(video_bits, audio_bits, row=row)
    if formatted.get('lang'):
        formatter_langs = [
            part.strip() for part in
            re.split(r'\s*(?:/|\||\u2022|\u00b7)\s*', formatted.get('lang'))
            if part.strip()
        ]
        if formatter_langs:
            tags['languages'] = formatter_langs[:6]
    origin_line = _source_origin_line(
        row, provider_name, addon_name=addon_name,
        indexer_name=indexer_name, service_name=service_name,
        provider_domain=provider_domain, addon_domain=addon_domain)
    codec = next((x for x in video_bits if x in ('HEVC', 'H264', 'AV1')), '')
    audio = next((x for x in audio_bits if x in (
        'ATMOS', 'TRUEHD', 'DTS-X', 'DTS-HD', 'DTS', 'DD+', 'DD', 'AC3',
        'FLAC', 'AAC', 'OPUS')), '')
    hdr = next((x for x in video_bits if x in ('DV', 'HDR10+', 'HDR10', 'HDR')), '')
    return {
        'display_name': display_name,
        'site': site,
        'addon': addon_name,
        'indexer': indexer_name,
        'service': service_name,
        'origin_line': origin_line,
        'provider_domain': provider_domain,
        'provider_url': safe_provider_origin,
        'addon_domain': addon_domain,
        'addon_url': addon_url,
        'provider_badge': provider_badge,
        'size': size,
        'video_bits': video_bits,
        'audio_bits': audio_bits,
        'subtitles': subtitles,
        'badges': badges,
        'tags': tags,
        'source_type': source_type,
        'source_identity_line': source_identity_line,
        'codec': codec,
        'audio': audio,
        'hdr': hdr,
        '_raw_blob': raw_blob,
        '_formatter': formatted,
    }

def _stream_label(row, provider_name, index=None, facts=None):
    facts = facts or _stream_facts(row, provider_name)
    display_name = facts['display_name']
    site = facts['site']
    size = facts['size']
    video_bits = facts['video_bits']
    audio_bits = facts['audio_bits']
    subtitles = facts['subtitles']
    subs = _subtitles_summary(subtitles)
    badges = facts['badges']
    formatted = facts.get('_formatter') or {}
    description = ('' if formatted else
                   _normalize_ascii(row.get('description') or ''))
    title = _normalize_ascii(
        formatted.get('title') or row.get('title') or '')

    prefix = ('%02d. ' % int(index)) if index else ''
    label = '[B]%s%s[/B]' % (prefix, display_name)

    line2 = []
    if size:
        line2.append('SIZE: %s' % size)
    line2.append('VIDEO: %s' % (' | '.join(video_bits[:6]) if video_bits else '--'))
    line2.append('AUDIO: %s' % (' | '.join(audio_bits[:6]) if audio_bits else '--'))
    if site:
        line2.append('SITE: %s' % site)
    if badges:
        line2.append('TAGS: %s' % badges)
    label2 = '    '.join(line2)

    plot_lines = []
    if title and title.upper() != display_name:
        plot_lines.append(title)
    if description and description.upper() not in [x.upper() for x in plot_lines]:
        plot_lines.append(description)
    if subs:
        plot_lines.append('Subtitles: %s' % subs)
    plot = '\n'.join(plot_lines) or display_name
    return label, label2, plot

def _quality_badge(video_bits):
    bits = [str(x).upper() for x in (video_bits or [])]
    if '2160P' in bits or '4K' in bits:
        return '4K', 'FF0891B2'
    if '1080P' in bits:
        return '1080P', 'FF2563EB'
    if '720P' in bits:
        return '720P', 'FF059669'
    if '480P' in bits:
        return '480P', 'FFD97706'
    return '--', 'FF475569'

PLEX_COLOR = 'FFE5A00D'   # Plex brand gold

EMBY_COLOR = 'FF52B54B'   # Emby brand green

_DEDUP_EXT_RE = re.compile(
    r'\.(mkv|mp4|avi|mov|wmv|flv|webm|m4v|mpg|mpeg|3gp|m2ts|ts|vob|ogv|divx|xvid|rmvb|asf|mka)$',
    re.I)

_DEDUP_NONALNUM_RE = re.compile(r'[^0-9a-z\u0600-\u06ff+]', re.I)

def _dedup_geometric_bucket(value, round_pct=10):
    """Bucket a number so near-identical sizes share a key (AIOStreams)."""
    try:
        value = float(value or 0)
    except (TypeError, ValueError):
        return ''
    if value <= 0:
        return ''
    step = math.log(1.0 + round_pct / 100.0)
    index = round(math.log(value) / step)
    return str(int(round(math.exp(index * step))))

def _dedup_keys(entry):
    """The set of identity keys this source row is known by."""
    keys = set()

    name = str(entry.get('filename') or entry.get('name') or '').strip()
    if name:
        base = _DEDUP_EXT_RE.sub('', name)
        base = _DEDUP_NONALNUM_RE.sub('', base).lower()
        if len(base) >= 8:      # too short to be a trustworthy identity
            keys.add('f:%s' % base)

    info_hash = str(entry.get('info_hash') or '').strip().lower()
    if len(info_hash) >= 32:
        keys.add('h:%s|%s' % (info_hash, entry.get('file_idx') or 0))

    # The size fingerprint is a FALLBACK ONLY. AIOStreams defaults to
    # ['filename', 'infoHash'] and treats smart-detect as opt-in, for good
    # reason: two DIFFERENT films that happen to share a size and a resolution
    # would otherwise be merged into one. It is used here only when the row
    # carries no filename and no hash — i.e. when there is nothing else to
    # identify it by.
    size_bucket = _dedup_geometric_bucket(entry.get('size_bytes')) if not keys else ''
    if size_bucket:
        keys.add('s:%s|%s|%s|%s|%s' % (
            size_bucket,
            str(entry.get('quality') or '').lower(),
            str(entry.get('video_codec') or '').lower(),
            str(entry.get('audio') or '').lower(),
            str(entry.get('hdr') or '').lower(),
        ))
    return keys

def _dedup_rank(entry, priority):
    """Lower sorts first: the copy the user should keep."""
    provider = str(entry.get('provider_name_raw') or entry.get('addon') or '')
    native = 0 if provider.startswith(('Plex \u2022 ', 'Emby \u2022 ', 'Silo \u2022 ')) else 1
    try:
        order = priority.index(provider.lower())
    except ValueError:
        order = len(priority)
    try:
        size = -int(entry.get('size_bytes') or 0)      # bigger file wins a tie
    except (TypeError, ValueError):
        size = 0
    return (native, order, size)

def dedupe_stream_entries(entries, mode='single', priority=None):
    """Collapse duplicate source rows. Returns (kept, removed_count)."""
    entries = list(entries or [])
    if mode == 'off' or len(entries) < 2:
        return entries, 0
    priority = [str(p).lower() for p in (priority or [])]

    parent = list(range(len(entries)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    seen = {}
    for index, entry in enumerate(entries):
        for key in _dedup_keys(entry):
            if key in seen:
                union(seen[key], index)      # transitive, like AIOStreams' DSU
            else:
                seen[key] = index

    groups = {}
    for index in range(len(entries)):
        groups.setdefault(find(index), []).append(index)

    kept_indexes = set()
    for members in groups.values():
        if len(members) == 1:
            kept_indexes.add(members[0])
            continue
        if mode == 'per_addon':
            by_addon = {}
            for index in members:
                addon = str(entries[index].get('provider_name_raw') or '?')
                current = by_addon.get(addon)
                if current is None or _dedup_rank(entries[index], priority) < _dedup_rank(entries[current], priority):
                    by_addon[addon] = index
            kept_indexes.update(by_addon.values())
        else:
            kept_indexes.add(min(members, key=lambda i: _dedup_rank(entries[i], priority)))

    kept = [entry for index, entry in enumerate(entries) if index in kept_indexes]
    removed = len(entries) - len(kept)
    if removed:
        try:
            xbmc.log('[DexHub] source dedup: %d -> %d (%d duplicates removed, mode=%s)'
                     % (len(entries), len(kept), removed, mode), xbmc.LOGINFO)
        except Exception:
            pass
    return kept, removed

def _dedup_mode():
    """Cross-addon dedupe mode, from settings.

    The source window is an inventory, not a shortlist: two identical
    filenames from DIFFERENT addons can still be different servers, paths,
    encodes, subtitle sets or access routes, so the default stays 'off'.
    Repeated rows from the SAME provider are handled separately and
    unconditionally by _collapse_repeated_provider_rows.
    """
    # --- dexhub-406-patch --- honour the setting instead of ignoring it
    try:
        raw = str(ADDON.getSetting('source_dedup_mode') or '').strip().lower()
    except Exception:
        return 'off'
    if raw.startswith('single'):
        return 'single'
    if raw.startswith('one per'):
        return 'per_addon'
    return 'off'

