_TAG_RES = []           # v5.10.188: compiled at their first use (44 patterns at every import)


def _tag_res():
    """(the tag patterns by kind, the language patterns), compiled once."""
    if not _TAG_RES:
        _TAG_RES.append((
            {kind: [(label, re.compile(pattern, re.I | re.U)) for label, pattern in patterns]
             for kind, patterns in _TAG_PATTERNS.items()},
            [(label, re.compile(pattern, re.I | re.U)) for label, pattern in _LANG_PATTERNS]))
    return _TAG_RES[0]


_GROUP_RE = re.compile(r'(?:^|[-\[])\s*([A-Za-z0-9]{2,20})\s*$')

def stream_tag_line(tags, size_label='', provider=''):
    """The badges a user actually reads, in the order they care about."""
    bits = []
    if provider:
        bits.append(provider)
    for key in ('source', 'encode'):
        if tags.get(key):
            bits.append(tags[key][0])
    for label in (tags.get('visual') or [])[:2]:
        bits.append(label)
    if tags.get('audio'):
        audio = tags['audio'][0]
        if tags.get('channels'):
            audio += ' ' + tags['channels'][0]
        bits.append(audio)
    elif tags.get('channels'):
        bits.append(tags['channels'][0])
    for label in (tags.get('languages') or [])[:3]:
        bits.append(label)
    if size_label and size_label != '--':
        bits.append(size_label)
    return ' \u00b7 '.join(bits)

def _provider_badge(row, provider_name, text_blob=''):
    # v3.9.185: the built-in media servers get their own clean badge. Without
    # this they fell through to the generic branch and rendered as the mangled
    # 'PLEX HOM' / 'EMBY • H' (name truncated at 8 chars).
    # v3.9.198: match the NATIVE server providers only. The old
    # startswith('Plex') also caught the PlexBridge / Plexio *Stremio addons*,
    # which are something else entirely, and mislabelled them as native Plex.
    _name = str(provider_name or '')
    if _name.startswith('Plex \u2022 '):
        return 'PLEX'
    if _name.startswith('Emby \u2022 '):
        return 'EMBY'
    if text_blob:
        text = _normalize_ascii(text_blob).lower()
    else:
        values = _collect_stream_texts(row)
        values.append(provider_name)
        text = ' '.join(_normalize_ascii(v).lower() for v in values if v)[:8192]
    if 'realdebrid' in text or 'rd+' in text or re.search(r'\brd\+?\b', text):
        return 'RD+'
    if 'alldebrid' in text or re.search(r'\bad\+?\b', text):
        return 'AD+'
    if 'premiumize' in text or re.search(r'\bpm\+?\b', text):
        return 'PM'
    if 'torbox' in text or re.search(r'\btb\+?\b', text):
        return 'TB'
    if 'easydebrid' in text or 'ed+' in text:
        return 'ED+'
    cleaned = _normalize_ascii(provider_name or '')
    return (cleaned.upper()[:12] if cleaned else 'SRC')

_SOURCE_TYPE_STYLES = {
    'usenet':  ('USENET',  'FFD97706'),
    'debrid':  ('DEBRID',  'FF059669'),
    'torrent': ('TORRENT', 'FFDC2626'),
    'direct':  ('DIRECT',  'FF2563EB'),
    # v4.6.0: Plex and Emby no longer share one anonymous purple — they use
    # their brand colours (matching PLEX_COLOR / EMBY_COLOR above and the
    # static chip variants in sources_results.xml).
    'plex':    ('PLEX',    'FFE5A00D'),
    'emby':    ('EMBY',    'FF52B54B'),
    'silo':    ('SILO',    'FF7C3AED'),
}

_USENET_RE = re.compile(r'usenet|nzb|sabnzbd|newznab|easynews|eweka|newshosting|tweaknews|drunkenslug|althub|dognzb|omgwtf|binsearch|newsdemon|giganews|supernews|astraweb|usenetserver|newsgroup', re.I)

_TORRENT_HINT_RE = re.compile(r'\btorrent\w*\b|\bmagnet\b|\bseeders?\b|\bpeers?\b|\bp2p\b', re.I)

_DEBRID_BADGES = ('RD+', 'AD+', 'PM', 'TB', 'ED+')

def _source_type_with_identity(source_type, *identity_values):
    """Let a concrete Usenet identity override a generic delivery label."""
    try:
        current_key = str((source_type or ('',))[0] or '').lower()
    except Exception:
        current_key = ''
    # Never reinterpret native-library transports from their display text.
    if current_key in ('plex', 'emby', 'silo'):
        return source_type
    identity_blob = ' '.join(
        _normalize_ascii(value).lower() for value in identity_values if value)
    if identity_blob and _USENET_RE.search(identity_blob):
        return ('usenet',) + _SOURCE_TYPE_STYLES['usenet']
    return source_type

def _stream_source_type(row, provider_name, text_blob='', provider_badge=''):
    """Classify one raw stream row → (key, chip label, chip ARGB colour)."""
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict) and hints.get('nativeProvider'):
        native = str(hints.get('nativeProvider') or '').lower()
        key = ('plex' if 'plex' in native else
               ('silo' if 'silo' in native else
                ('emby' if ('emby' in native or 'jellyfin' in native) else 'direct')))
        return (key,) + _SOURCE_TYPE_STYLES[key]
    _pname = str(provider_name or '')
    if _pname.startswith('Plex \u2022 '):
        return ('plex',) + _SOURCE_TYPE_STYLES['plex']
    if _pname.startswith('Emby \u2022 '):
        return ('emby',) + _SOURCE_TYPE_STYLES['emby']
    if _pname.startswith('Silo \u2022 '):
        return ('silo',) + _SOURCE_TYPE_STYLES['silo']
    # Structural marker first: several aggregators (AIOStreams included)
    # expose the transport as a literal field rather than words in the name.
    for _tf in (row.get('type'), row.get('sourceType'), row.get('transport'),
                (hints.get('type') if isinstance(hints, dict) else None),
                (hints.get('sourceType') if isinstance(hints, dict) else None)):
        if 'usenet' in str(_tf or '').lower():
            return ('usenet',) + _SOURCE_TYPE_STYLES['usenet']
    raw_text = str(text_blob or '')[:8192]
    if not raw_text:
        raw_text = ' '.join(_collect_stream_texts(row))[:8192]
    text_l = _normalize_ascii(raw_text).lower()
    if _USENET_RE.search(text_l):
        return ('usenet',) + _SOURCE_TYPE_STYLES['usenet']
    badge = provider_badge or _provider_badge(
        row, provider_name, text_blob=raw_text)
    if badge in _DEBRID_BADGES or 'debrid' in text_l or 'offcloud' in text_l or 'premiumize' in text_l or '\u26a1' in raw_text:
        return ('debrid',) + _SOURCE_TYPE_STYLES['debrid']
    info_hash = str(row.get('infoHash') or row.get('infohash') or (hints.get('infoHash') if isinstance(hints, dict) else '') or '')
    url = str(row.get('url') or row.get('externalUrl') or '')
    if info_hash or url.lower().startswith('magnet:') or _TORRENT_HINT_RE.search(text_l):
        return ('torrent',) + _SOURCE_TYPE_STYLES['torrent']
    return ('direct',) + _SOURCE_TYPE_STYLES['direct']

def _source_info_text(row, provider_name, facts=None, provider_origin=''):
    parts = []
    facts = facts or _stream_facts(
        row, provider_name, provider_origin=provider_origin)
    addon_name = facts.get('addon') or ''
    site_name = facts.get('site') or ''
    indexer_name = facts.get('indexer') or ''
    service_name = facts.get('service') or ''
    parts.append('provider: %s' % (provider_name or 'Provider'))
    safe_provider_url = facts.get('provider_url') or _safe_http_origin(provider_origin)
    if safe_provider_url:
        parts.append('provider URL: %s' % safe_provider_url)
    if addon_name:
        parts.append('addon: %s' % addon_name)
    if facts.get('addon_url'):
        parts.append('addon URL: %s' % facts.get('addon_url'))
    if service_name:
        parts.append('service: %s' % service_name)
    if indexer_name:
        parts.append('indexer: %s' % indexer_name)
    if site_name and site_name != addon_name:
        parts.append('site: %s' % site_name)
    detail_keys = ('name', 'title', 'filename')
    for key in detail_keys:
        val = row.get(key)
        if val:
            parts.append('%s: %s' % (key, _clean_stream_text(val)))
    formatted = facts.get('_formatter') or {}
    if formatted:
        for key in ('file', 'title', 'video', 'audio', 'size', 'lang', 'subs'):
            val = formatted.get(key)
            if val:
                parts.append('%s: %s' % (key, _clean_stream_text(val)))
    elif row.get('description'):
        parts.append('description: %s' % _clean_stream_text(row.get('description')))
    if row.get('subtitles'):
        parts.append('subtitles: %s' % _subtitles_summary(row.get('subtitles') or []))
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict) and hints:
        # Keep the useful technical fields but never copy a tokenised manifest,
        # request headers or a huge opaque JSON blob into every ListItem.
        compact_hints = {}
        for key in ('filename', 'videoSize', 'bingeGroup', 'sourceType',
                    'quality', 'resolution', 'codec', 'audioChannels',
                    'nativeProvider', 'serverType'):
            value = hints.get(key)
            if value not in (None, '', [], {}):
                compact_hints[key] = value
        try:
            if compact_hints:
                parts.append('behaviorHints: %s' % json.dumps(
                    compact_hints, ensure_ascii=False, separators=(',', ':')))
        except Exception:
            pass
    return '\n'.join(parts)

_SUBS_TMP_DIRNAME = 'dexhub_subs'

def _companion_context_from_playback(ctx):
    hints = ctx.get('behaviorHints') or {}
    if not isinstance(hints, dict):
        hints = {}
    comp = {}
    for src, dst in (
        ('bootstrapUrl', 'bootstrapUrl'),
        ('companionUrl', 'companionUrl'),
        ('companionScrobbleUrl', 'companionScrobbleUrl'),
        ('companionUnscrobbleUrl', 'companionUnscrobbleUrl'),
        ('sessionIdentifier', 'sessionIdentifier'),
        ('playbackSessionId', 'playbackSessionId'),
        ('clientIdentifier', 'clientIdentifier'),
        ('plexDuration', 'duration_ms'),
        ('serverType', 'server_type'),
        ('serverUrl', 'server_url'),
        ('token', 'token'),
        ('itemId', 'item_id'),
        ('deviceId', 'device_id'),
        ('sessionId', 'session_id'),
        ('durationMs', 'duration_ms'),
    ):
        val = hints.get(src)
        if val not in (None, ''):
            comp[dst] = val
    if comp.get('duration_ms'):
        try:
            comp['duration_ms'] = int(float(comp['duration_ms']))
        except Exception:
            comp['duration_ms'] = int(ctx.get('duration_ms') or 0)
    elif ctx.get('duration_ms'):
        comp['duration_ms'] = int(ctx.get('duration_ms') or 0)
    if not comp.get('clientIdentifier'):
        comp['clientIdentifier'] = hints.get('clientIdentifier') or 'DexHub-Kodi'
    if comp.get('server_type') and isinstance(comp.get('server_type'), str):
        comp['server_type'] = comp['server_type'].lower()
    comp['deviceName'] = 'Kodi'
    comp['product'] = 'Dex Hub'
    if any(comp.get(k) for k in ('companionUrl', 'companionScrobbleUrl', 'companionUnscrobbleUrl')):
        return comp
    if all(ctx.get(k) for k in ('server_type', 'server_url', 'token')):
        direct = {
            'server_type': ctx.get('server_type'),
            'server_url': ctx.get('server_url'),
            'token': ctx.get('token'),
            'duration_ms': int(ctx.get('duration_ms') or 0),
        }
        for key in ('rating_key', 'client_id', 'device_name', 'product', 'product_version', 'item_id', 'device_id', 'session_id'):
            if ctx.get(key):
                direct[key] = ctx.get(key)
        return direct
    return {}

_SESSION_CTX_COPY_KEYS = (
    # The service ownership gate requires this identity on every handoff.
    # Losing it makes our own stream look foreign and disables resume/progress.
    'playback_uid', 'playback_created_at',
    'source_switch_pending', 'source_switch_captured_at', 'source_switch_reuse_subtitle',
    'media_type', 'canonical_id', 'video_id', 'title', 'show_title', 'year',
    'season', 'episode', 'imdb_id', 'tmdb_id', 'tvdb_id', 'provider_id',
    'source_provider_id', 'server_id', 'source_addon', 'source_indexer',
    'source_service', 'source_type', 'binge_group', 'behaviorHints',
    'show_imdb_id', 'show_tmdb_id', 'show_tvdb_id', 'external_ids',
    'introdb_post_start', 'episode_order', 'displayorder',
    'provider_name', 'provider_base_url', 'subtitles', 'stream_url', 'poster',
    'background', 'clearlogo', 'genre', 'rating', 'studio', 'premiered',
    'duration', 'duration_ms', 'kodi_info', 'cast', 'resume_seconds', 'resume_percent',
    'switch_subtitle_path', 'switch_subtitle_enabled', 'switch_subtitle_name',
    # --- direct-server reporting keys (v3.9.232) --------------------------
    # companion.get_reporter() builds its EmbyReporter/PlexReporter from the
    # SAVED SESSION, and needs (server_type, server_url, token) plus item_id
    # for Emby / rating_key for Plex.  None of them were copied here, so
    # get_reporter() returned None on the native-server path: no progress was
    # ever POSTed to /Sessions/Playing, Emby never marked anything as
    # in-progress, /Users/{id}/Items/Resume stayed empty, and Emby's Continue
    # Watching row was permanently blank.  (Plex only looked fine because the
    # Plex apps write their own progress.)
    'server_type', 'server_url', 'token', 'item_id', 'rating_key',
    'media_source_id', 'part_key', 'play_session_id', 'device_id', 'session_id', 'silo_session',
)

def _augment_session_ctx(target, ctx, fallback_keys, include_stream_url=True):
    """Copy live playback fields from ``ctx`` onto a session dict ``target``.

    Shared by both the companion-sync and the minimal (no-companion) branches
    of ``_play_with_context`` — previously duplicated verbatim.  Behaviour is
    identical to the original inline blocks:

      * only non-empty ctx values overwrite target keys,
      * ``include_stream_url=False`` skips the stream_url key so the caller's
        pre-seeded ``{'stream_url': ...}`` precedence is preserved,
      * source picker URL and next-episode hint are attached when available
        (picker-url failures are swallowed exactly as before),
      * automatic stream fallback is explicitly removed.  A failed source must
        never switch to a different source without the user's choice.
    """
    for key in _SESSION_CTX_COPY_KEYS:
        if key == 'stream_url' and not include_stream_url:
            continue
        if ctx.get(key) not in (None, ''):
            target[key] = ctx.get(key)
    target.pop('fallback_stream_keys', None)
    try:
        _picker_url = _source_picker_url_from_ctx(ctx)
        if _picker_url:
            target['source_picker_url'] = _picker_url
    except Exception:
        pass
    next_hint = ctx.get('next_episode') or _compute_next_episode_hint(ctx)
    if next_hint:
        target['next_episode'] = next_hint
    return target

def _publish_playback_art_properties(ctx):
    """Publish playback artwork/skin properties for the current item.

    Extracted verbatim from _play_with_context (v3.9.145). Writes the
    dexhub.* window properties, mirrors artwork onto the always-alive
    home window (Window 10000), and publishes Arctic Fuse / Arctic
    Zephyr skin properties. Property write ORDER is preserved exactly;
    several skins and the Kodi 22 safe-handoff path depend on it.
    Self-contained: reads only ctx, leaks no locals back to the caller.
    """
    # Always write clearlogo — even when empty — so stale art from the
    # previous item doesn't bleed through to the current one.
    _logo = ctx.get('clearlogo') or ''
    xbmcgui.Window(WINDOW_ID).setProperty('dexhub.clearlogo', _logo)
    xbmcgui.Window(WINDOW_ID).setProperty('clearlogo', _logo)
    xbmcgui.Window(WINDOW_ID).setProperty('tvshow.clearlogo', _logo)
    # v3.9.85: scrub the poster URL before propagating. Some Stremio
    # addons (notably the smaller anime/streaming providers) return
    # their own logo in the meta record's poster field when they have
    # no real poster for an item. Without this cleanup, that addon
    # logo would appear in Dex Hub's source-loading dialog, the source
    # picker hero, and the player overlay — looking broken because the
    # SAME logo appears for every item from that addon. See
    # _is_suspect_logo_poster for the detection heuristic.
    _clean_p = _clean_poster(ctx.get('poster') or '',
                              fallback=ctx.get('background') or '',
                              imdb_id=ctx.get('imdb_id') or '')
    _clean_fanart = ctx.get('background') or _clean_p or neutral_fanart()
    if _clean_p:
        xbmcgui.Window(WINDOW_ID).setProperty('dexhub.poster', _clean_p)
    xbmcgui.Window(WINDOW_ID).setProperty('dexhub.fanart', _clean_fanart)
    # Mirror the active playback artwork onto the always-alive home window as
    # well. Several skins/player overlays read artwork from Window(10000) or
    # global properties during fullscreen playback, not from our transient
    # custom source window. Without this mirror the clearlogo can be visible in
    # Dex Hub's source picker yet disappear once the actual player takes over.
    try:
        home = xbmcgui.Window(10000)
        logo_value = ctx.get('clearlogo') or ''
        poster_value = _clean_p   # v3.9.85: same scrubbed value used above
        fanart_value = _clean_fanart
        title_value = ctx.get('title') or ''
        plot_value = ctx.get('plot') or ''
        year_value = str(ctx.get('year') or '')
        genre_value = str(ctx.get('genre') or '')
        studio_value = str(ctx.get('studio') or '')
        rating_value = str(ctx.get('rating') or '')
        home.setProperty('dexhub.source.clearlogo', logo_value)
        home.setProperty('dexhub.source.poster', poster_value)
        home.setProperty('dexhub.source.thumb', poster_value)
        home.setProperty('dexhub.source.fanart', fanart_value)
        home.setProperty('dexhub.source.title', title_value)
        home.setProperty('dexhub.source.plot', plot_value)
        home.setProperty('dexhub.source.year', year_value)
        home.setProperty('dexhub.source.genre', genre_value)
        home.setProperty('dexhub.source.studio', studio_value)
        home.setProperty('dexhub.source.rating', rating_value)
        home.setProperty('dexhub.source.key', _source_art_identity_key(ctx))
        if _safe_playback_handoff_enabled():
            # Kodi 22 safe path: publish ONLY the lightweight logo properties
            # used by Arctic Fuse/skin player overlays.  Do not publish the full
            # poster/fanart/tvshow alias set here; that was the risky part on
            # CoreELEC Piers alpha.
            home.setProperty('clearlogo', logo_value)
            home.setProperty('logo', logo_value)
            home.setProperty('tvshow.clearlogo', logo_value)
            home.setProperty('ArcticFuse.NowPlaying.Logo', logo_value)
            home.setProperty('ArcticFuse.Player.Logo', logo_value)
            home.setProperty('ArcticFuse.CurrentlyPlaying', 'true' if logo_value else '')
        else:
            # Publish common global artwork keys too; many fullscreen skins read
            # these instead of the addon's namespaced properties during playback.
            home.setProperty('clearlogo', logo_value)
            home.setProperty('logo', logo_value)
            home.setProperty('tvshow.clearlogo', logo_value)
            home.setProperty('poster', poster_value)
            home.setProperty('thumb', poster_value)
            home.setProperty('fanart', fanart_value)
            home.setProperty('fanart_image', fanart_value)
            home.setProperty('landscape', fanart_value)
            home.setProperty('tvshow.poster', poster_value)
            home.setProperty('tvshow.fanart', fanart_value)
            home.setProperty('tvshow.landscape', fanart_value)
            home.setProperty('studio', studio_value)
            home.setProperty('genre', genre_value)
            home.setProperty('rating', rating_value)
            home.setProperty('tmdb_type', _tmdb_type_from_ctx(ctx))
            if ctx.get('tmdb_id'):
                home.setProperty('tmdb_id', str(ctx.get('tmdb_id')))
            if ctx.get('imdb_id'):
                home.setProperty('imdb_id', str(ctx.get('imdb_id')))
                home.setProperty('IMDBNumber', str(ctx.get('imdb_id')))
            if ctx.get('tvdb_id'):
                home.setProperty('tvdb_id', str(ctx.get('tvdb_id')))

            # ── Arctic Fuse 3 / Arctic Zephyr 2 skin properties ─────────────
            home.setProperty('ArcticFuse.NowPlaying.Logo',    logo_value)
            home.setProperty('ArcticFuse.NowPlaying.Thumb',   poster_value)
            home.setProperty('ArcticFuse.NowPlaying.Fanart',  fanart_value)
            home.setProperty('ArcticFuse.NowPlaying.Title',   title_value)
            home.setProperty('ArcticFuse.NowPlaying.Plot',    plot_value)
            home.setProperty('ArcticFuse.NowPlaying.Year',    year_value)
            home.setProperty('ArcticFuse.NowPlaying.Studio',  studio_value)
            home.setProperty('ArcticFuse.NowPlaying.Genre',   genre_value)
            home.setProperty('ArcticFuse.NowPlaying.Rating',  rating_value)
            home.setProperty('ArcticFuse.CurrentlyPlaying',   'true')
            home.setProperty('ArcticFuse.Player.Logo',        logo_value)
            home.setProperty('ArcticFuse.Player.Thumb',       poster_value)
            home.setProperty('ArcticFuse.Player.Fanart',      fanart_value)
            home.setProperty('ArcticFuse.Player.Studio',      studio_value)
            home.setProperty('ArcticFuse.Player.Genre',       genre_value)
            home.setProperty('ArcticFuse.Player.Rating',      rating_value)
            if ctx.get('season') and ctx.get('episode'):
                _ep_label = 'S%02dE%02d' % (int(ctx.get('season') or 0), int(ctx.get('episode') or 0))
                home.setProperty('ArcticFuse.NowPlaying.Episode', _ep_label)
                home.setProperty('ArcticFuse.Player.Episode',     _ep_label)
                _show = ctx.get('show_title') or title_value
                home.setProperty('ArcticFuse.NowPlaying.ShowTitle', _show)
                home.setProperty('ArcticFuse.Player.ShowTitle',     _show)
            else:
                home.clearProperty('ArcticFuse.NowPlaying.Episode')
                home.clearProperty('ArcticFuse.Player.Episode')
                home.clearProperty('ArcticFuse.NowPlaying.ShowTitle')
                home.clearProperty('ArcticFuse.Player.ShowTitle')
    except Exception:
        pass
    # 5.10.302: the Home's now-playing logo (kept until playback stops)
    try:
        from . import nowplaying as _np
        _np.publish(ctx, lookup=False)
    except Exception:
        pass

def _refresh_native_playback_context(ctx):
    """Refresh server-owned playback URLs immediately before handoff.

    Source results can stay open for minutes and Emby PlaybackInfo is session
    scoped. Refreshing here prevents stale MediaSource/PlaySession data from
    crashing direct play after the user spends time in the source picker.
    """
    ctx = dict(ctx or {})
    backend = str(ctx.get('server_type') or '').lower()
    if backend not in ('emby', 'silo', 'jellyfin'):
        return ctx
    if ctx.get('native_playback_resolved'):
        return ctx
    # `video_id` is the CANONICAL id (e.g. tt43595399 on the source-picker
    # path), NOT an Emby ItemId. Feeding an IMDb id to Emby's API makes every
    # PlaybackInfo/progress call fail. Only fall back to video_id when it does
    # not look like an external (imdb/tmdb/tvdb/anime) id.
    item_id = str(ctx.get('item_id') or '')
    if not item_id:
        _candidate = str(ctx.get('video_id') or '')
        if _candidate and not _candidate.lower().startswith(
                ('tt', 'tmdb:', 'tvdb:', 'kitsu:', 'mal:', 'anilist:')):
            item_id = _candidate

    server_url = str(ctx.get('server_url') or '')
    token = str(ctx.get('token') or '')
    if not (item_id and server_url and token):
        return ctx
    try:
        client = _server_client(backend)
        auth = client.account() or {}
        server = {
            'id': auth.get('user_id') or backend,
            'name': auth.get('server_name') or ('Silo' if backend == 'silo' else 'Emby'),
            'url': server_url,
            'token': token,
            'user_id': auth.get('user_id') or '',
            'backend': backend,
        }
        # v5.10.27: bound the refresh. It runs synchronously right before
        # Player.play, and the direct URL below is already a valid fallback.
        with emby_client.bounded_timeout(6):
            args = (server, item_id, str(ctx.get('media_source_id') or ''))
            resolved = (client.resolve_playback(*args, start_position=ctx.get('resume_seconds'))
                        if backend == 'silo' else client.resolve_playback(*args))
        if resolved.get('url'):
            ctx['stream_url'] = resolved.get('url')
        if resolved.get('media_source_id'):
            ctx['media_source_id'] = resolved.get('media_source_id')
        if resolved.get('play_session_id'):
            ctx['session_id'] = resolved.get('play_session_id')
        if resolved.get('silo_session'):
            ctx['silo_session'] = resolved['silo_session']
        version = resolved.get('version') or {}
        if version.get('subtitles'):
            ctx['subtitles'] = list(version.get('subtitles') or [])
        ctx['native_playback_resolved'] = True
    except Exception as exc:
        if backend == 'silo':
            raise
        # Keep the already-built direct URL as a compatibility fallback.
        try:
            xbmc.log('[DexHub] %s PlaybackInfo refresh failed; using direct fallback: %s' % (
                         backend.capitalize(), exc),
                     xbmc.LOGWARNING)
        except Exception:
            pass
    return ctx

def _play_with_context(ctx, stream_key='', fallback_keys=None, entries_meta=None, use_resolved_url=None):
    from .playback_engine import play_with_context
    return play_with_context(sys.modules[__name__], ctx=ctx, stream_key=stream_key, fallback_keys=fallback_keys, entries_meta=entries_meta, use_resolved_url=use_resolved_url)

def _compute_next_episode_hint(ctx):
    """Return next-episode playback URL info if current playback is an episode
    and a next episode exists."""
    try:
        season = int(ctx.get('season') or 0)
        episode = int(ctx.get('episode') or 0)
    except Exception:
        return None
    canonical = ctx.get('canonical_id') or ''
    media_type = (ctx.get('media_type') or '').lower()
    if not canonical or season <= 0 or episode <= 0 or media_type not in ('series', 'anime', 'show', 'tv'):
        return None
    # Look up the show's video list from the window prop set by series_meta().
    try:
        raw = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical) or ''
        videos = json.loads(raw) if raw else []
    except Exception:
        videos = []
    if not videos:
        return None
    # Find next episode — same season & ep+1, else season+1 & ep1.
    candidates = [
        (season, episode + 1),
        (season + 1, 1),
    ]
    affinity = _binge_source.affinity_from_context(ctx)
    for s, e in candidates:
        for v in videos:
            try:
                if int(v.get('season') or 0) == s and int(v.get('episode') or 0) == e:
                    hint = {
                        'canonical_id': canonical,
                        'video_id': v.get('id') or canonical,
                        'season': s,
                        'episode': e,
                        'title': ctx.get('show_title') or ctx.get('title') or canonical,
                    }
                    for key, value in affinity.items():
                        if value:
                            # Route code historically consumes
                            # source_provider_id, while affinity helpers use
                            # provider_id. Keep one canonical key in the hint.
                            hint['source_provider_id' if key == 'provider_id' else key] = value
                    return hint
            except Exception:
                continue
    return None

def _source_window_meta_from_entries(entries, meta=None):
    merged = dict(meta or {})
    try:
        home = xbmcgui.Window(10000)
    except Exception:
        home = None
    for entry in list(entries or []):
        try:
            ctx = cache_store.get('stream', entry.get('stream_key') or '') or {}
        except Exception:
            ctx = {}
        if not isinstance(ctx, dict) or not ctx:
            continue
        if not merged.get('poster'):
            merged['poster'] = ctx.get('poster') or ''
        if not merged.get('fanart'):
            merged['fanart'] = ctx.get('background') or ctx.get('poster') or ''
        if not merged.get('clearlogo'):
            merged['clearlogo'] = ctx.get('clearlogo') or ''
        if not merged.get('title'):
            merged['title'] = ctx.get('show_title') or ctx.get('originaltitle') or ctx.get('title') or ''
        if not merged.get('originaltitle'):
            merged['originaltitle'] = ctx.get('originaltitle') or ctx.get('show_title') or ''
        if not merged.get('plot'):
            merged['plot'] = ctx.get('plot') or ctx.get('stream_description') or ''
        if not merged.get('tmdb_id'):
            merged['tmdb_id'] = ctx.get('tmdb_id') or ''
        if not merged.get('imdb_id'):
            merged['imdb_id'] = ctx.get('imdb_id') or ''
        if not merged.get('tvdb_id'):
            merged['tvdb_id'] = ctx.get('tvdb_id') or ''
        if not merged.get('media_type'):
            merged['media_type'] = ctx.get('media_type') or ''
        if not merged.get('year'):
            merged['year'] = ctx.get('year') or ''
        if not merged.get('genre'):
            merged['genre'] = ctx.get('genre') or ''
        if not merged.get('rating'):
            merged['rating'] = ctx.get('rating') or ''
        if not merged.get('studio'):
            merged['studio'] = ctx.get('studio') or ((ctx.get('kodi_info') or {}).get('studio') if isinstance(ctx.get('kodi_info'), dict) else '') or ''
        if merged.get('poster') and merged.get('fanart') and merged.get('title'):
            break
    try:
        if home and _home_source_props_match(merged, home):
            if not merged.get('poster'):
                merged['poster'] = home.getProperty('dexhub.source.poster') or ''
            if not merged.get('fanart'):
                merged['fanart'] = home.getProperty('dexhub.source.fanart') or ''
            if not merged.get('clearlogo'):
                merged['clearlogo'] = home.getProperty('dexhub.source.clearlogo') or ''
            if not merged.get('title'):
                merged['title'] = home.getProperty('dexhub.source.title') or ''
            if not merged.get('plot'):
                merged['plot'] = home.getProperty('dexhub.source.plot') or ''
            if not merged.get('year'):
                merged['year'] = home.getProperty('dexhub.source.year') or ''
            if not merged.get('studio'):
                merged['studio'] = home.getProperty('dexhub.source.studio') or ''
    except Exception:
        pass
    if not merged.get('poster'):
        merged['poster'] = merged.get('fanart') or ''
    return merged

def _current_source_ui_meta(meta=None):
    """Artwork currently shown in the source window, without stale bleed.

    For playback handoff we should preserve the artwork selected for this
    source window, but not pull poster/logo from previous playback globals.
    """
    merged = dict(meta or {})
    try:
        home = xbmcgui.Window(10000)
    except Exception:
        home = None

    def _first(*values):
        for value in values:
            if value not in (None, ''):
                return value
        return ''

    poster = _first(merged.get('poster'), merged.get('thumb'))
    fanart = _first(merged.get('background'), merged.get('fanart'), poster)
    clearlogo = _first(merged.get('clearlogo'), merged.get('logo'))
    title = _first(merged.get('title'), merged.get('name'))
    plot = _first(merged.get('plot'), merged.get('description'))
    year = _first(merged.get('year'))
    genre = _first(merged.get('genre'))
    rating = _first(merged.get('rating'))
    studio = _first(merged.get('studio'))

    try:
        if home and _home_source_props_match(merged, home):
            poster = _first(poster, home.getProperty('dexhub.source.poster'), home.getProperty('dexhub.source.thumb'))
            fanart = _first(fanart, home.getProperty('dexhub.source.fanart'), poster)
            clearlogo = _first(clearlogo, home.getProperty('dexhub.source.clearlogo'))
            title = _first(title, home.getProperty('dexhub.source.title'))
            plot = _first(plot, home.getProperty('dexhub.source.plot'))
            year = _first(year, home.getProperty('dexhub.source.year'))
            genre = _first(genre, home.getProperty('dexhub.source.genre'))
            rating = _first(rating, home.getProperty('dexhub.source.rating'))
            studio = _first(studio, home.getProperty('dexhub.source.studio'))
    except Exception:
        pass

    if poster:
        merged['poster'] = poster
    if fanart:
        merged['fanart'] = fanart
        merged['background'] = fanart
    elif poster:
        merged['fanart'] = poster
        merged['background'] = poster
    merged['clearlogo'] = clearlogo or ''
    merged['logo'] = clearlogo or ''
    if title and not merged.get('title'):
        merged['title'] = title
    if plot and not merged.get('plot'):
        merged['plot'] = plot
    if year and not merged.get('year'):
        merged['year'] = year
    if genre and not merged.get('genre'):
        merged['genre'] = genre
    if rating and not merged.get('rating'):
        merged['rating'] = rating
    if studio and not merged.get('studio'):
        merged['studio'] = studio
    return merged

def _show_stream_window(entries, meta, session_key=''):
    meta = _source_window_meta_from_entries(entries, meta)
    meta = _source_window_meta_fallback(meta)
    chosen_key = None
    play_with_subtitles = False
    play_mode = _subtitle_pick_mode_setting()
    try:
        for _dlg in ('busydialog', 'busydialognocancel'):
            try:
                xbmc.executebuiltin('Dialog.Close(%s,true)' % _dlg)
            except Exception:
                pass
        def retry_source(state, source_meta):
            from .source_retry import fetch
            return fetch(state, source_meta, api=sys.modules[__name__])
        result = open_sources_window(entries, meta, play_mode=play_mode, session_key=session_key,
                                     retry_source=retry_source)
        if isinstance(result, dict):
            chosen_key = result.get('stream_key')
            play_with_subtitles = bool(result.get('play_with_subtitles'))
        else:
            chosen_key = result
    except Exception as exc:
        xbmc.log('[DexHub] source window failed, using dialog fallback: %s' % exc, xbmc.LOGWARNING)
        labels = [e.get('name') or e.get('label2') or e.get('stream_key') or 'Stream' for e in entries]
        idx = xbmcgui.Dialog().select(tr(meta.get('title') or tr('اختر المصدر')), [tr(x) for x in labels])
        if idx >= 0 and idx < len(entries):
            chosen_key = entries[idx].get('stream_key')
            if play_mode == 'ask':
                play_choice = xbmcgui.Dialog().select(tr('اختر طريقة التشغيل'), [tr('تشغيل'), tr('تشغيل مع ترجمة')])
                if play_choice < 0:
                    chosen_key = None
                else:
                    play_with_subtitles = (play_choice == 1)
            else:
                play_with_subtitles = (play_mode == 'play_with_subtitles')
    if chosen_key:
        ctx = cache_store.get('stream', chosen_key)
        if ctx:
            ctx = dict(ctx or {})
            # Preserve exactly the artwork currently shown in the source UI and
            # forward it to the wait window + player overlay. This prevents TMDb
            # fallback art from replacing the correct XML/source artwork.
            meta = _current_source_ui_meta(meta)
            for _art_key in ('clearlogo', 'poster', 'background'):
                _meta_val = meta.get(_art_key) or meta.get('fanart' if _art_key == 'background' else _art_key)
                if _meta_val:
                    ctx[_art_key] = _meta_val
            # Propagate plot/year/title/media_type so the wait window can
            # render the full right panel without a TMDb DB round-trip.
            for _txt_key in ('plot', 'title', 'year', 'media_type', 'genre', 'rating', 'studio', 'premiered', 'duration'):
                _txt_val = meta.get(_txt_key)
                if _txt_val and not ctx.get(_txt_key):
                    ctx[_txt_key] = _txt_val
            ctx['play_with_subtitles'] = bool(play_with_subtitles)
            # The selected source is authoritative. A failed handoff returns
            # control to the user instead of trying a different URL.
            # Pre-emptively close any spinner so it doesn't sit on top of the
            # video player after playback starts. Symptom this fixes:
            # "loading spinner stays even when the movie plays".
            for _dlg in ('busydialog', 'busydialognocancel'):
                try:
                    xbmc.executebuiltin('Dialog.Close(%s,true)' % _dlg)
                except Exception:
                    pass
            _remember_source_choice(ctx)
            try:
                current_action = dict(parse_qsl(sys.argv[2].lstrip('?'))).get('action', '')
            except Exception:
                current_action = ''
            # dialog:false in dexhub.json → no open HANDLE for tmdb_player.
            use_resolved = (HANDLE >= 0 and current_action in (
                'play_item', 'cw_resume', 'cw_play_from_start', 'play',
                # TMDb Helper invokes its player URL through ResolvePath on
                # current Kodi builds even when the player JSON advertises
                # is_resolvable=false. Resolving the selected stream here
                # prevents the parent TMDb Helper route from ending with
                # "is not playable" after the source picker closes.
                'tmdb_player',
            ))
            try:
                _needs_resume_seek = float(ctx.get('resume_seconds') or 0.0) > 1.0 or (1.0 < float(ctx.get('resume_percent') or 0.0) < 95.0)
            except Exception:
                _needs_resume_seek = False
            if _needs_resume_seek and current_action != 'tmdb_player':
                # Normal internal routes keep the known-good Player.play seek
                # path. TMDb Helper must remain resolved through its open
                # handle, otherwise its parent ResolvePath reports the item as
                # unplayable after Dex Hub already opened the source picker.
                use_resolved = False
            # v3.9.80: DPlex-style fast handoff. Keep setResolvedUrl for
            # normal raw media when Kodi gave us a plugin handle; reserve
            # Player.play for resume/plugin/magnet paths.  This usually starts
            # the native player faster and closer to DPlex/TMDb Helper.
            # v3.9.71: full diagnostic wrap around the play handoff. If
            # anything inside _play_with_context raises, the user gets a
            # textviewer dialog with the full traceback instead of a
            # silent crash before playback. Same pattern that exposed
            # the v3.9.62 "ADDON not defined" bug in collection import.
            # v4.7.8: reverted the 4.7.5 resolve-abort here for the same
            # reason as the play-dispatch site — declaring the item unplayable
            # made Kodi's Playlist Player skip it.
            try:
                # Fast DPlex-style handoff: do not add an artificial delay
                # between closing the source picker and resolving the item.
                _play_with_context(ctx, chosen_key, fallback_keys=[], use_resolved_url=use_resolved)
            except Exception as _play_exc:
                import traceback as _tb
                _trace = _tb.format_exc()
                try:
                    xbmc.log('[DexHub] _play_with_context CRASHED before playback:\n%s' % _trace, xbmc.LOGERROR)
                except Exception:
                    pass
                try:
                    xbmcgui.Dialog().textviewer(
                        tr('Dex Hub — تعذّر بدء التشغيل'),
                        ('Crashed before playback could start.\n\n'
                         'Stream key: %s\nProvider: %s\nMedia: %s\n\n'
                         'Error:\n%s\n\n%s') % (
                            chosen_key or '?',
                            ctx.get('provider_name') or ctx.get('provider_id') or '?',
                            ctx.get('media_type') or '?',
                            str(_play_exc),
                            _trace,
                        ),
                    )
                except Exception:
                    pass
                # Still clear handoff flags so we don't bounce through TMDb Helper.
                _clear_tmdbh_transient()
                return
            # v3.9.32: skip endOfDirectory after ANY successful playback
            # start, not just the setResolvedUrl path. When invoked via
            # TMDb Helper handoff, calling endOfDirectory triggers Kodi
            # to re-render the directory we came from (TMDb Helper's
            # player route) — manifesting as a second TMDb Helper page
            # appearing the moment playback starts. Even when not from
            # TMDb Helper, after Player.play() has been called the
            # HANDLE no longer needs an endOfDirectory — Kodi's playback
            # flow doesn't depend on it. Previously only `use_resolved`
            # path returned early; now both paths do.
            # Clear the handoff flag pre-emptively so any later container
            # refresh from playback start doesn't bounce us back through
            # TMDb Helper either.
            _clear_tmdbh_transient()
            return
    else:
        _clear_tmdbh_transient()
        # TMDb Helper invokes this route through ResolvePath. Closing the
        # source picker without choosing a stream must complete that resolver
        # explicitly; otherwise Kodi waits for the Python invoker and reports
        # the parent TMDb Helper item as "is not playable".
        if HANDLE >= 0:
            try:
                xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
            except Exception:
                pass
    try:
        xbmcplugin.endOfDirectory(HANDLE, succeeded=True, updateListing=False, cacheToDisc=False)
    except Exception:
        pass

def _collapse_repeated_provider_rows(entries):
    """Drop rows the SAME provider returned more than once.

    A provider is queried with up to four candidate ids (imdb/tmdb/tvdb/
    kitsu). Bridge addons resolve every one of them to the same item and
    answer with the same streams, so each version arrives once per matched
    id. Two identical urls from the same addon are the same file by
    definition — there is no server, encode or access route in which they
    differ.

    Rows from DIFFERENT providers are deliberately left alone: the source
    window is an inventory, and two addons offering the same filename can
    still be genuinely different routes.

    Returns (kept, removed_count).
    """
    entries = list(entries or [])
    if len(entries) < 2:
        return entries, 0
    seen = set()
    kept = []
    removed = 0
    for entry in entries:
        provider = str(entry.get('provider_name_raw') or entry.get('addon') or '')
        url = str(entry.get('stream_url') or '').strip()
        info_hash = str(entry.get('info_hash') or '').strip().lower()
        key = None
        if url:
            key = ('u', provider, url)
        elif len(info_hash) >= 32:
            key = ('h', provider, info_hash, str(entry.get('file_idx') or 0))
        if key is not None and key in seen:
            removed += 1
            continue
        if key is not None:
            seen.add(key)
        kept.append(entry)
    return kept, removed

def _finalize_stream_entries(entries, resort=True, media_type='', canonical_id='', video_id=''):
    # --- dexhub-406-patch --- same provider, same url -> one row
    try:
        entries, _repeat_removed = _collapse_repeated_provider_rows(entries)
        if _repeat_removed:
            xbmc.log('[DexHub] collapsed %d repeated rows from the same provider '
                     '(multi-id scan)' % _repeat_removed, xbmc.LOGINFO)
    except Exception:
        pass
    # v3.9.198: collapse the same physical file arriving from several addons
    # (AIOStreams' union-find over filename / infoHash / size fingerprint).
    try:
        _mode = _dedup_mode()
        if _mode != 'off':
            _order = (ADDON.getSetting('source_priority_order') or '')
            entries, _removed = dedupe_stream_entries(
                entries, mode=_mode,
                priority=[p.strip().lower() for p in _order.split(',') if p.strip()])
    except Exception:
        pass
    preferred_source = _last_source_choice(media_type, canonical_id, video_id)
    from .search.ranking import source_settings
    return _rank_finalize_stream_entries(entries, source_settings(ADDON), preferred_source=preferred_source, resort=resort)

def _kodi_header_string(headers):
    """Return Kodi's URL header suffix from a dict/list of HTTP headers."""
    if not headers:
        return ''
    pairs = []
    try:
        if isinstance(headers, dict):
            iterable = headers.items()
        elif isinstance(headers, (list, tuple)):
            iterable = headers
        else:
            iterable = []
        for key, value in iterable:
            key = str(key or '').strip()
            if not key or value in (None, ''):
                continue
            pairs.append((key, str(value)))
    except Exception:
        pairs = []
    if not pairs:
        return ''
    try:
        return urlencode(pairs)
    except Exception:
        return '&'.join('%s=%s' % (quote_plus(k), quote_plus(v)) for k, v in pairs)

def _stream_row_request_headers(row):
    """Extract request headers from Stremio stream rows.

    Stremio aggregators-style addons can attach headers either at the top
    level (`requestHeaders`) or under `behaviorHints.proxyHeaders.request`.
    Kodi needs those encoded after a `|` suffix on the playable URL.
    """
    if not isinstance(row, dict):
        return {}
    out = {}

    def _merge(value):
        if not value:
            return
        try:
            if isinstance(value, dict):
                iterator = value.items()
            elif isinstance(value, (list, tuple)):
                iterator = value
            else:
                return
            for k, v in iterator:
                k = str(k or '').strip()
                if k and v not in (None, ''):
                    out[k] = str(v)
        except Exception:
            pass

    _merge(row.get('requestHeaders'))
    _merge(row.get('headers'))
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict):
        _merge(hints.get('requestHeaders'))
        proxy_headers = hints.get('proxyHeaders') or {}
        if isinstance(proxy_headers, dict):
            _merge(proxy_headers.get('request'))
            # Some implementations put the request headers directly under
            # proxyHeaders instead of nesting them under "request".
            if not any(k in proxy_headers for k in ('request', 'response')):
                _merge(proxy_headers)
    return out

def _apply_kodi_request_headers(url, row):
    url = str(url or '').strip()
    if not url:
        return ''
    # Plugin URLs should receive their own query params, not Kodi pipe headers.
    if url.lower().startswith('plugin://'):
        return url
    headers = _stream_row_request_headers(row)
    suffix = _kodi_header_string(headers)
    if not suffix:
        return url
    if '|' in url:
        base, existing = url.split('|', 1)
        if existing:
            return base + '|' + existing + '&' + suffix
        return base + '|' + suffix
    return url + '|' + suffix

def _torrent_handoff_url(magnet):
    """Return a Kodi plugin handoff URL for a magnet when a torrent player exists."""
    magnet = str(magnet or '').strip()
    if not magnet:
        return ''
    # Elementum is the most common Kodi torrent player and understands the
    # Stremio-style magnet handoff reliably. Quasar uses a compatible route.
    for addon_id, template in (
        ('plugin.video.elementum', 'plugin://plugin.video.elementum/play?uri=%s'),
        ('plugin.video.quasar', 'plugin://plugin.video.quasar/play?uri=%s'),
        # Torrest route support varies by build, but this is harmless when
        # installed and gives users another local torrent player option.
        ('plugin.video.torrest', 'plugin://plugin.video.torrest/play_magnet?magnet=%s'),
    ):
        try:
            # the skin condition first: Addon() on a missing add-on logs an
            # EXCEPTION line in kodi.log
            if not xbmc.getCondVisibility('System.HasAddon(%s)' % addon_id):
                continue
            xbmcaddon.Addon(addon_id)
            return template % quote_plus(magnet)
        except Exception:
            continue
    # Kodi cannot natively resolve magnets, but returning the magnet keeps the
    # source visible and lets any external/magnet handler attempt playback.
    return magnet

def _magnet_from_stream_row(row):
    if not isinstance(row, dict):
        return ''
    raw_url = str(row.get('url') or '').strip()
    if raw_url.lower().startswith('magnet:'):
        return raw_url
    hints = row.get('behaviorHints') or {}
    if not isinstance(hints, dict):
        hints = {}
    info_hash = (
        row.get('infoHash') or row.get('infohash') or row.get('btih') or
        hints.get('infoHash') or hints.get('infohash') or hints.get('btih') or ''
    )
    info_hash = re.sub(r'[^A-Fa-f0-9]', '', str(info_hash or '')).strip()
    if len(info_hash) not in (32, 40):
        return ''
    name = (
        row.get('title') or row.get('name') or row.get('filename') or
        hints.get('filename') or hints.get('title') or hints.get('name') or
        'DexHub torrent'
    )
    trackers = []
    for value in (row.get('sources') or hints.get('sources') or []):
        text = str(value or '').strip()
        if not text:
            continue
        if text.lower().startswith(('tracker:', 'dht:', 'udp://', 'http://', 'https://')):
            text = re.sub(r'^(tracker:|dht:)', '', text, flags=re.I).strip()
            if text.lower().startswith(('udp://', 'http://', 'https://')):
                trackers.append(text)
    magnet = 'magnet:?xt=urn:btih:%s&dn=%s' % (info_hash, quote_plus(str(name or 'DexHub torrent')))
    for tr_url in trackers[:30]:
        magnet += '&tr=%s' % quote_plus(tr_url)
    try:
        file_idx = row.get('fileIdx') if row.get('fileIdx') not in (None, '') else row.get('fileIndex')
        if file_idx in (None, ''):
            file_idx = hints.get('fileIdx') if hints.get('fileIdx') not in (None, '') else hints.get('fileIndex')
        if file_idx not in (None, ''):
            # Stremio/Torrentio fileIdx is 0-based. Elementum accepts `so` as
            # the selected file index in the magnet query.
            magnet += '&so=%s' % quote_plus(str(file_idx))
    except Exception:
        pass
    return magnet

def _stream_play_url_from_row(row):
    """Normalize a Stremio stream row into something Kodi can play.

    Important: do NOT use `externalUrl` as a fallback playable URL. In the
    Stremio stream schema it is usually an external webpage/intent, while
    `url` is the direct playable stream and `infoHash`/`fileIdx` is the torrent
    stream shape. Treating externalUrl as video is why Torrentio/AIOStreams
    rows could appear in Dex Hub but fail at playback.
    """
    if not isinstance(row, dict):
        return ''
    url = str(row.get('url') or '').strip()
    if url.lower().startswith('magnet:'):
        return _torrent_handoff_url(url)
    if url:
        return _apply_kodi_request_headers(url, row)
    magnet = _magnet_from_stream_row(row)
    if magnet:
        return _torrent_handoff_url(magnet)
    # Some Stremio/Nuvio-compatible addons return playable resolver links only
    # in externalUrl. Keep direct media, plugin, and manifest-resolver URLs;
    # reject ordinary webpages/configuration links.
    external = str(row.get('externalUrl') or '').strip()
    low = external.lower()
    if low.startswith(('plugin://', 'magnet:')):
        return _torrent_handoff_url(external) if low.startswith('magnet:') else external
    if low.startswith(('http://', 'https://')):
        path = low.split('?', 1)[0]
        media_exts = ('.m3u8', '.mp4', '.mkv', '.webm', '.ts', '.avi', '.mov', '.mpd')
        resolver_markers = ('/stream/', '/play/', '/resolve/', '/redirect/', 'video=', 'url=')
        blocked = ('/configure', '/settings', '/install', '/manifest.json')
        if not any(x in low for x in blocked) and (path.endswith(media_exts) or any(x in low for x in resolver_markers)):
            return _apply_kodi_request_headers(external, row)
    return ''

_APPEND_LEDGER = {}

_APPEND_LEDGER_LOCK = threading.Lock()

def _prune_append_ledger():
    """Keep the dedupe ledger bounded under reuselanguageinvoker.

    Keyed by id(entries), so a list that has been garbage-collected leaves a
    stale entry behind. The scan holds at most a couple of live lists, so
    trimming to the newest few is both safe and enough.
    """
    with _APPEND_LEDGER_LOCK:
        if len(_APPEND_LEDGER) <= 8:
            return
        for key in list(_APPEND_LEDGER)[:-4]:
            _APPEND_LEDGER.pop(key, None)

def _is_aiostreams_provider(provider):
    """Identify an AIOStreams manifest without depending on its display name."""
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    values = (
        manifest.get('id'), manifest.get('name'), manifest.get('logo'),
        provider.get('name'), provider.get('manifest_url'), provider.get('base_url'),
    )
    blob = ' '.join(str(value or '') for value in values).lower()
    return ('com.aiostreams.' in blob or 'viren070/aiostreams' in blob or
            'aiostreams.' in blob)


def _aio_info_lines(text):
    """v5.10.203: the lines of an AIOStreams description worth a row: not the
    title line (the page already names the title), the file path or a
    message, which a formatter often puts first or last."""
    lines = [line for line in str(text or '').splitlines() if line.strip()]
    keep = [line for line in lines
            if not line.lstrip().startswith(('\U0001f3ac', '\U0001f4c1', '\U0001f4c2', '\u2139'))]
    return keep or lines


def _source_left_out(provider):
    """v5.10.203: an add-on the user left out of the source search."""
    try:
        from .source_addons import skipped, key
        return key(provider) in skipped()
    except Exception:
        return False


def _library_state(row):
    """v5.10.204: the source is already in the user's library."""
    try:
        from .source_details import library_state
        return library_state(row)
    except Exception:
        return False


def _ready_state(row, facts):
    """v5.10.203: cached (True), not cached (False) or unknown (None)."""
    try:
        from .source_details import ready_state
        return ready_state(row, facts)
    except Exception:
        return None


def _upstream_formatter_text(value, max_lines=8, max_chars=1600):
    """Keep AIO's line structure/emojis while bounding Kodi ListItem payloads."""
    lines = []
    for raw in str(value or '').replace('\r', '').split('\n')[:max_lines]:
        line = MULTI_WS_RE.sub(' ', raw).strip()
        if line:
            lines.append(line)
    return '\n'.join(lines)[:max_chars]

def _append_stream_entries_from_data(entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids, title='', video_id=None, season=None, episode=None, show_title='', resume_seconds=0.0, resume_percent=0.0):
    provider_name = provider.get('name') or 'Provider'
    _provider_is_aiostreams = _is_aiostreams_provider(provider)
    _provider_safe_origin = _provider_origin(provider)
    _provider_identity_art = provider_art(
        provider_name,
        provider.get('manifest') or {},
        provider.get('base_url') or provider.get('manifest_url') or '',
    )
    _provider_icon = (_provider_identity_art.get('icon') or
                      _provider_identity_art.get('thumb') or media_path('provider.png'))
    # Self-hosted/rebranded AIOStreams manifests can omit their logo.  Use a
    # bundled official mark in that case so a custom name such as Dexstreams
    # does not fall back to Dex Hub's anonymous provider glyph.
    if (_provider_is_aiostreams and
            _provider_icon == media_path('provider.png')):
        _provider_icon = media_path('provider_aiostreams.png')
    raw_streams = (data or {}).get('streams') or []
    # Be liberal with non-standard addons that return a single stream object
    # instead of a list. More importantly, never turn a multi-version response
    # into a provider-level singleton.
    if isinstance(raw_streams, dict):
        raw_streams = [raw_streams]
    elif not isinstance(raw_streams, (list, tuple)):
        raw_streams = []
    # v5.10.15: idempotency guard. The 5.10.14 kodi.log shows every provider
    # appended TWICE with an identical request id ("collapsed 1/2/4/6/8
    # repeated rows from the same provider"), because the foreground scan and
    # the live-refresh worker can both process the same completion. Collapsing
    # afterwards still paid the full cost: JSON walk, ranking, artwork, UI.
    # `entries` is the one object both phases share, so the ledger lives on it
    # and a payload can be appended at most once per scan.
    _dedupe_key = '%s|%s|%s' % (
        str(provider.get('id') or provider.get('base_url')
            or provider.get('manifest_url') or provider_name or ''),
        str(request_id or ''), str(len(raw_streams)))
    try:
        _seen = _APPEND_LEDGER.setdefault(id(entries), set())
        if _dedupe_key in _seen:
            xbmc.log('[DexHub] duplicate append suppressed: provider=%s request=%s rows=%d'
                     % (provider_name, request_id, len(raw_streams)), xbmc.LOGINFO)
            return
        _seen.add(_dedupe_key)
        if len(_APPEND_LEDGER) > 8:
            _prune_append_ledger()
    except Exception:
        pass
    try:
        xbmc.log('[DexHub] Stremio raw streams: provider=%s request=%s rows=%d' % (
            provider_name, request_id, len(raw_streams)), xbmc.LOGINFO)
    except Exception:
        pass
    _before_provider_rows = len(entries)
    _dropped_no_url = 0
    # Read the user template once per provider response, never on focus or
    # selection changes. The formatter itself caches the parsed template.
    try:
        _formatter_enabled = str(_setting(
            'enable_source_formatter', 'true')).strip().lower() in (
                '1', 'true', 'yes', 'on')
        _follow_aio_formatter = str(_setting(
            'follow_aiostreams_formatter', 'true')).strip().lower() in (
                '1', 'true', 'yes', 'on')
        _formatter_template = (_setting('source_formatter_template', '') or
                               _source_formatter.DEFAULT_TEMPLATE)
    except Exception:
        _formatter_enabled = False
        _follow_aio_formatter = False
        _formatter_template = ''
    from . import source_diagnostics as _diag
    _batch_kodi_info = None
    _batch_year = None
    for _row_index, row in enumerate(raw_streams):
        _row_started = time.monotonic()
        _diag.trace('row-start', _row_index)
        stream_url = _stream_play_url_from_row(row)
        if not stream_url:
            # v3.9.262: a row with no url/magnet/infoHash is unplayable and is
            # skipped — but count and LOG it, so "addon returned 3, Dex shows 1"
            # can be diagnosed from kodi.log instead of guessed at.
            _dropped_no_url += 1
            # v4.7.5: this fired 486 times in ONE session of the user's log.
            # Per-row detail is a DEBUG concern and the per-provider summary
            # below keeps the diagnostic value at INFO; on ARM boxes the write
            # volume itself costs frame time during a source scan.
            try:
                if _dropped_no_url <= 3:
                    xbmc.log('[DexHub] Stremio row dropped (no playable url): provider=%s name=%r external=%r keys=%s' % (
                        provider_name, (row.get('name') or row.get('title') or '')[:60],
                        bool(row.get('externalUrl')), sorted(list(row.keys()))[:12]), xbmc.LOGINFO)
            except Exception:
                pass
            continue
        facts = _stream_facts(
            row, provider_name, provider_origin=_provider_safe_origin)
        _diag.trace('facts-ready', _row_index, _row_started)
        _aio_name = ''
        _aio_description = ''
        _aio_preview = ''
        if (_formatter_enabled and _follow_aio_formatter and
                _provider_is_aiostreams):
            # AIOStreams has already applied the formatter selected in its
            # configuration page. Consume that output instead of trying to
            # retrieve private user configuration or evaluate it a second
            # time. The next stream request therefore follows every saved AIO
            # formatter change automatically and adds zero network calls.
            _aio_name = _upstream_formatter_text(row.get('name'), max_lines=2,
                                                  max_chars=240)
            _aio_description = _upstream_formatter_text(row.get('description'))
            if _aio_name:
                facts['display_name'] = '  '.join(_aio_name.splitlines())
            if _aio_description:
                _aio_preview = '  •  '.join(
                    _aio_info_lines(_aio_description)[:2])[:420]
        elif _formatter_enabled and _formatter_template:
            try:
                _formatted_identity = _source_formatter.render(
                    _formatter_template, row, facts)
                if _formatted_identity:
                    facts['source_identity_line'] = _formatted_identity
            except Exception:
                # A malformed custom preset must never hide or drop a stream.
                pass
        label, label2, plot = _stream_label(
            row, provider_name, facts=facts)
        _diag.trace('formatter-ready', _row_index, _row_started)
        display_name = facts['display_name']
        size = facts['size']
        video_bits = facts['video_bits']
        audio_bits = facts['audio_bits']
        quality, highlight = _quality_badge(video_bits)
        # Do not collapse exact URLs or matching name/size fingerprints.
        # The user explicitly wants every row from every addon/server.
        if _batch_kodi_info is None:
            _batch_kodi_info = _stream_meta_info_payload(
                best_meta, media_type=media_type,
                title=(title or best_meta.get('name') or canonical_id),
                show_title=(show_title or best_meta.get('name') or canonical_id),
                season=season, episode=episode,
            )
            _batch_year = _meta_info(best_meta).get('year') or 0
        _kodi_info = dict(_batch_kodi_info)
        _studio_prop = _kodi_info.get('studio') or ''
        _genre_prop = _kodi_info.get('genre') or ''
        if isinstance(_studio_prop, (list, tuple)):
            _studio_prop = ' / '.join([str(x) for x in _studio_prop if x])
        if isinstance(_genre_prop, (list, tuple)):
            _genre_prop = ' / '.join([str(x) for x in _genre_prop if x])
        payload = {
            'media_type': media_type,
            'canonical_id': canonical_id,
            'video_id': video_id or request_id,
            'provider_name': provider_name,
            'provider_id': provider.get('id') or '',
            # Stable scan target used by same-source next episode. Native
            # playback rewrites provider_id to plex_native/emby_native below,
            # while this field deliberately keeps __plex__/__emby__.
            'source_provider_id': provider.get('id') or '',
            'source_addon': facts.get('addon') or provider_name,
            'source_indexer': facts.get('indexer') or '',
            'source_service': facts.get('service') or '',
            'source_origin': facts.get('origin_line') or provider_name,
            'provider_origin': _provider_safe_origin,
            'provider_domain': facts.get('provider_domain') or '',
            'addon_url': facts.get('addon_url') or '',
            'addon_domain': facts.get('addon_domain') or '',
            'title': title or best_meta.get('name') or canonical_id,
            'show_title': show_title or best_meta.get('name') or canonical_id,
            'year': _batch_year,
            'stream_url': stream_url,
            'poster': art.get('poster') or '',
            'background': bg,
            'clearlogo': art.get('clearlogo') or '',
            'tmdb_id': ids.get('tmdb_id') or '',
            'imdb_id': ids.get('imdb_id') or '',
            'tvdb_id': ids.get('tvdb_id') or '',
            'external_ids': ids,
            'kodi_info': _kodi_info,
            'plot': _kodi_info.get('plot') or best_meta.get('description') or best_meta.get('overview') or '',
            'genre': _genre_prop,
            'studio': _studio_prop,
            'rating': _kodi_info.get('rating') or best_meta.get('imdbRating') or '',
            'premiered': _kodi_info.get('premiered') or '',
            'duration': _kodi_info.get('duration') or '',
            'cast': _kodi_info.get('cast') or [],
            'subtitles': row.get('subtitles') or [],
            'behaviorHints': row.get('behaviorHints') or {},
            'binge_group': ((row.get('behaviorHints') or {}).get('bingeGroup')
                            if isinstance(row.get('behaviorHints') or {}, dict)
                            else '') or '',
            'source_type': (facts.get('source_type') or ('', '', ''))[0],
            'provider_base_url': provider.get('base_url') or '',
            'duration_ms': int((((row.get('behaviorHints') or {}).get('plexDuration') or (row.get('behaviorHints') or {}).get('durationMs') or 0)) or 0),
            'stream_name': row.get('name') or '',
            'stream_title': row.get('title') or '',
            'stream_description': row.get('description') or '',
            'formatter_tags': [],
            # v4.7.3: RAW stream text (AIOStreams formatter output with its
            # \u265b/emoji markers intact). User badges.json presets are
            # written against THIS text; the cleaned display name strips
            # the markers, so crown-gated rules could never match.
            'badge_blob_raw': ' | '.join(_collect_stream_texts(row))[:4096],
            # AIOStreams already formatted the description. source_info keeps
            # it for the details panel; duplicating it as another list property
            # only makes every row heavier and triggers a second badge scan.
            'formatter_summary': '',
            'video_bits': facts.get('video_bits') or [],
            'audio_bits': facts.get('audio_bits') or [],
            'request_headers': _stream_row_request_headers(row),
            'external_url': row.get('externalUrl') or '',
            'info_hash': (row.get('infoHash') or row.get('infohash') or ((row.get('behaviorHints') or {}) if isinstance(row.get('behaviorHints') or {}, dict) else {}).get('infoHash') or ''),
        }
        # A Stremio episode request is made with the series identity, so keep
        # that identity explicit before any native source row replaces the
        # item's generic ids with episode-level ids.
        if season not in (None, '', 0, '0') and episode not in (None, '', 0, '0'):
            payload['show_imdb_id'] = _normalize_imdb_id(ids.get('imdb_id')) or ''
            payload['show_tmdb_id'] = str(ids.get('tmdb_id') or '')
            payload['show_tvdb_id'] = str(ids.get('tvdb_id') or '')
        # Native Plex/Emby rows carry their direct progress and identity
        # context in behaviorHints. Copy it to the playback session so external
        # subtitle addons receive the full IDs and companion reporting does not
        # fall back to a generic Stremio row.
        _hints = row.get('behaviorHints') or {}
        if isinstance(_hints, dict) and _hints.get('nativeProvider'):
            payload['provider_id'] = '%s_native' % str(_hints.get('nativeProvider'))
            payload['server_type'] = str(_hints.get('serverType') or _hints.get('nativeProvider') or '')
            payload['server_url'] = str(_hints.get('serverUrl') or '')
            payload['server_id'] = str(_hints.get('serverId') or '')
            payload['token'] = str(_hints.get('token') or '')
            payload['rating_key'] = str(_hints.get('ratingKey') or '')
            payload['item_id'] = str(_hints.get('itemId') or '')
            payload['media_source_id'] = str(_hints.get('mediaSourceId') or '')
            payload['part_key'] = str(_hints.get('partKey') or '')
            payload['duration_ms'] = int(_hints.get('durationMs') or payload.get('duration_ms') or 0)
            payload['imdb_id'] = _normalize_imdb_id(_hints.get('imdbId') or payload.get('imdb_id')) or payload.get('imdb_id') or ''
            payload['tmdb_id'] = str(_hints.get('tmdbId') or payload.get('tmdb_id') or '')
            payload['tvdb_id'] = str(_hints.get('tvdbId') or payload.get('tvdb_id') or '')
            payload['show_imdb_id'] = _normalize_imdb_id(
                _hints.get('showImdbId') or payload.get('show_imdb_id')) or payload.get('show_imdb_id') or ''
            payload['show_tmdb_id'] = str(
                _hints.get('showTmdbId') or payload.get('show_tmdb_id') or '')
            payload['show_tvdb_id'] = str(
                _hints.get('showTvdbId') or payload.get('show_tvdb_id') or '')
            payload['external_ids'] = {
                'imdb_id': payload.get('imdb_id') or '',
                'tmdb_id': payload.get('tmdb_id') or '',
                'tvdb_id': payload.get('tvdb_id') or '',
                'show_imdb_id': payload.get('show_imdb_id') or '',
                'show_tmdb_id': payload.get('show_tmdb_id') or '',
                'show_tvdb_id': payload.get('show_tvdb_id') or '',
            }

        if season is not None:
            payload['season'] = int(season)
        if episode is not None:
            payload['episode'] = int(episode)
        try:
            rs = float(resume_seconds or 0.0)
        except Exception:
            rs = 0.0
        if rs > 1.0:
            payload['resume_seconds'] = rs
        try:
            rp = float(resume_percent or 0.0)
        except Exception:
            rp = 0.0
        if rp > 1.0 and rp < 95.0:
            payload['resume_percent'] = rp
        cache_key = cache_store.put('stream', payload)
        _diag.trace('cache-written', _row_index, _row_started)
        _row_tags = facts.get('tags') or {}
        _stype, _stype_label, _stype_color = facts.get('source_type') or (
            ('direct',) + _SOURCE_TYPE_STYLES['direct'])
        _source_details = _source_info_text(
            row, provider_name, facts=facts,
            provider_origin=_provider_safe_origin)
        if _aio_description:
            _source_details = '%s\n\n%s' % (_aio_description, _source_details)
        entries.append({
            'stream_key': cache_key,
            # --- dexhub-406-patch --- identity for same-provider collapsing
            'stream_url': stream_url,
            # v4.1.0: source-type chip (usenet/debrid/torrent/direct/server)
            'source_type': _stype,
            'source_type_label': _stype_label,
            'source_type_color': _stype_color,
            'name': display_name,
            'label2': label2,
            'count': '00.',
            'quality': quality,
            'highlight': highlight,
            'provider': facts.get('provider_badge') or _provider_badge(
                row, provider_name, text_blob=facts.get('_raw_blob') or ''),
            'provider_name_raw': provider_name,
            'binge_group': ((_hints.get('bingeGroup') if isinstance(_hints, dict)
                             else '') or ''),
            'source_addon': facts.get('addon') or provider_name,
            'source_indexer': facts.get('indexer') or '',
            'source_service': facts.get('service') or '',
            'provider_icon': _provider_icon,
            'addon': facts.get('addon') or provider_name,
            'provider_domain': facts.get('provider_domain') or '',
            'provider_url': _provider_safe_origin,
            'addon_url': facts.get('addon_url') or '',
            'addon_domain': facts.get('addon_domain') or '',
            'source_site': facts['site'],
            'indexer': facts.get('indexer') or '',
            'service_name': facts.get('service') or '',
            'origin_line': facts.get('origin_line') or provider_name,
            'source_identity_line': (facts.get('source_identity_line') or
                                     facts.get('origin_line') or provider_name),
            'upstream_formatter_preview': _aio_preview,
            'upstream_formatter_text': _aio_description,
            # v5.10.302: the add-on's own row text, shown as Nuvio shows it
            # (5.10.297 put it in plugin.py only; this is the builder in use)
            'stream_name_raw': str(row.get('name') or '')[:400],
            'stream_desc_raw': str(row.get('description') or row.get('title') or '')[:900],
            'stream_video_size': ((row.get('behaviorHints') or {}).get('videoSize') if isinstance(row.get('behaviorHints'), dict) else '') or '',
            'cached': _ready_state(row, facts),
            'in_library': _library_state(row),
            'size_label': size or '--',
            'extraInfo': ' | '.join(video_bits[:8]) if video_bits else '--',
            'extraInfo2': ' | '.join(audio_bits[:8]) if audio_bits else '--',
            'badges': _stream_badges(video_bits, audio_bits, row.get('subtitles') or []),
            'source_info': _source_details + '\n\n' + plot,
            # v3.9.198: identity fields for the AIOStreams-style deduplicator.
            'filename': str((row.get('behaviorHints') or {}).get('filename') or ''),
            'info_hash': str(row.get('infoHash') or row.get('infohash') or
                             (row.get('behaviorHints') or {}).get('infoHash') or ''),
            'file_idx': (row.get('fileIdx') if row.get('fileIdx') is not None
                         else (row.get('behaviorHints') or {}).get('fileIdx')) or 0,
            'size_bytes': _extract_size(
                (row.get('behaviorHints') or {}).get('videoSize'),
                row.get('size'), row.get('sizebytes')) or 0,
            'video_codec': facts.get('codec') or '',
            'audio': facts.get('audio') or '',
            'hdr': facts.get('hdr') or '',
            # v3.9.199: the AIOStreams-grade fact set, parsed from the raw title.
            'tags': _row_tags,
            'languages': _row_tags.get('languages') or [],
            'tag_line': stream_tag_line(_row_tags,
                                        size_label=facts.get('size') or '',
                                        provider=facts.get('addon') or provider_name),
        })
        _diag.trace('row-ready', _row_index, _row_started)
    # Publish the growing index once per provider, not once per result.
    try:
        _publish_last_streams_index(canonical_id, season, episode, entries, poster=art.get('poster') or '')
    except Exception:
        pass
    try:
        xbmc.log('[DexHub] Stremio appended streams: provider=%s raw=%d kept=%d dropped_no_url=%d' % (
            provider_name, len(raw_streams), len(entries) - _before_provider_rows, _dropped_no_url), xbmc.LOGINFO)
    except Exception:
        pass

def _provider_signature_text(provider):
    manifest = (provider or {}).get('manifest') or {}
    return ' '.join([
        str((provider or {}).get('name') or ''),
        str((provider or {}).get('base_url') or ''),
        str((provider or {}).get('manifest_url') or ''),
        str((provider or {}).get('id') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()

def _stream_timeout_for_provider(provider):
    """Return a bounded timeout for a normal Stremio addon.

    Every installed manifest follows the same provider path. Aggregators such
    as AIOStreams are no longer called through a private/direct API. Their
    configured manifest URL is queried exactly like any other Stremio addon.
    """
    sig = _provider_signature_text(provider)
    try:
        base = int(float(ADDON.getSetting('timeout') or '20'))
    except Exception:
        base = 20
    if any(token in sig for token in ('torrentio', 'comet', 'mediafusion', 'stremthru', 'aiostream')):
        # v5.10.26: 10-25s let one slow aggregator pin a streams-lane worker
        # for the whole scan. 8-12s still covers Torrentio/Comet cold hits.
        return max(8, min(max(base, 8), 12))
    return fast_timeout('stream')

def _setting_bool(name, default=False):
    try:
        raw = (ADDON.getSetting(name) or ('true' if default else 'false')).strip().lower()
    except Exception:
        raw = 'true' if default else 'false'
    return raw in ('true', '1', 'yes', 'on')

def _server_client(backend):
    if backend == 'jellyfin':
        return jellyfin_client
    if backend == 'plex':
        return plex_client
    if backend == 'silo':
        return silo_client
    return emby_client

def _server_stream_rows(backend, server, ids, media_type, titles,
                        season=None, episode=None, titles_loader=None, year=''):
    """ONE lookup for both servers: ID first, titles only as a fallback.

    v3.9.218 — the unified path the user asked for.

    Emby worked because it was asked by ID (AnyProviderIdEquals). Plex was
    asked by TITLE — and an Arabic title can never match an English library,
    let alone the literal string "الحلقة 16". Both servers now take the same
    route through the same code:

        1. every ID we hold (imdb / tmdb / tvdb) -> find_all_by_ids
        2. only if that finds nothing, the title variants
        3. every hit is verified against the IDs before it is trusted

    Whatever comes back is a normal Dex Hub source row, so the servers ARE
    sources — ranked, badged, switchable and resumable like any other.
    """
    client = _server_client(backend)
    identity = MediaIdentity(media_type=media_type, ids=ids, title=(titles or [''])[0],
                             titles=titles, season=season, episode=episode)
    ids = identity.ids
    series = identity.is_episode
    kind = identity.media_type

    # v3.9.225: the server step gets its OWN budget. It used to run inside the
    # shared source scan with no ceiling of its own, so a slow Plex server
    # starved the Stremio addons until they timed out and were blacklisted.
    # Failure accounting is suspended for the duration: a provider must only
    # ever be penalised for its own failures.
    _budget = _get_int_setting('server_lookup_seconds', 7, minimum=4, maximum=60)
    _deadline = time.time() + float(_budget)
    try:
        from .dexhub.client import provider_health_pause
        provider_health_pause(_budget + 2)
    except Exception:
        pass

    matches, seen = [], set()

    def _take(rows):
        for row in (rows or []):
            key = str(row.get('rating_key') or '')
            if key and key not in seen:
                seen.add(key)
                matches.append(row)

    # v5.10.27: every request inside this step is capped at the step budget,
    # so a single hung request can no longer outlive it.
    _bounded = (plex_client.bounded_timeout if backend == 'plex'
                else emby_client.bounded_timeout)
    _per_request = max(3, min(int(_budget), 6))

    # 1) BY ID — the only lookup that survives a translated library
    try:
        with _bounded(_per_request):
            options = {'year': year} if backend == 'jellyfin' else {}
            _take(client.find_all_by_ids(server, ids, media_type=kind, title='', limit=24, **options))
    except Exception as exc:
        xbmc.log('[DexHub] %s id lookup failed: %s' % (backend, exc), xbmc.LOGWARNING)
        # v5.10.91: a timed-out id lookup is a slow server, not an empty one.
        if isinstance(exc, TimeoutError) or 'timed out' in str(exc).lower():
            try:
                if not server.get('_stop_reason'):
                    server['_stop_reason'] = 'deadline'
            except Exception:
                pass

    # v5.10.91: the stop signal installed by the source scan (cancelled when
    # the user picks a source, or past the server's time limit). Emby,
    # Jellyfin and Silo lookups never polled it, so a show with many copies
    # kept resolving episodes after playback had started.
    _stop_signal = (server or {}).get('_should_stop') if isinstance(server, dict) else None

    def _stopped(where):
        if _stop_signal is None:
            return False
        try:
            if _stop_signal():
                if not server.get('_stop_logged'):
                    server['_stop_logged'] = True
                    xbmc.log('[DexHub] %s lookup stopped at %s: search cancelled or over budget (%s)'
                             % (backend, where, server.get('name') or '?'), xbmc.LOGINFO)
                return True
        except Exception:
            pass
        return False

    # 2) BY TITLE. Jellyfin tries local names first: remote enrichment only
    # follows an actual miss, inside this worker's existing time budget.
    def _title_candidates():
        nonlocal titles
        if backend != 'jellyfin' and titles_loader is not None:
            try:
                titles = titles_loader() or titles
            except Exception:
                pass
        used = set()
        for candidate in (titles or []):
            value = str(candidate or '').strip()
            if backend == 'jellyfin' and re.fullmatch(r'(?:tt\d+(?::\d+){0,2}|(?:imdb|tmdb|tvdb):.*)', value, flags=re.I):
                continue
            if value and value.casefold() not in used:
                used.add(value.casefold())
                yield value
        if backend == 'jellyfin' and not matches and titles_loader is not None and time.time() < _deadline and not _stopped('title-enrichment'):
            try:
                loaded = titles_loader() or []
            except Exception:
                loaded = []
            for candidate in loaded:
                value = str(candidate or '').strip()
                if value and value.casefold() not in used and not re.fullmatch(r'(?:tt\d+(?::\d+){0,2}|(?:imdb|tmdb|tvdb):.*)', value, flags=re.I):
                    used.add(value.casefold())
                    titles = list(titles or []) + [value]
                    yield value

    if not matches and time.time() < _deadline:
        for title in _title_candidates():
            if not str(title or '').strip():
                continue
            if time.time() >= _deadline:
                xbmc.log('[DexHub] %s lookup: budget spent — stopping so the '
                         'Stremio providers keep their time' % backend, xbmc.LOGINFO)
                break
            if _stopped('title-search'):
                break
            try:
                with _bounded(_per_request):
                    options = {'year': year} if backend == 'jellyfin' else {}
                    _take(client.find_all_by_ids(server, ids, media_type=kind,
                                                 title=title, limit=24, **options))
            except Exception:
                continue
            # v3.9.222: do NOT stop at the first title that hits. A library
            # routinely holds the same film twice — once under its Arabic name
            # and once under its English one — and each copy is a real source.

    xbmc.log('[DexHub] %s lookup: server=%s ids=%s titles=%d -> %d item(s)'
             % (backend, server.get('name') or '?',
                ','.join('%s=%s' % (k, v) for k, v in sorted((ids or {}).items()) if v) or 'none',
                len(titles or []), len(matches)), xbmc.LOGINFO)
    if not matches:
        return []

    # 3) walk to the exact episode when needed
    items = []
    for index, match in enumerate(matches):
        if series and _stopped('episode-walk %d/%d' % (index, len(matches))):
            break
        if series:
            try:
                # v5.10.241: bounded like the title searches, so a scan the
                # user ended (a source chosen) stops here quickly
                with _bounded(_per_request):
                    row = client.episode_item(server, match, season, episode)
            except Exception:
                row = None
            if not row:
                continue
            if _stopped('episode-walk %d/%d' % (index, len(matches))):
                break
            # v5.10.91: Emby/Jellyfin return the episode WITH its MediaSources
            # and their MediaStreams (DETAIL_FIELDS), so the second request per
            # copy only re-read the same record. Plex and Silo keep the full
            # fetch: their episode listings omit the stream details.
            if backend in ('emby', 'jellyfin') and row.get('versions'):
                items.append(row)
                continue
            try:
                items.append(client.metadata(server, row.get('rating_key')))
            except Exception:
                items.append(row)
        else:
            items.append(match)
    return items

def _emby_stream_payload(provider, media_type):
    """Emby/Silo versions as normal Dex Hub source rows.

    Every MediaSource becomes a stream carrying its real file size, so ranking,
    badges, the switch-source index and resume all work with no special cases.
    """
    server = provider.get('_server') or {}
    backend = {'__silo__': 'silo', '__jellyfin__': 'jellyfin'}.get((provider or {}).get('id'), 'emby')
    client = _server_client(backend)
    brand = backend.upper()
    colour = 'FF7C3AED' if backend == 'silo' else EMBY_COLOR
    title = provider.get('_title') or ''
    from .search.native_titles import resolve as _native_titles
    titles = list(provider.get('_titles') or [])
    if title and title.casefold() not in [str(x).casefold() for x in titles]:
        titles.insert(0, title)
    if not titles and title:
        titles = [title]
    ids = provider.get('_ids') or {}
    season, episode = provider.get('_season'), provider.get('_episode')
    if not (ids.get('imdb_id') or ids.get('tmdb_id') or title):
        return {}
    series = _is_series_media(media_type) and season and episode
    items = _server_stream_rows(
        backend, server, ids, media_type, titles,
        season=season, episode=episode, year=provider.get('_year') or '',
        titles_loader=lambda: _native_titles(provider, media_type, _tmdb_direct))
    if not items:
        return {}
    server_name = server.get('name') or ('Silo' if backend == 'silo' else 'Emby')
    streams = []
    for item in items:
      for version in (item.get('versions') or []):
        url = client.playback_url(server, item.get('rating_key'),
                                       version.get('media_source_id') or '')
        fname = os.path.basename(version.get('file') or '') or (item.get('raw_title') or title)
        facts = ' '.join(x for x in (version.get('resolution'), version.get('hdr'),
                                     version.get('video_codec'), version.get('audio'),
                                     version.get('size_label')) if x)
        streams.append({
            'name': '[COLOR %s]%s NATIVE[/COLOR]\n%s' % (colour, brand, ' • '.join(x for x in (server_name, item.get('library_name')) if x)),
            'title': '%s\n%s' % (fname, facts),
            'url': url,
            'subtitles': list(version.get('subtitles') or []),
            'behaviorHints': {
                'filename': fname,
                'videoSize': version.get('size_bytes') or 0,
                'nativeProvider': backend,
                'serverType': backend,
                'serverUrl': server.get('url') or '',
                'serverId': str(server.get('id') or ''),
                'token': server.get('token') or '',
                'itemId': str(item.get('rating_key') or ''),
                'mediaSourceId': str(version.get('media_source_id') or ''),
                'imdbId': _normalize_imdb_id((item.get('ids') or {}).get('imdb_id')) or '',
                'tmdbId': str((item.get('ids') or {}).get('tmdb_id') or ''),
                'tvdbId': str((item.get('ids') or {}).get('tvdb_id') or ''),
                'showImdbId': _normalize_imdb_id(ids.get('imdb_id')) or '',
                'showTmdbId': str(ids.get('tmdb_id') or ''),
                'showTvdbId': str(ids.get('tvdb_id') or ''),
                'durationMs': int(item.get('duration_ms') or 0),
            },
        })
    return {'streams': streams}

def _plex_stream_payload(provider, media_type):
    """Built-in Plex source step (DPlex trakttokodi-style, v3.9.172).

    GUID-matches the current item on ONE server and returns every file
    version as a Stremio-shaped stream, so Plex copies flow through the
    normal source pipeline — ranking, badges, size parsing, the switch
    index and companion progress all apply with zero special cases.
    """
    server = provider.get('_server') or {}
    title = provider.get('_title') or ''
    from .search.native_titles import resolve as _native_titles
    titles = list(provider.get('_titles') or [])
    if title and title.casefold() not in [str(x).casefold() for x in titles]:
        titles.insert(0, title)
    if not titles and title:
        titles = [title]
    ids = provider.get('_ids') or {}
    wanted_year = str(provider.get('_year') or '').strip()
    season, episode = provider.get('_season'), provider.get('_episode')
    want_imdb = str(ids.get('imdb_id') or '').lower()
    want_tmdb = str(ids.get('tmdb_id') or '')
    want_tvdb = str(ids.get('tvdb_id') or '')
    if not title and not (want_imdb or want_tmdb or want_tvdb):
        return {}

    def _ids_match(it):
        iid = it.get('ids') or {}
        return ((want_imdb and str(iid.get('imdb_id') or '').lower() == want_imdb) or
                (want_tmdb and str(iid.get('tmdb_id') or '') == want_tmdb) or
                (want_tvdb and str(iid.get('tvdb_id') or '') == want_tvdb))

    # v3.9.218: the SAME lookup Emby uses — ID first, titles only as a
    # fallback. The 90 lines this replaces searched Plex by TITLE, which is
    # why an Arabic query never matched an English library and every server
    # answered 'no match' after 14 seconds.
    target_items = _server_stream_rows(
        'plex', server, ids, media_type, titles,
        season=season, episode=episode,
        titles_loader=lambda: _native_titles(provider, media_type, _tmdb_direct))

    if not target_items:
        xbmc.log('[DexHub] Plex Native no match: server=%s title=%s ids=%s' % (
            server.get('name') or '?', title,
            ','.join('%s=%s' % (key, ids.get(key))
                     for key in ('imdb_id', 'tmdb_id', 'tvdb_id') if ids.get(key)) or 'none'),
            xbmc.LOGWARNING)
        return {}
    server_name = server.get('name') or 'Plex'
    streams = []
    for target_item in target_items:
        try:
            item = plex_client.metadata(server, target_item.get('rating_key'))
        except Exception as exc:
            xbmc.log('[DexHub] Plex Native metadata failed: server=%s key=%s error=%s' % (
                server_name, target_item.get('rating_key') or '?', exc), xbmc.LOGWARNING)
            continue
        for version in (item.get('versions') or []):
            if not version.get('part_key'):
                continue
            try:
                url = plex_client.playback_url(item, part_key=version['part_key'])
            except Exception:
                continue
            fname = os.path.basename(version.get('file') or '') or (item.get('raw_title') or title)
            facts = ' '.join(x for x in (version.get('resolution'), version.get('hdr'),
                                         version.get('video_codec'), version.get('audio'),
                                         version.get('size_label')) if x)
            streams.append({
                'name': '[COLOR %s]PLEX NATIVE[/COLOR]\n%s' % (PLEX_COLOR, ' • '.join(x for x in (server_name, item.get('library_name')) if x)),
                'title': '%s\n%s' % (fname, facts),
                'url': url,
                'subtitles': list(version.get('subtitles') or []),
                'behaviorHints': {
                    'filename': fname,
                    'videoSize': version.get('size_bytes') or 0,
                    'nativeProvider': 'plex',
                    'serverType': 'plex',
                    'serverUrl': item.get('server_url') or server.get('url') or '',
                    'serverId': str(server.get('id') or ''),
                    'token': item.get('token') or server.get('token') or '',
                    'ratingKey': str(item.get('rating_key') or target_item.get('rating_key') or ''),
                    'partKey': str(version.get('part_key') or ''),
                    'imdbId': _normalize_imdb_id((item.get('ids') or {}).get('imdb_id')) or '',
                    'tmdbId': str((item.get('ids') or {}).get('tmdb_id') or ''),
                    'tvdbId': str((item.get('ids') or {}).get('tvdb_id') or ''),
                    'showImdbId': _normalize_imdb_id(ids.get('imdb_id')) or '',
                    'showTmdbId': str(ids.get('tmdb_id') or ''),
                    'showTvdbId': str(ids.get('tvdb_id') or ''),
                    'durationMs': int(item.get('duration_ms') or 0),
                },
            })
    return {'streams': streams}

def _fetch_stream_payload(target, media_type):
    from . import source_diagnostics as diagnostics
    handle = diagnostics.begin(target, media_type)
    result = None
    try:
        result = _fetch_stream_payload_inner(target, media_type)
        return result
    except Exception as exc:
        result = exc
        raise
    finally:
        diagnostics.finish(handle, result)

def _fetch_stream_payload_inner(target, media_type):
    from .search.source_engine import fetch
    return fetch(target, media_type, sys.modules[__name__])

_ALT_ID_MAX_PARALLEL = 3

def _fetch_alternate_ids_parallel(provider, media_type, alt_ids, timeout):
    """Try the remaining candidate ids at once; return the first with rows.

    Returns ``(payload, winning_id, last_exception)``. ``payload`` is None when
    no alternate produced any playable row. Threads are daemons and are joined
    only for the provider timeout, so a hung addon cannot extend the scan.
    """
    alt_ids = list(alt_ids or [])[:_ALT_ID_MAX_PARALLEL]
    if not alt_ids:
        return None, '', None
    results = {}
    lock = threading.Lock()

    def _one(index, rid):
        try:
            payload = _stremio_provider.fetch(
                provider, media_type, rid, timeout_override=timeout)
            rows = ((payload or {}).get('streams') or []) if isinstance(payload, dict) else []
            if isinstance(rows, dict):
                rows = [rows]
            if rows:
                with lock:
                    results[index] = (payload, rid)
        except Exception as exc:
            with lock:
                results.setdefault('exc', exc)

    threads = []
    for index, rid in enumerate(alt_ids):
        try:
            thread = threading.Thread(
                target=_one, args=(index, rid),
                name='DexHubAltId%d' % index, daemon=True)
            thread.start()
            threads.append(thread)
        except RuntimeError:
            # Out of threads: run this one inline rather than skipping the id.
            _one(index, rid)
    deadline = time.monotonic() + max(1.0, float(timeout or 0.0))
    for thread in threads:
        thread.join(max(0.0, deadline - time.monotonic()))
    with lock:
        hits = sorted(k for k in results if isinstance(k, int))
        if hits:
            # Candidate ids arrive pre-ranked, so the earliest index wins.
            payload, rid = results[hits[0]]
            xbmc.log('[DexHub] alternate id resolved: provider=%s id=%s (%d tried in parallel)'
                     % ((provider or {}).get('name') or '?', rid, len(alt_ids)), xbmc.LOGINFO)
            return payload, rid, None
        return None, '', results.get('exc')

def _native_payload_budgeted(provider, media_type, backend, budget_seconds):
    """Run a native Plex/Emby lookup under a wall-clock ceiling.

    Used only for servers the health router has marked cold. The worker is a
    daemon and is never joined past the budget, so a slow title scan cannot
    hold the source scan open; if it finishes late its result is simply
    discarded, exactly like the Plex discovery budget above.
    """
    out = {}

    def _worker():
        try:
            out['payload'] = (_plex_stream_payload(provider, media_type)
                              if backend == 'plex'
                              else _emby_stream_payload(provider, media_type))
        except Exception as exc:
            out['exc'] = exc

    try:
        thread = threading.Thread(
            target=_worker, name='DexHubColdNative', daemon=True)
        thread.start()
    except RuntimeError:
        # Out of threads: run inline rather than losing the server entirely.
        return (_plex_stream_payload(provider, media_type) if backend == 'plex'
                else _emby_stream_payload(provider, media_type))
    thread.join(max(0.5, float(budget_seconds or 0.0)))
    if thread.is_alive():
        xbmc.log('[DexHub] %s cold server exceeded its %.0fs budget — moving on'
                 % (backend, budget_seconds), xbmc.LOGINFO)
        # v5.10.91: tell the caller WHY there is nothing, so a lookup that ran
        # out of time is not recorded as a scan that found nothing. Asking the
        # stop signal once also flags the running worker to stop.
        reason = 'deadline'
        try:
            srv = (provider or {}).get('_server') or {}
            stop = srv.get('_should_stop')
            if stop is not None:
                stop()
            if srv.get('_stop_reason') == 'cancelled':
                reason = 'cancelled'
        except Exception:
            pass
        return {'streams': [], '_source_status': reason}
    if out.get('exc') is not None:
        raise out['exc']
    return out.get('payload') or {'streams': []}

def _source_parallel_workers(target_count=0):
    """Worker budget for stream-source scans.

    v3.9.87: CoreELEC boxes can hit "can't start new thread" when several
    plugin invokers, source refreshes and subtitle workers overlap. Keep source
    discovery parallel, but use a fixed 2-4 worker envelope.  Subtitle lookup
    now runs at the same time, so retaining the old six-stream-worker ceiling
    would recreate the CoreELEC thread spike through a different path.
    """
    try:
        base = int(float(ADDON.getSetting('parallel_workers') or parallel_workers() or 4))
    except Exception:
        try:
            base = int(parallel_workers() or 4)
        except Exception:
            base = 4
    workers = max(2, base)
    if target_count:
        workers = min(workers, max(1, int(target_count)))
    return max(1, min(4, workers))

def _source_quick_open_seconds():
    """How long to keep collecting after the first rows before opening UI.

    It is a short post-first-result grace; late providers continue through the
    live session refresh after the source window opens.
    """
    try:
        raw = float(ADDON.getSetting('streams_quick_open_seconds') or 0.3)
    except Exception:
        raw = 0.3
    # This is a post-first-result grace, not a minimum loading screen. The
    # settings UI allows 0.3s; honour it instead of silently clamping the
    # fast path. Providers keep filling the live source window afterwards.
    return max(0.3, min(raw, 4.0))

def _source_result_goal():
    """Unique-row threshold for the cinematic source-search screen.

    Kodi enum values are stored as zero-based indices.  A goal of ``0`` means
    patient mode: do not early-open; wait for every source (bounded by the
    existing global source timeout).
    """
    try:
        raw = str(ADDON.getSetting('streams_result_goal') or '1').strip()
        idx = int(float(raw))
    except Exception:
        idx = 1
    # The shipped default index used to mean 20 rows. Opening the live picker
    # should not wait for a large aggregator dump: ten distinct rows are
    # already enough to choose, and every pending provider continues filling
    # the same window in the background.
    return {0: 4, 1: 4, 2: 10, 3: 0}.get(idx, 4)

def _source_enough_wait_seconds():
    try:
        raw = float(ADDON.getSetting('streams_enough_wait_seconds') or 5.0)
    except Exception:
        raw = 5.0
    # This is only the foreground wait. The existing race remains alive and
    # slow providers keep publishing into the open source window.
    return max(1.5, min(raw, 4.0))

def _source_progress_unique_count(entries, out=None):
    """Return the post-dedup count without ranking or rebuilding UI rows.

    v5.10.438: ``out`` (a list) receives the rows the count stands for, so
    the search screen can show how many are 4K, 1080p, cached and so on."""
    rows = list(entries or [])
    try:
        rows, _removed = _collapse_repeated_provider_rows(rows)
    except Exception:
        pass
    try:
        mode = _dedup_mode()
        if mode != 'off':
            order = (ADDON.getSetting('source_priority_order') or '')
            rows, _removed = dedupe_stream_entries(
                rows, mode=mode,
                priority=[part.strip().lower() for part in order.split(',') if part.strip()],
            )
    except Exception:
        pass
    if out is not None:
        out[:] = rows
    return len(rows)

def _collect_stream_entries(targets, media_type, canonical_id, best_meta, art, bg, ids, title='',
                            video_id='', season=None, episode=None, show_title='', resume_seconds=0.0,
                            resume_percent=0.0,
                            stop_after_first=False, show_loader=False,
                            processed_targets=None, scan_state=None, progress=None):
    entries = []
    if not targets:
        return entries

    loader_title = title or show_title or best_meta.get('name') or canonical_id or tr('المصادر')
    # v4.6.3: warm the MDBList aggregated-ratings cache in the background
    # while the providers are queried anyway. The picker's tmdbh_context
    # overlay only ever READS the warm cache (no network in its hot path) —
    # and since 4.2.2 nothing had ever warmed it, so the Letterboxd /
    # MDBList / MAL chips never rendered. Keyed by tmdb id first, exactly
    # like TMDb Helper's own MDBList lookups.
    try:
        from . import mdblist as _mdb_warm
        _mdb_warm.warm_ratings_async(
            imdb_id=(ids or {}).get('imdb_id') or '',
            media_type=media_type,
            tmdb_id=(ids or {}).get('tmdb_id') or '')
    except Exception as _silent_exc:
        log.silent('MDBLIST_WARM', _silent_exc)
    def _run(loader=None):
        # v3.9.43: hard global wall-clock ceiling. Per-provider timeouts
        # protect against any single provider hanging, but if many slow
        # providers each take the full per-provider timeout (which can
        # be 15 seconds for AIOStreams), the cumulative wait can feel
        # like a hang to the user. The ceiling forces the loop to exit
        # even if iter_parallel still has outstanding work. Twenty-five
        # seconds is generous for any realistic scan; the cancel and
        # "اكتفي بالموجود" buttons remain available throughout.
        import time as _t
        _started_at = _t.time()
        _hard_deadline = _started_at + 25.0
        _result_goal = _source_result_goal() if stop_after_first else 0
        _enough_wait = _source_enough_wait_seconds() if stop_after_first else 25.0
        _quick_grace = _source_quick_open_seconds() if stop_after_first else 0.0
        _parallel_timeout = (
            25.0 if (not stop_after_first or _result_goal == 0)
            else min(25.0, _enough_wait)
        )
        _unique_count = 0
        _source_race = start_parallel_race(
            lambda t: _fetch_stream_payload(t, media_type), targets,
            workers=_source_parallel_workers(len(targets)),
            # One race lives through both the foreground and live-refresh
            # phases, so slow aggregators are never requested twice.
            timeout=25.0, lane='streams',
        )

        for idx, (target, data) in enumerate(_iter_source_race(
                _source_race, lambda: _unique_count, lambda: bool(entries),
                _started_at, _parallel_timeout, stop_after_first,
                _result_goal, _quick_grace,
                should_stop=(loader.is_stopped if loader is not None else None),
                consume_continue=(loader.consume_continue_search if loader is not None else None),
                clear_sufficient=(loader.clear_sufficient if loader is not None else None),
                mark_sufficient=(lambda: loader.mark_sufficient(auto_seconds=0)
                                 if loader is not None else None),
            ), start=1):
            _now = _t.time()
            if _now > _hard_deadline:
                try:
                    xbmc.log('[DexHub] source gathering hit 25s hard ceiling — %d targets processed, %d entries gathered' % (idx, len(entries)), xbmc.LOGINFO)
                except Exception:
                    pass
                break
            provider, request_id = target
            request_id = str((provider or {}).get('_resolved_request_id') or request_id)
            if processed_targets is not None:
                try:
                    processed_targets.append(target)
                except Exception:
                    pass
            if loader is not None:
                # v3.9.32: respect either button. The XML now shows two:
                #   "اكتفي بالموجود" → stop scan, keep partial entries
                #   "إلغاء"            → stop scan AND drop entries (true abort)
                # is_stopped() is true for either; we differentiate after
                # the loop so the caller sees the right result list.
                if loader.is_stopped():
                    break
                loader.update(
                    provider_name=provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
                    index=idx,
                    status=tr('جار البحث عن المصادر...'),
                    sub_status='%d %s' % (len(entries), tr('مصدر')) if entries else '',
                )
            if isinstance(data, Exception) or not data:
                if progress is not None:
                    try:
                        progress(idx, len(targets), entries)
                    except Exception:
                        pass
                continue
            before = len(entries)
            _append_stream_entries_from_data(
                entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids,
                title=title, video_id=video_id, season=season, episode=episode, show_title=show_title,
                resume_seconds=resume_seconds, resume_percent=resume_percent,
            )
            if len(entries) > before:
                _unique_rows = []
                _unique_count = _source_progress_unique_count(entries, _unique_rows)
            else:
                _unique_rows = None
            if progress is not None:
                # v5.10.253: the player's Sources panel fills as each
                # provider answers
                try:
                    progress(idx, len(targets), entries)
                except Exception:
                    pass
            if loader is not None:
                loader.add_results(
                    len(entries) - before,
                    provider_name=provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
                    unique_total=_unique_count,
                    rows=_unique_rows,
                )
        if scan_state is not None:
            scan_state['race'] = _source_race
            scan_state['pending_targets'] = _source_race.pending_items()
        if (scan_state is None or
                (loader is not None and loader.is_cancelled())):
            _source_race.cancel()
        if loader is not None:
            # v3.9.32: if the user pressed the true Cancel button (not
            # "Use what's found"), wipe the partial entries so the
            # caller treats it as an aborted search rather than showing
            # half-scanned sources the user explicitly didn't want.
            if loader.is_cancelled():
                entries[:] = []
            loader.set_finalizing()

    if show_loader:
        # v5.10.15: hold the subtitle broker back while the loading screen is
        # the user's whole world. Released in the finally below, so a cancel,
        # a zero-result scan or an exception all still free it.
        try:
            from .playback.subtitle_files import hold_for_source_scan as _hold_subs
            _hold_subs()
        except Exception:
            pass
        # v3.9.59/v3.9.60: build the subtitle for the bottom-sheet
        # layout's hero area: "2023 • Drama, Sci-Fi • S2E5".
        try:
            sub_parts = []
            _year = best_meta.get('year') or best_meta.get('releaseInfo') or ''
            if _year:
                sub_parts.append(str(_year))
            _genres = best_meta.get('genres') or best_meta.get('genre') or []
            if isinstance(_genres, list) and _genres:
                sub_parts.append(', '.join(str(g) for g in _genres[:2] if g))
            elif isinstance(_genres, str) and _genres:
                sub_parts.append(_genres)
            if season is not None and episode is not None:
                try:
                    sub_parts.append('S%dE%d' % (int(season), int(episode)))
                except Exception:
                    pass
            loader_subtitle = '  •  '.join(sub_parts)
        except Exception:
            loader_subtitle = ''

        # v3.9.89: pass the raw addon poster + IDs to the dialog and let
        # it route through art.clean_poster (same policy as the results
        # window and the player overlay). MetaHub TMDb wins when IMDb is
        # known; addon URL when it's clearly not a logo; local portrait
        # placeholder otherwise. NEVER fanart/thumb — they are landscape
        # and render as a banner stuck at the top of an empty card.
        _media_type_for_loader = (
            (best_meta or {}).get('media_type')
            or (best_meta or {}).get('type')
            or media_type
            or 'movie'
        )
        # v4.6.0: full ordered provider list for the dashboard cards.
        _loader_names = []
        for _tgt in targets:
            try:
                _prov = _tgt[0] or {}
                _nm = str(_prov.get('name')
                          or (_prov.get('manifest') or {}).get('name') or '').strip()
            except Exception:
                _nm = ''
            if _nm and _nm not in _loader_names:
                _loader_names.append(_nm)
        with SourcesLoadingDialog(
            title=loader_title,
            subtitle=loader_subtitle,
            fanart=bg or (art or {}).get('fanart') or '',
            poster=(art or {}).get('poster') or '',
            clearlogo=(art or {}).get('clearlogo') or (art or {}).get('logo') or '',
            media_type=_media_type_for_loader,
            imdb_id=(ids or {}).get('imdb_id') or '',
            tmdb_id=(ids or {}).get('tmdb_id') or '',
            provider_count=len(targets),
            provider_names=_loader_names,
        ) as loader:
            try:
                _run(loader)
            finally:
                try:
                    from .playback.subtitle_files import release_source_scan as _release_subs
                    _release_subs()
                except Exception:
                    pass
    else:
        _run(None)
    return entries

_STREAM_REFRESH_SEM = threading.BoundedSemaphore(2)

def _start_stream_session_refresh(session_key, initial_entries, remaining_targets, media_type, canonical_id,
                                  best_meta, art, bg, ids, title='', video_id='', season=None,
                                  episode=None, show_title='', resume_seconds=0.0,
                                  resume_percent=0.0, scan_race=None):
    if not session_key or not remaining_targets:
        return

    def _worker():
        _acquired = False
        try:
            # Reused foreground futures already own their bounded stream lane;
            # consuming them needs no second network-refresh slot.
            if scan_race is None:
                try:
                    _acquired = _STREAM_REFRESH_SEM.acquire(timeout=1.5)
                except TypeError:
                    _acquired = _STREAM_REFRESH_SEM.acquire(False)
                if not _acquired:
                    xbmc.log('[DexHub] live source refresh slots busy; continuing in low-concurrency mode', xbmc.LOGINFO)
        except Exception:
            _acquired = False
        entries = list(initial_entries or [])
        version = 1
        last_request_id = str(video_id or '')
        refresh_race = scan_race
        pending_count = len(remaining_targets)
        failed_count = 0
        last_name = ''   # v5.10.439: the add-on that answered last (Halo)

        def _publish_status(done=False):
            nonlocal version
            version += 1
            return source_session.update(session_key, {
                'entries': list(entries), 'done': done, 'version': version,
                'search_pending': pending_count,
                'search_failed': failed_count,
                'search_last': last_name,
            })

        _publish_status()
        try:
            refresh_workers = (_source_parallel_workers(len(remaining_targets))
                               if _acquired else 1)
            if refresh_race is not None:
                # Reuse the live futures. Never re-submit: the originals are
                # still in flight and a second fetch would double the network,
                # the JSON walk and the UI work for the same rows.
                _continue = getattr(refresh_race, 'continue_in_background', None)
                if _continue is not None:
                    _continue(seconds=25.0)
                _iterator = refresh_race.iter_completed(timeout=25.0)
            else:
                # v5.10.15: no race to inherit (pre-cached entries, or a caller
                # that never ran a foreground scan). Only targets that were
                # genuinely never dispatched may be fetched here.
                xbmc.log('[DexHub] refresh handoff: NO race to reuse — dispatching %d target(s)'
                         % len(remaining_targets), xbmc.LOGINFO)
                refresh_race = start_parallel_race(
                    lambda t: _fetch_stream_payload(t, media_type),
                    remaining_targets, workers=refresh_workers, timeout=25.0,
                    lane='stream_refresh')
                _iterator = refresh_race.iter_completed(timeout=25.0)
            # Back closes the session synchronously. Registering the owned
            # race gives that action a direct cancellation path instead of
            # waiting for the next provider completion to notice the closure.
            source_session.register_cancel(session_key, refresh_race.cancel)
            for target, data in _iterator:
                # v5.10.15: the source window can be closed (or Kodi can move
                # on to another item) while slow providers are still answering.
                # The 5.10.14 log shows exactly that outcome: background work
                # outliving its window, then a stuck invoker on the next click
                # ("waiting on thread" + "Error resolving item") and an
                # "EXCEPTION: Window id does not exist" from a dead window.
                # Check every iteration, not just once before the loop.
                if not source_session.is_active(session_key):
                    xbmc.log('[DexHub] live source refresh stopped: session %s closed'
                             % session_key, xbmc.LOGINFO)
                    if refresh_race is not None:
                        try:
                            refresh_race.cancel()
                        except Exception:
                            pass
                    break
                try:
                    provider, request_id = target
                    request_id = str((provider or {}).get('_resolved_request_id') or request_id)
                except Exception:
                    continue
                last_request_id = str(video_id or request_id or last_request_id or '')
                pending_count = max(0, pending_count - 1)
                last_name = str((provider or {}).get('name') or '')
                if isinstance(data, Exception):
                    failed_count += 1
                if isinstance(data, Exception) or not data:
                    _publish_status()
                    continue
                # Closing can race with a just-completed future. Do not spend
                # CPU parsing/formatting hundreds of rows after the user left.
                if not source_session.is_active(session_key):
                    break
                before = len(entries)
                _append_stream_entries_from_data(
                    entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids,
                    title=title, video_id=video_id, season=season, episode=episode, show_title=show_title,
                    resume_seconds=resume_seconds, resume_percent=resume_percent,
                )
                if len(entries) == before:
                    _publish_status()
                    continue
                if not source_session.is_active(session_key):
                    break
                fresh = list(entries[before:])
                del entries[before:]
                entries.extend(_finalize_stream_entries(fresh, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id))
                version += 1
                if not source_session.update(session_key, {
                    'entries': _finalize_stream_entries(list(entries), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id),
                    'done': False,
                    'version': version,
                    'search_pending': pending_count,
                    'search_failed': failed_count,
                'search_last': last_name,
                }):
                    break

        finally:
            if refresh_race is not None:
                try:
                    refresh_race.cancel()
                except Exception:
                    pass
            try:
                source_session.update(session_key, {
                    'entries': _finalize_stream_entries(list(entries), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id),
                    'done': True,
                    'version': version + 1,
                    'search_pending': pending_count,
                    'search_failed': failed_count,
                'search_last': last_name,
                })
            except Exception:
                pass
            if _acquired:
                try:
                    _STREAM_REFRESH_SEM.release()
                except Exception:
                    pass

    try:
        threading.Thread(target=_worker, name='DexHubStreamRefresh', daemon=True).start()
    except RuntimeError as exc:
        try:
            xbmc.log('[DexHub] skipped background source refresh: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass
        try:
            source_session.update(session_key, {
                'entries': _finalize_stream_entries(list(initial_entries or []), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=str(video_id or '')),
                'done': True,
                'version': 2,
                'search_pending': len(remaining_targets),
                'search_failed': 0,
            })
        except Exception:
            pass

def _full_parallel_source_scan_enabled():
    """Optional patient mode: wait for all providers before opening results."""
    try:
        raw = (ADDON.getSetting('streams_full_parallel_scan') or 'false').strip().lower()
    except Exception:
        return False
    return raw in ('true', '1', 'yes', 'on')

def _is_suspect_logo_poster(url):
    """v3.9.85: detect URLs that look like addon icons/logos rather than
    real movie/TV posters. Several Stremio addons (notably some Arabic
    anime addons and small streaming providers) return their OWN logo
    as the poster when their meta record for an item lacks a real one.
    We never want such logos to show in the loading dialog, the source
    picker, or the player overlay — they look broken and identical for
    every item from that addon. The check is two-tier:

      1. Allow-list known reliable poster CDNs (TMDb, MetaHub, Fanart.tv,
         Amazon Images, Imgur). These never get filtered.
      2. Reject URLs matching common addon-icon patterns: paths ending
         in /icon.png, /logo.png, /addon.png, /favicon.*, or containing
         '/logo' or '/icon' segments.

    Returns True if the URL should be treated as a logo (and therefore
    rejected as a poster). False = the URL is fine to use as a poster.
    """
    if not url or not isinstance(url, str):
        return False
    url_low = url.lower()
    safe_hosts = (
        'image.tmdb.org', 'images.metahub.space', 'media-amazon.com',
        'm.media-amazon.com', 'img.youtube.com', 'i.imgur.com',
        'fanart.tv', 'assets.fanart.tv', 'static.metahub.space',
        'image.com', 'imgcdn', 'imageapi',
    )
    for h in safe_hosts:
        if h in url_low:
            return False
    suspect_endings = (
        '/icon.png', '/icon.jpg', '/icon.jpeg', '/icon.webp',
        '/logo.png', '/logo.jpg', '/logo.jpeg', '/logo.webp',
        '/addon.png', '/addon.jpg',
        '/favicon.png', '/favicon.ico', '/favicon.jpg',
        '/poster.png', '/poster.jpg',
        '/banner.png', '/banner.jpg',
    )
    for ending in suspect_endings:
        if url_low.endswith(ending):
            return True
    # Path-segment match — catches /icon/, /logo/, /branding/ subpaths
    for seg in ('/logo/', '/icon/', '/icons/', '/branding/', '/brand/', '/assets/icon'):
        if seg in url_low:
            return True
    return False

def _clean_poster(url, fallback='', imdb_id=''):
    """v3.9.86: poster sourcing with TMDb-first preference.

    Order of preference:
      1. TMDb/MetaHub clean URL if imdb_id is available — most reliable
         source for movie/TV posters, covers ~all titles with an IMDb
         entry, never returns addon logos. MetaHub is the same CDN
         Stremio's official Cinemeta addon uses, keyed by IMDb ID.
      2. The addon-provided URL if it passes the logo-suspect check —
         catches the case where TMDb has no entry but a niche addon
         (anime fan-database, fan-translated content, etc.) does have
         a real poster.
      3. The supplied fallback (typically the fanart/background image
         so the loading dialog and player overlay still show something
         visual even when both sources fail).

    The previous v3.9.85 behaviour was the addon URL first with logo
    filtering. That worked but exposed users to the addon-logo problem
    whenever the addon URL passed the heuristic by luck (e.g. hosted
    on imgur). The user-reported case was an Arabic anime addon
    returning its orange fox icon for the live-action show "FROM";
    moving TMDb to first place fixes that class of issue at the source
    instead of relying on URL pattern detection.
    """
    # Tier 1: TMDb/MetaHub clean URL
    imdb_id = (imdb_id or '').strip()
    if imdb_id.startswith('tt') and len(imdb_id) >= 4:
        return _METAHUB_POSTER % imdb_id
    # Tier 2: addon-provided URL, if not suspect
    if url and not _is_suspect_logo_poster(url):
        return url
    if url:
        try:
            xbmc.log('[DexHub] rejected suspect addon-logo poster: %s' % url[:120], xbmc.LOGINFO)
        except Exception:
            pass
    # Tier 3: caller-supplied fallback
    return fallback or ''

def _quick_to_results_enabled():
    """Default to fast parallel opening with live background completion.

    Full-scan mode is still available for users who prefer waiting up front.
    """
    if _full_parallel_source_scan_enabled():
        return False
    try:
        raw = (ADDON.getSetting('streams_quick_to_results') or 'true').strip().lower()
    except Exception:
        return True

    return raw in ('true', '1', 'yes', 'on')

def _source_scan_cancelled():
    """True when the user backed out of the source scan on purpose.

    v3.9.227: pressing Back mid-scan produced "playback failed" — wrong and
    alarming. The user did not fail; they left. Only a scan that ran to
    completion and genuinely found nothing deserves an error.
    """
    try:
        if xbmc.Monitor().abortRequested():
            return True
    except Exception:
        pass
    for prop in ('dexhub.sources.cancelled', 'dexhub.sources.stopped'):
        try:
            if (xbmcgui.Window(WINDOW_ID).getProperty(prop) or '') == '1':
                return True
        except Exception:
            continue
    return False

def _server_direct_entry(canonical_id, media_type, season=None, episode=None):
    """Play a server item DIRECTLY when the source scan comes back empty.

    v3.9.207 — the honest fix for content that lives ONLY on the user's server.

    A Turkish series with no IMDb/TMDb entry cannot be matched by any Stremio
    addon, and the id-based lookup inside the native Plex/Emby source step has
    nothing to match on either — so the scan ends with zero sources and the
    item simply refuses to play. But we do not NEED to search: the item came
    from the server, we hold its rating key, and the file is right there.

    So when the canonical id IS a server id (`plex:<server>:<key>` /
    `emby:<key>`), resolve the file straight from that server and hand back one
    ready-to-play entry. Identified content is untouched — this only runs after
    everything else has already returned nothing.
    """
    cid = str(canonical_id or '')
    if not cid.startswith(('plex:', 'emby:')):
        return []
    try:
        backend, rest = cid.split(':', 1)
        if backend == 'plex':
            server_id, rating_key = rest.split(':', 1)
            server = _plex_server(server_id)
            item = plex_client.metadata(server, rating_key)
            versions = [v for v in (item.get('versions') or []) if v.get('part_key')]
            make_url = lambda v: plex_client.playback_url(item, part_key=v['part_key'])
            poster = plex_client.artwork_url(item, item.get('thumb') or '')
            label = 'PLEX NATIVE'
            colour = PLEX_COLOR
            server_name = server.get('name') or 'Plex'
        else:
            rating_key = rest
            server = _emby_server()
            item = emby_client.metadata(server, rating_key)
            versions = [v for v in (item.get('versions') or []) if v.get('media_source_id')]
            make_url = lambda v: emby_client.playback_url(
                server, item.get('rating_key'), v.get('media_source_id') or '')
            poster = emby_client.artwork_url(server, item.get('thumb') or '')
            label = 'EMBY NATIVE'
            colour = EMBY_COLOR
            server_name = server.get('name') or 'Emby'
    except Exception as exc:
        xbmc.log('[DexHub] direct server play unavailable: %s' % exc, xbmc.LOGWARNING)
        return []

    if not versions:
        return []

    entries = []
    for version in versions:
        try:
            url = make_url(version)
        except Exception:
            continue
        name = os.path.basename(version.get('file') or '') or (
            item.get('raw_title') or item.get('title') or 'Direct')
        facts = version.get('info_line') or ''
        payload = {
            'stream_url': url,
            'name': name,
            'title': item.get('title') or '',
            'poster': poster,
            'provider_name': '%s \u2022 %s' % (
                'Plex' if label.startswith('PLEX') else 'Emby', server_name),
            'subtitles': list(version.get('subtitles') or []),
            'size_label': version.get('size_label') or '',
        }
        entries.append({
            'stream_key': cache_store.put('stream', payload),
            'name': '[COLOR %s]%s[/COLOR]  %s' % (colour, label, name),
            'quality': version.get('resolution') or '',
            'provider': 'PLEX' if label.startswith('PLEX') else 'EMBY',
            'provider_name_raw': payload['provider_name'],
            'addon': payload['provider_name'],
            'source_site': server_name,
            'size_label': version.get('size_label') or '',
            'size_bytes': version.get('size_bytes') or 0,
            'filename': name,
            'label2': '%s \u2022 %s' % (facts, payload['provider_name']) if facts
                      else payload['provider_name'],
            'source_info': facts,
            'stream_url': url,
        })
    xbmc.log('[DexHub] direct server play: %d version(s) for %s'
             % (len(entries), cid), xbmc.LOGINFO)
    return entries

def streams(media_type, canonical_id, title='', resume_seconds='0', resume_percent='', preferred_provider_name='', source_provider_id='', source_mode='', seed_ids=None, ui_seed=None):
    _prepare_started = time.monotonic()
    from . import source_diagnostics
    source_diagnostics.reset()
    _clear_source_transient_props(clear_global=False)
    _mark_interactive_busy()
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    best_meta, has_cached_meta = _fast_meta_for_sources(media_type, canonical_id, providers, title=title, source_provider_id=source_provider_id, seed_ids=seed_ids)
    xbmc.log('[DexHub timing] stage=source-meta ms=%.1f' % ((time.monotonic() - _prepare_started) * 1000), xbmc.LOGINFO)
    best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, media_type)
    art = _resolve_meta_art(providers[0] if providers else {}, media_type, best_meta, fallback_art=provider_fb,
                            lazy=bool((best_meta or {}).get('poster'))) if has_cached_meta else dict(provider_fb)
    art = _prefer_item_art(art, best_meta, media_type, fallback_art=provider_fb)
    art = _merge_ui_seed_into_art(art, ui_seed)
    art = _source_ui_art(art, provider_fb)
    ids = _merge_seed_ids(_merge_seed_ids(extract_ids(best_meta), seed_ids or {}), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    # Subtitle discovery is independent from the chosen release. Start it at
    # the same moment as stream discovery so one fixed five-second budget
    # covers both phases. Source/native sidecars are still merged only after
    # the user picks the exact stream.
    try:
        start_subtitle_prefetch(
            media_type, canonical_id, ids=ids,
            title=title or best_meta.get('name') or best_meta.get('title') or canonical_id,
        )
    except Exception as exc:
        xbmc.log('[DexHub] source-scan subtitle prefetch failed: %s' % exc,
                 xbmc.LOGDEBUG)
    _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    win = xbmcgui.Window(WINDOW_ID)
    logo = art.get('clearlogo') or ''
    win.setProperty('clearlogo', logo)
    win.setProperty('tvshow.clearlogo', logo)
    bg = _content_background(art, provider_fb)
    win.setProperty('fanart', bg)
    win.setProperty('poster', art.get('poster') or '')
    try:
        resume_seconds = float(resume_seconds or 0.0)
    except Exception:
        resume_seconds = 0.0
    try:
        resume_percent_val = float(resume_percent or 0.0)
    except Exception:
        resume_percent_val = 0.0
    targets_all = _prioritize_provider_targets(list(_stream_provider_targets(media_type, canonical_id, meta=stream_meta)), preferred_provider_name=preferred_provider_name)
    targets_all, _kodi_late = _kodi_sources_lane(targets_all, media_type)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    xbmc.log('[DexHub timing] stage=source-prepare-total ms=%.1f' % ((time.monotonic() - _prepare_started) * 1000), xbmc.LOGINFO)

    # v3.9.65: race all candidate providers and open the source picker
    # as soon as the FIRST entry arrives (instead of waiting for every
    # provider). Slow providers continue to fill the live results window
    # through the existing stream_session refresh thread, and the user
    # can click any source the moment it appears.
    _quick = _quick_to_results_enabled()
    loading_art = _loading_art_fast(media_type, best_meta, art, bg, ids, title=title or canonical_id)
    art = _merge_ui_seed_into_art(art, loading_art)
    bg = loading_art.get('fanart') or bg
    processed_targets = []
    scan_state = {}
    entries = _collect_stream_entries(
        targets, media_type, canonical_id, best_meta, art, bg, ids,
        title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
        stop_after_first=_quick, processed_targets=processed_targets,
        scan_state=scan_state,
    )
    _active_race = scan_state.get('race')
    if _active_race is not None:
        remaining_targets = _active_race.pending_items()
    else:
        processed_set = set((id(p), rid) for p, rid in processed_targets)
        remaining_targets = [t for t in targets if (id(t[0]), t[1]) not in processed_set]
    if not entries and fallback_targets:
        processed_targets = []
        try:
            if _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        scan_state = {}
        entries = _collect_stream_entries(
            fallback_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
            stop_after_first=_quick, processed_targets=processed_targets,
            scan_state=scan_state,
        )
        _active_race = scan_state.get('race')
        if _active_race is not None:
            remaining_targets = _active_race.pending_items()
        else:
            processed_set = set((id(p), rid) for p, rid in processed_targets)
            remaining_targets = [t for t in fallback_targets if (id(t[0]), t[1]) not in processed_set]
    if not entries and _kodi_late:
        entries = _kodi_collect(_kodi_late, _kodi_rows_converter(
            media_type, canonical_id, best_meta, art, bg, ids, title=title,
            resume_seconds=resume_seconds, resume_percent=resume_percent_val))
        _kodi_late = None
    if not entries:
        # Nothing matched anywhere — but if this item CAME from the user's own
        # server we do not need a match at all: play the file directly.
        entries = _server_direct_entry(canonical_id, media_type)
    if not entries:
        try:
            if _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        if _source_scan_cancelled():
            xbmc.log('[DexHub] source scan cancelled by the user — no error', xbmc.LOGINFO)
            if HANDLE >= 0:
                try:
                    xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
                except Exception:
                    pass
            return end_dir(cache=False)
        error(tr('لم يتم العثور على روابط تشغيل'))
        if HANDLE >= 0:
            try:
                xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
            except Exception:
                pass
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id)
    # Pull plot/year/genre/rating from best_meta so the source window can
    # render the redesigned hero panel (Plot textbox, year-genre-rating row).
    _genres = best_meta.get('genres') or []
    if isinstance(_genres, list):
        _genre_str = ' / '.join([str(g) for g in _genres[:3] if g])
    else:
        _genre_str = str(_genres or '')
    _year_val = ''
    _release = best_meta.get('releaseInfo') or best_meta.get('year') or ''
    if _release:
        _ymatch = YEAR_RE.search(str(_release))
        if _ymatch:
            _year_val = _ymatch.group(1)
    _rating = best_meta.get('imdbRating') or ''
    try:
        if _rating:
            _rating = '%.1f' % float(_rating)
    except Exception:
        _rating = str(_rating or '')
    _src_info = _stream_meta_info_payload(best_meta, media_type=media_type, title=title or best_meta.get('name') or canonical_id)
    _src_studio = _src_info.get('studio') or ''
    if isinstance(_src_studio, (list, tuple)):
        _src_studio = ' / '.join([str(x) for x in _src_studio if x])
    meta = {
        'title': title or best_meta.get('name') or canonical_id,
        'poster': art.get('poster') or provider_fb.get('poster') or provider_fb.get('thumb') or '',
        'fanart': _content_background(art, provider_fb),
        'clearlogo': art.get('clearlogo') or '',
        'plot': best_meta.get('description') or best_meta.get('overview') or '',
        'year': _year_val,
        'genre': _genre_str,
        'rating': _rating,
        'studio': _src_studio,
        'imdb_id': ids.get('imdb_id') or '',
        'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'media_type': media_type,
        'canonical_id': canonical_id,
    }
    session_key = ''
    if remaining_targets or _kodi_late:
        session_key = source_session.create(entries, done=False, version=1)
        if remaining_targets:
            _start_stream_session_refresh(
                session_key, entries, remaining_targets, media_type, canonical_id, best_meta, art, bg, ids,
                title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val,
                scan_race=_active_race,
            )
        if _kodi_late:
            _kodi_late.attach(session_key, _kodi_rows_converter(
                media_type, canonical_id, best_meta, art, bg, ids, title=title,
                resume_seconds=resume_seconds, resume_percent=resume_percent_val),
                base_done=not remaining_targets)
    return _show_stream_window(entries, meta, session_key=session_key)

def _video_season_num(video):
    """Season number of a Stremio video entry, with season 0 kept as 0.

    v3.9.239: both series_meta() and season() parsed this with a bare
    `or 1` fallback. JSON number 0 is falsy, so SPECIALS
    (season 0) were silently merged into Season 1 — polluting its episode list
    and letting a special "S01E01" collide with the real S01E01, which could
    send stream matching after the wrong video id. A string '0' did NOT trigger
    it (non-empty strings are truthy), so the bug was intermittent by provider.
    Missing/None/garbage still defaults to season 1.
    """
    raw = video.get('season')
    if raw is None or raw == '':
        return 1
    try:
        return int(raw)
    except Exception:
        return 1

def series_meta(media_type, canonical_id, title='', source_provider_id=''):
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    meta = None
    meta_provider = None
    for provider in providers:
        try:
            data = fetch_meta(provider, media_type, canonical_id, timeout_override=fast_timeout('meta'))
            meta = data.get('meta') or data.get('metas')
            if isinstance(meta, list):
                meta = meta[0] if meta else None
            if meta and meta.get('videos'):
                meta_provider = provider
                break
        except Exception:
            continue
    if not meta:
        error(tr('تعذر جلب بيانات المسلسل'))
        return end_dir()
    try:
        from . import meta_source as _meta_source
        if _is_virtual_meta_target(source_provider_id):
            meta = _meta_source.override_virtual_meta(source_provider_id, media_type, meta) or meta
        else:
            meta = _meta_source.override_meta(meta_provider or (providers[0] if providers else {}), media_type, meta) or meta
    except Exception:
        pass
    seasons = {}
    videos = meta.get('videos') or []
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id, json.dumps(videos))
    art_provider = meta_provider or (providers[0] if providers else {})
    provider_fb = _item_fallback_art(art_provider, media_type)
    series_art = _resolve_meta_art(art_provider, media_type, meta, fallback_art=provider_fb)
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.art', json.dumps(series_art))
    resolved_series_title = meta.get('name') or title or canonical_id
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.title', resolved_series_title)
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type', media_type or 'series')
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id', source_provider_id if _is_virtual_meta_target(source_provider_id) else ((art_provider or {}).get('id') or source_provider_id or ''))
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.native_art', '1' if (_provider_prefers_native_art(art_provider) or _provider_uses_explicit_meta_art(art_provider)) else '0')
    ids = _merge_seed_ids(extract_ids(meta), _get_tmdbh_seed_ids(canonical_id))
    for video in videos:
        season_num = _video_season_num(video)
        seasons.setdefault(season_num, []).append(video)
    for season_num in sorted(seasons.keys()):
        _season_label = 'حلقات خاصة' if season_num == 0 else (tr('الموسم %s') % season_num)
        add_item(
            _season_label,
            build_url(action='season', media_type=media_type, canonical_id=canonical_id, season=season_num, title=resolved_series_title),
            info={'title': _season_label, 'tvshowtitle': resolved_series_title, 'mediatype': 'season'},
            art=dict(series_art, thumb=series_art.get('poster'), icon=series_art.get('poster')),
            ids=ids,
        )
    end_dir(content='seasons')

def _precache_episode_async(canonical_id, video_id, season, episode, title='', media_type='series', delay_seconds=60):
    try:
        from . import precache_store as _pc
    except Exception:
        return
    try:
        season_i = int(season or 0)
        episode_i = int(episode or 0)
    except Exception:
        return
    if not canonical_id or season_i <= 0 or episode_i <= 0:
        return
    # Reserve the slot so a second trigger for the same episode (rare but
    # possible if the user replays) doesn't spin up a duplicate scrape.
    if not _pc.mark_inflight(canonical_id, season_i, episode_i):
        return

    def _worker():
        try:
            import time as _t
            if delay_seconds > 0:
                _t.sleep(delay_seconds)
            # Abort if Kodi is shutting down or the user already moved on to
            # something else mid-binge — no point scraping a stale next-up.
            try:
                if xbmc.Monitor().abortRequested():
                    return
            except Exception:
                pass
            try:
                xbmc.log('[DexHub] precache worker scraping s%se%s of %s'
                         % (season_i, episode_i, canonical_id), xbmc.LOGINFO)
            except Exception:
                pass
            # Replicate the early setup that episode_streams() does, but never
            # call into UI code (no loader, no picker open, no transient
            # property writes).
            providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id='')
            best_meta, _has = _fast_meta_for_sources(media_type, canonical_id, providers,
                                                     title=title or canonical_id, source_provider_id='')
            ids = _merge_seed_ids(extract_ids(best_meta), _get_tmdbh_seed_ids(canonical_id))
            ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id,
                                     title=title or best_meta.get('name') or best_meta.get('title') or '')
            stream_meta = _meta_with_seed_ids(best_meta, ids)
            direct_targets = []
            for provider in store.list_providers():
                if not _get_bool_setting('stremio_sources_enabled', True):
                    break
                if provider.get('enabled') is False or _source_left_out(provider):
                    continue
                if supports_resource(provider, 'stream', media_type=media_type, item_id=video_id):
                    direct_targets.append((provider, video_id))
            from .search.episode_route import merge_targets
            targets_all = merge_targets(_stream_provider_targets(
                media_type, canonical_id, meta=stream_meta, season=season_i, episode=episode_i),
                direct_targets)
            targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name='')
            targets, fallback_targets = _split_targets_by_source_mode(targets_all,
                                                                       source_provider_id='', source_mode='')
            if not targets and not fallback_targets:
                return
            # Silent scrape: show_loader=False. stop_after_first=False so the
            # pre-cache has the FULL list (no point cutting short when no user
            # is waiting). Empty art dicts because we don't need to write to UI.
            entries = _collect_stream_entries(
                targets, media_type, canonical_id, best_meta, {}, '', ids,
                title=title or video_id, video_id=video_id, season=season_i, episode=episode_i,
                show_title=best_meta.get('name') or canonical_id,
                resume_seconds=0.0, resume_percent=0.0,
                show_loader=False, stop_after_first=False, processed_targets=None,
            )
            if not entries and fallback_targets:
                entries = _collect_stream_entries(
                    fallback_targets, media_type, canonical_id, best_meta, {}, '', ids,
                    title=title or video_id, video_id=video_id, season=season_i, episode=episode_i,
                    show_title=best_meta.get('name') or canonical_id,
                    resume_seconds=0.0, resume_percent=0.0,
                    show_loader=False, stop_after_first=False, processed_targets=None,
                )
            if entries:
                _pc.put(canonical_id, season_i, episode_i, entries, meta=best_meta)
                try:
                    xbmc.log('[DexHub] precache STORED %d entries for s%se%s'
                             % (len(entries), season_i, episode_i), xbmc.LOGINFO)
                except Exception:
                    pass
            else:
                try:
                    xbmc.log('[DexHub] precache worker found 0 entries for s%se%s'
                             % (season_i, episode_i), xbmc.LOGWARNING)
                except Exception:
                    pass
        except Exception as exc:
            try:
                xbmc.log('[DexHub] precache worker crashed: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
        finally:
            try:
                _pc.release_inflight(canonical_id, season_i, episode_i)
            except Exception:
                pass

    import threading as _th
    try:
        t = _th.Thread(target=_worker, name='DexHubPrecache-s%se%s' % (season_i, episode_i))
        t.daemon = True
        t.start()
    except RuntimeError as exc:
        try:
            xbmc.log('[DexHub] skipped next-episode precache: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass

def episode_streams(canonical_id, video_id, season, episode, title='', media_type='', resume_seconds='0', resume_percent='', preferred_provider_name='', source_provider_id='', source_mode='', seed_ids=None, ui_seed=None):
    _prep_started = time.monotonic()
    from . import source_diagnostics
    source_diagnostics.reset()
    _clear_source_transient_props(clear_global=False)
    _mark_interactive_busy()
    media_type = media_type or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type') or 'series'
    source_provider_id = source_provider_id or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or ''
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    best_meta, has_cached_meta = _fast_meta_for_sources(media_type, canonical_id, providers, title=title or canonical_id, source_provider_id=source_provider_id, seed_ids=seed_ids)
    best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, media_type)
    art = _resolve_meta_art(providers[0] if providers else {}, media_type, best_meta, fallback_art=provider_fb,
                            lazy=bool((best_meta or {}).get('poster'))) if has_cached_meta else dict(provider_fb)
    art = _prefer_item_art(art, best_meta, media_type, fallback_art=provider_fb)
    art = _merge_ui_seed_into_art(art, ui_seed)
    art = _source_ui_art(art, provider_fb)
    ids = _merge_seed_ids(_merge_seed_ids(extract_ids(best_meta), seed_ids or {}), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    try:
        start_subtitle_prefetch(
            media_type, canonical_id, ids=ids,
            title=title or best_meta.get('name') or canonical_id,
            season=season, episode=episode,
        )
    except Exception as exc:
        xbmc.log('[DexHub] episode source-scan subtitle prefetch failed: %s' % exc,
                 xbmc.LOGDEBUG)
    _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    win = xbmcgui.Window(WINDOW_ID)
    logo = art.get('clearlogo') or ''
    win.setProperty('clearlogo', logo)
    win.setProperty('tvshow.clearlogo', logo)
    bg = _content_background(art, provider_fb)
    win.setProperty('fanart', bg)
    win.setProperty('poster', art.get('poster') or '')
    direct_targets = []
    for provider in store.list_providers():
        if not _get_bool_setting('stremio_sources_enabled', True):
            break
        if provider.get('enabled') is False or _source_left_out(provider):
            continue
        if _stremio_provider.supports_stream(provider, media_type, item_id=video_id):
            direct_targets.append((provider, video_id))
    try:
        resume_seconds = float(resume_seconds or 0.0)
    except Exception:
        resume_seconds = 0.0
    try:
        resume_percent_val = float(resume_percent or 0.0)
    except Exception:
        resume_percent_val = 0.0
    from .search.episode_route import merge_targets
    targets_all = merge_targets(
        _stream_provider_targets(media_type, canonical_id, meta=stream_meta, season=season, episode=episode),
        direct_targets)
    xbmc.log('[DexHub timing] stage=episode-source-preparation ms=%.1f' % (
        (time.monotonic() - _prep_started) * 1000), xbmc.LOGINFO)
    targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name=preferred_provider_name)
    targets_all, _kodi_late = _kodi_sources_lane(targets_all, media_type)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    # v3.9.65: same race strategy as movies — open the source picker
    # the moment the FIRST entry arrives (instead of waiting for every
    # provider). Especially valuable for NextUp/collection-driven
    # episode playback where the user wants to start watching ASAP.
    _quick = _quick_to_results_enabled()
    loading_art = _loading_art_fast(media_type, best_meta, art, bg, ids, title=title or best_meta.get('name') or canonical_id)
    art = _merge_ui_seed_into_art(art, loading_art)
    bg = loading_art.get('fanart') or bg

    # v3.9.104: pre-cache hit short-circuits the entire scrape. If the previous
    # episode's playback warmed sources for this one, we use them as-is and
    # the picker opens instantly. Cache miss falls through to the normal
    # network scrape unchanged.
    entries = None
    remaining_targets = []
    try:
        from . import precache_store as _pc
        _hit = _pc.consume(canonical_id, season, episode)
        if _hit:
            cached_entries, _cached_meta = _hit
            if cached_entries:
                entries = list(cached_entries)
                try:
                    xbmc.log('[DexHub] precache HIT for s%se%s (%d entries) — skipping live scrape'
                             % (season, episode, len(entries)), xbmc.LOGINFO)
                except Exception:
                    pass
    except Exception as _pc_exc:
        try:
            xbmc.log('[DexHub] precache lookup failed: %s' % _pc_exc, xbmc.LOGDEBUG)
        except Exception:
            pass

    processed_targets = []
    scan_state = {}
    if entries is None:
        entries = _collect_stream_entries(
            targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title or video_id, video_id=video_id, season=season, episode=episode,
            show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
            stop_after_first=_quick, processed_targets=processed_targets,
            scan_state=scan_state,
        )
        _active_race = scan_state.get('race')
        if _active_race is not None:
            remaining_targets = _active_race.pending_items()
        else:
            processed_set = set((id(p), rid) for p, rid in processed_targets)
            remaining_targets = [t for t in targets if (id(t[0]), t[1]) not in processed_set]
        if not entries and fallback_targets:
            processed_targets = []
            try:
                if _active_race is not None:
                    _active_race.cancel()
            except Exception:
                pass
            scan_state = {}
            entries = _collect_stream_entries(
                fallback_targets, media_type, canonical_id, best_meta, art, bg, ids,
                title=title or video_id, video_id=video_id, season=season, episode=episode,
                show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
                stop_after_first=_quick, processed_targets=processed_targets,
                scan_state=scan_state,
            )
            _active_race = scan_state.get('race')
            if _active_race is not None:
                remaining_targets = _active_race.pending_items()
            else:
                processed_set = set((id(p), rid) for p, rid in processed_targets)
                remaining_targets = [t for t in fallback_targets if (id(t[0]), t[1]) not in processed_set]
    if not entries and _kodi_late:
        entries = _kodi_collect(_kodi_late, _kodi_rows_converter(
            media_type, canonical_id, best_meta, art, bg, ids, title=title or video_id, video_id=video_id,
            season=season, episode=episode, show_title=best_meta.get('name') or canonical_id,
            resume_seconds=resume_seconds, resume_percent=resume_percent_val))
        _kodi_late = None
    if not entries:
        try:
            if entries is None or _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        if _source_scan_cancelled():
            xbmc.log('[DexHub] source scan cancelled by the user — no error', xbmc.LOGINFO)
            return end_dir(cache=False)
        error(tr('لم يتم العثور على روابط تشغيل للحلقة'))
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id, video_id=video_id)
    # Pull plot/year/genre/rating from best_meta so the source window can
    # render the redesigned hero panel for the episode picker too.
    _ep_genres = best_meta.get('genres') or []
    if isinstance(_ep_genres, list):
        _ep_genre_str = ' / '.join([str(g) for g in _ep_genres[:3] if g])
    else:
        _ep_genre_str = str(_ep_genres or '')
    _ep_year_val = ''
    _ep_release = best_meta.get('releaseInfo') or best_meta.get('year') or ''
    if _ep_release:
        _ep_ymatch = YEAR_RE.search(str(_ep_release))
        if _ep_ymatch:
            _ep_year_val = _ep_ymatch.group(1)
    _ep_rating = best_meta.get('imdbRating') or ''
    try:
        if _ep_rating:
            _ep_rating = '%.1f' % float(_ep_rating)
    except Exception:
        _ep_rating = str(_ep_rating or '')
    _ep_info = _stream_meta_info_payload(best_meta, media_type=media_type, title=title or video_id, show_title=best_meta.get('name') or canonical_id, season=season, episode=episode)
    _ep_studio = _ep_info.get('studio') or ''
    if isinstance(_ep_studio, (list, tuple)):
        _ep_studio = ' / '.join([str(x) for x in _ep_studio if x])
    meta = {
        'title': title or video_id,
        'poster': art.get('poster') or provider_fb.get('poster') or provider_fb.get('thumb') or '',
        'fanart': _content_background(art, provider_fb),
        'clearlogo': art.get('clearlogo') or '',
        'plot': best_meta.get('description') or best_meta.get('overview') or '',
        'year': _ep_year_val,
        'genre': _ep_genre_str,
        'rating': _ep_rating,
        'studio': _ep_studio,
        'imdb_id': ids.get('imdb_id') or '',
        'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'media_type': media_type,
        'canonical_id': canonical_id,
        'season': season,
        'episode': episode,
    }
    session_key = ''
    if remaining_targets or _kodi_late:
        session_key = source_session.create(entries, done=False, version=1)
        if remaining_targets:
            _start_stream_session_refresh(
                session_key, entries, remaining_targets, media_type, canonical_id, best_meta, art, bg, ids,
                title=title or video_id, video_id=video_id, season=season, episode=episode,
                show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val,
                scan_race=_active_race,
            )
        if _kodi_late:
            _kodi_late.attach(session_key, _kodi_rows_converter(
            media_type, canonical_id, best_meta, art, bg, ids, title=title or video_id, video_id=video_id,
            season=season, episode=episode, show_title=best_meta.get('name') or canonical_id,
            resume_seconds=resume_seconds, resume_percent=resume_percent_val), base_done=not remaining_targets)
    return _show_stream_window(entries, meta, session_key=session_key)

def _resolve_best_id(video_type, tmdb_id='', imdb_id='', tvdb_id='', title=''):
    if tmdb_id:
        return 'tmdb:%s' % tmdb_id
    if imdb_id:
        return imdb_id if str(imdb_id).startswith('tt') else 'imdb:%s' % imdb_id
    if tvdb_id:
        return 'tvdb:%s' % tvdb_id
    return title or ''

def _find_episode_video_id(canonical_id, season, episode):
    cached = _meta_mem_get('series', canonical_id) or {}
    for video in cached.get('videos') or []:
        try:
            if (int(video.get('season') or 0) == int(season) and
                    int(video.get('episode') or 0) == int(episode) and video.get('id')):
                return video['id'], cached.get('name') or cached.get('title') or ''
        except (TypeError, ValueError, AttributeError):
            continue
    providers = _provider_order_for_id('series', canonical_id)
    for provider in providers:
        try:
            data = fetch_meta(provider, 'series', canonical_id, timeout_override=fast_timeout('meta'))
            meta = data.get('meta') or data.get('metas')
            if isinstance(meta, list):
                meta = meta[0] if meta else None
            videos = (meta or {}).get('videos') or []
            if isinstance(meta, dict) and videos:
                _meta_mem_put('series', canonical_id, meta)
            for video in videos:
                if int(video.get('season') or 0) == int(season or 0) and int(video.get('episode') or 0) == int(episode or 0):
                    return video.get('id') or canonical_id, (meta or {}).get('name') or canonical_id
        except Exception:
            continue
    return canonical_id, ''

