def _append_a4k_ids_to_url(url, ctx):
    """Append Syncler/Stremio-style |ids={...} metadata for a4kSubtitles.

    a4kSubtitles supports IMDb metadata passed through the playing file URL;
    adding the compact ids object lets it recover IMDb even when Kodi's
    VideoPlayer.IMDBNumber infolabel is delayed/empty for plugin handoffs.
    """
    url = str(url or '').strip()
    if not url:
        return url
    lower = url.lower()
    # Do not append |ids={...} to real media URLs. Kodi treats the pipe suffix
    # as URL/header options, and several PlexBridge/Plexio/CDN links fail to
    # open when an unknown ids option is added after the file URL. The playback
    # ListItem still carries IMDb/TMDb/TVDb via InfoTag, UniqueIDs and window
    # properties for a4k/subtitle addons.
    if lower.startswith(('http://', 'https://', 'ftp://', 'smb://', 'nfs://', 'dav://', 'davs://', 'file://')):
        return url
    if lower.startswith(('plugin://', 'magnet:')) or '|ids=' in lower or '&ids=' in lower:
        return url
    ids = _ids_from_playback_ctx(ctx)
    payload = {}
    if ids.get('tmdb_id'):
        try:
            payload['tmdb'] = int(str(ids.get('tmdb_id')))
        except Exception:
            payload['tmdb'] = str(ids.get('tmdb_id'))
    if ids.get('imdb_id'):
        payload['imdb'] = str(ids.get('imdb_id'))
    if ids.get('tvdb_id'):
        try:
            payload['tvdb'] = int(str(ids.get('tvdb_id')))
        except Exception:
            payload['tvdb'] = str(ids.get('tvdb_id'))
    try:
        if ctx.get('season') not in (None, '', '0', 0):
            payload['season'] = int(ctx.get('season') or 0)
        if ctx.get('episode') not in (None, '', '0', 0):
            payload['episode'] = int(ctx.get('episode') or 0)
    except Exception:
        pass
    if not payload.get('imdb'):
        return url
    marker = 'ids=' + json.dumps(payload, separators=(',', ':'), ensure_ascii=False)
    if '|' in url:
        base, opts = url.split('|', 1)
        return base + '|' + (opts + '&' if opts else '') + marker
    return url + '|' + marker

def _meta_with_seed_ids(meta, ids):
    """Expose resolved ids to stream target discovery without changing UI meta."""
    out = dict(meta or {})
    ids = ids or {}
    external = dict(out.get('externalIds') or {}) if isinstance(out.get('externalIds') or {}, dict) else {}
    for src, external_key, camel_key in (
        ('imdb_id', 'imdb', 'imdbId'),
        ('tmdb_id', 'tmdb', 'tmdbId'),
        ('tvdb_id', 'tvdb', 'tvdbId'),
    ):
        val = str(ids.get(src) or '').strip()
        if not val:
            continue
        out.setdefault(src, val)
        out.setdefault(camel_key, val)
        external.setdefault(external_key, val)
    if external:
        out['externalIds'] = external
    return out

def _local_resume_lookup(media_type, canonical_id, video_id='', season=None, episode=None):
    """(seconds, percent) from Dex Hub's local progress DB, else (0.0, 0.0).

    v3.9.153: playback launched from TMDb Helper's own lists reaches
    _auto_play_first_* with resume 0 because TMDbH cannot know Dex Hub's
    saved positions. Continue-Watching data already lives in
    playback_store — look the item up so "استكمال المشاهدة" works no matter
    which side started playback. Finished items (>=95%) and tiny positions
    (<=30s) return zero so fresh plays stay fresh.
    """
    def _n(v):
        t = str(v).strip() if v is not None else ''
        return str(int(t)) if t.isdigit() else t
    want_mt = 'series' if _is_series_media(media_type) else str(media_type or 'movie')
    # Fast indexed lookup first. This avoids loading and scanning up to 500
    # continue-watching rows on every TMDb Helper handoff.
    try:
        ids = extract_ids({'id': canonical_id or ''}) or {}
        row = playback_store.find_resume_entry(
            media_type=want_mt,
            canonical_id=canonical_id or video_id or '',
            tmdb_id=ids.get('tmdb_id') or '',
            imdb_id=ids.get('imdb_id') or '',
            tvdb_id=ids.get('tvdb_id') or '',
            season=season, episode=episode,
        )
        if row:
            pos = float(row.get('position') or 0.0)
            dur = float(row.get('duration') or 0.0)
            pct = float(row.get('percent') or 0.0)
            if pct <= 0.0 and dur > 0:
                pct = pos / dur * 100.0
            if pos > 30.0 and (pct <= 0.0 or pct < 95.0):
                return pos, pct
            return 0.0, 0.0
    except Exception:
        pass

    # Compatibility fallback for old/pre-migration rows that do not yet carry
    # indexed external IDs. It only runs after the fast path misses.
    try:
        rows = playback_store.list_continue_items(limit=500) or []
    except Exception:
        return 0.0, 0.0
    cid, vid = _n(canonical_id), _n(video_id)
    sn, ep = _n(season), _n(episode)
    for r in rows:
        try:
            if str(r.get('media_type') or '') != want_mt:
                continue
            if not ((cid and _n(r.get('canonical_id')) == cid) or (vid and _n(r.get('video_id')) == vid)):
                continue
            if sn and _n(r.get('season')) != sn:
                continue
            if ep and _n(r.get('episode')) != ep:
                continue
            pos = float(r.get('position') or 0.0)
            dur = float(r.get('duration') or 0.0)
            pct = float(r.get('percent') or 0.0)
            if pct <= 0.0 and dur > 0:
                pct = pos / dur * 100.0
            if pos > 30.0 and (pct <= 0.0 or pct < 95.0):
                return pos, pct
            return 0.0, 0.0
        except Exception:
            continue
    return 0.0, 0.0

def _auto_play_first_movie(canonical_id, title='', seed_ids=None, preferred_provider_name='', resume_seconds=0.0, resume_percent=0.0, source_provider_id='', source_mode='', pick_dialog=False, ui_seed=None, source_server_id=''):
    # v5.10.172: play_item's quick-same path passes the server like the
    # episode path does; a movie took no such argument and Resume failed
    if source_server_id and not (ui_seed or {}).get('native_server_id'):
        ui_seed = dict(ui_seed or {}, native_server_id=source_server_id)
    try:
        if float(resume_seconds or 0) <= 1.0 and float(resume_percent or 0) <= 1.0:
            _rs, _rp = _local_resume_lookup('movie', canonical_id)
            if _rs > 1.0 or _rp > 1.0:
                resume_seconds, resume_percent = _rs, _rp
    except Exception:
        pass
    providers = _provider_order_for_id_with_context('movie', canonical_id, source_provider_id=source_provider_id)
    if source_mode == 'quick_same':
        best_meta, _cached = _fast_meta_for_sources('movie', canonical_id, providers,
            title=title, source_provider_id=source_provider_id, seed_ids=seed_ids)
    else:
        best_meta = _best_meta_for_item('movie', canonical_id, providers, source_provider_id=source_provider_id)
    if ui_seed:
        best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, 'movie')
    art = _resolve_meta_art(providers[0] if providers else {}, 'movie', best_meta, fallback_art=provider_fb)
    art = _prefer_item_art(art, best_meta, 'movie', fallback_art=provider_fb)
    bg = _content_background(art, provider_fb)
    ids = _merge_seed_ids(extract_ids(best_meta), seed_ids or _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, 'movie', meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    entries = []
    targets_all = _prioritize_provider_targets(list(_stream_provider_targets('movie', canonical_id, meta=stream_meta)), preferred_provider_name=preferred_provider_name)

    def _quick_same_fallback(reason):
        # v5.10.103: see _auto_play_first_episode
        xbmc.log('[DexHub] quick same-source: %s for %s; opening the source picker'
                 % (reason, source_provider_id or preferred_provider_name or '?'), xbmc.LOGINFO)
        return streams('movie', canonical_id, title=title, resume_seconds=resume_seconds,
                       resume_percent=resume_percent,
                       preferred_provider_name=preferred_provider_name,
                       source_provider_id=source_provider_id, source_mode='',
                       seed_ids=seed_ids, ui_seed=ui_seed)

    if source_mode == 'quick_same':
        targets_all = _quick_same_source_targets(targets_all, source_provider_id,
            preferred_provider_name, (ui_seed or {}).get('native_server_id') or '')
        if not targets_all:
            return _quick_same_fallback('no stream targets')
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    def _fetch(t):
        return _fetch_stream_payload(t, 'movie')

    # v5.10.314: the choice is made after the first sources settle (patient
    # scan setting: every provider, as before)
    for target, data in (run_parallel(_fetch, targets) if _full_parallel_source_scan_enabled()
                         else _run_parallel_settle(_fetch, targets)):
        if isinstance(data, Exception) or not data:
            continue
        p, rid = target
        _append_stream_entries_from_data(entries, data, p, rid, 'movie', canonical_id, best_meta, art, bg, ids, title=title, resume_seconds=resume_seconds, resume_percent=resume_percent)
    if not entries and fallback_targets:
        for target, data in run_parallel(_fetch, fallback_targets):
            if isinstance(data, Exception) or not data:
                continue
            p, rid = target
            _append_stream_entries_from_data(entries, data, p, rid, 'movie', canonical_id, best_meta, art, bg, ids, title=title, resume_seconds=resume_seconds, resume_percent=resume_percent)
    if not entries and source_mode == 'quick_same':
        return _quick_same_fallback('no links')
    if not entries:
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        error(tr('لم يتم العثور على روابط تشغيل'))
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type='movie', canonical_id=canonical_id)
    if pick_dialog:
        try:
            items = []
            for e in entries:
                li = xbmcgui.ListItem(e.get('name') or e.get('stream_title') or '?')
                try:
                    li.setLabel2(_entry_second_line(e))
                    _p = art.get('poster') or ''
                    if _p:
                        li.setArt({'icon': _p, 'thumb': _p, 'poster': _p})
                except Exception:
                    pass
                items.append(li)
            choice = xbmcgui.Dialog().select(tr('اختر السورس'), items, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(tr('اختر السورس'), [e.get('name') or '?' for e in entries])
        if choice < 0:
            _clear_tmdbh_transient()
            _clear_source_transient_props(clear_global=True)
            if HANDLE >= 0:
                try:
                    xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
                except Exception:
                    pass
            return
        return play(entries[choice]['stream_key'], resume_seconds=resume_seconds, resume_percent=resume_percent)
    return play(entries[0]['stream_key'], resume_seconds=resume_seconds, resume_percent=resume_percent)

def _auto_play_first_episode(canonical_id, video_id, season, episode, title='', seed_ids=None, preferred_provider_name='', resume_seconds=0.0, resume_percent=0.0, source_provider_id='', source_mode='', pick_dialog=False, source_server_id='', source_affinity=None, ui_seed=None):
    try:
        if float(resume_seconds or 0) <= 1.0 and float(resume_percent or 0) <= 1.0:
            _rs, _rp = _local_resume_lookup('series', canonical_id, video_id, season, episode)
            if _rs > 1.0 or _rp > 1.0:
                resume_seconds, resume_percent = _rs, _rp
    except Exception:
        pass
    providers = _provider_order_for_id_with_context('series', canonical_id, source_provider_id=source_provider_id)
