def _continue_row_is_episode(row):
    try:
        return int(row.get('season') or 0) > 0 and int(row.get('episode') or 0) >= 0
    except Exception:
        return False

_CW_CODE_RE = re.compile(r'^(?:(?=[A-Z0-9]*[A-Z])[A-Z0-9]{4,}|\d{5,})$')

def _cw_looks_like_code(text):
    """True for id-like 'titles' (JSGB4701, 28739) that must never be shown."""
    t = str(text or '').strip()
    return (not t) or bool(_CW_CODE_RE.match(t))

