def _reset_invocation_state():
    """Clear state that must NOT survive from a previous plugin invocation.

    v3.9.235: addon.xml sets reuselanguageinvoker=true, so the Python VM (and
    every module-level global) stays alive between invocations. `_PENDING_ITEMS`
    is the buffer that add_item() appends to and that _flush_pending_items()
    drains on end_dir(). If an action raises BETWEEN those two points — an
    upstream error, a user backing out mid-render — the buffer is never drained
    and the leftovers stay resident. The NEXT screen then flushes them together
    with its own rows: ghost entries and stale art from the previous directory.

    run() already swallows the exception so Kodi shows a dialog rather than
    dying, which means the leak is silent and reproducible. Clearing at the
    START of every dispatch is the only place guaranteed to run.
    """
    global _PENDING_ITEMS
    from .runtime_binding import bind
    bind(sys.modules[__name__])
    if _PENDING_ITEMS:
        try:
            xbmc.log('[DexHub] dropping %d stale buffered item(s) from a previous '
                     'invocation (reuselanguageinvoker warm VM)' % len(_PENDING_ITEMS),
                     xbmc.LOGWARNING)
        except Exception:
            pass
    _PENDING_ITEMS = []
    # v4.6.4: `from .context import *` COPIES HANDLE into this module's
    # namespace at import time, and the warm VM keeps that copy across
    # invocations — a RunPlugin invocation (handle -1) then poisoned every
    # later folder render in the same VM (empty ".." directory, dead
    # endOfDirectory). Refresh the source of truth AND this module's copy
    # at the start of every dispatch.
    global HANDLE
    try:
        from . import context as _ctx_mod
        HANDLE = _ctx_mod.refresh_invocation()
    except Exception:
        try:
            HANDLE = int(sys.argv[1])
        except Exception:
            HANDLE = -1
    # v4.6.9: ui_core captures its OWN module-level HANDLE at import time
    # and end_dir()/setContent() run on it — the third frozen copy of the
    # same warm-VM bug 4.6.4 fixed in context/plugin. Rebind it too.
    try:
        from . import ui_core as _ui_mod
        _ui_mod.HANDLE = HANDLE
    except Exception:
        pass

def _streams_item_key(canonical_id, season, episode):
    def _n(v):
        t = str(v).strip() if v is not None else ''
        return str(int(t)) if t.isdigit() else t
    return '%s|%s|%s' % (_n(canonical_id), _n(season), _n(episode))

def _entry_second_line(e):
    """Small provider-first line: addon site size quality."""
    parts = []
    prov = str(e.get('provider_name_raw') or e.get('addon') or '').strip()
    if prov:
        parts.append(prov)
    site = str(e.get('source_site') or '').strip()
    if site and site.lower() != prov.lower():
        parts.append(site)
    size = str(e.get('size_label') or '').strip()
    if size and size != '--':
        parts.append(size)
    q = str(e.get('quality') or '').strip()
    if q:
        parts.append(q)
    return ' \u00b7 '.join(parts)

def _named_ids(ctx):
    """v5.10.255: a server title with no IMDb or TMDb id (a Plex library
    that never matched it, such as an Arabic series named only in Arabic)
    is looked up on TMDb by its name and year, so the source search can ask
    the add-ons for it (it asked them for plex:<server>:<item> and found
    nothing). The show's name for an episode."""
    ctx = dict(ctx or {})
    canonical = str(ctx.get('canonical_id') or '')
    if not canonical.startswith(('plex:', 'emby:', 'jellyfin:', 'silo:')):
        return ctx
    is_ep = ctx.get('season') not in (None, '', 0, '0') and ctx.get('episode') not in (None, '', 0, '0')
    if is_ep and (ctx.get('show_imdb_id') or ctx.get('show_tmdb_id')):
        return ctx
    if not is_ep and (ctx.get('imdb_id') or ctx.get('tmdb_id')):
        return ctx
    name = (ctx.get('show_title') if is_ep else ctx.get('title')) or ''
    if not name:
        return ctx
    year = str(ctx.get('show_year') or ctx.get('year') or '').strip()
    kind = 'tv' if is_ep else 'movie'
    try:
        from . import tmdb_direct as _td
        tmdb_id = _td._resolve_tmdb_from_search(name, year, kind) if year.isdigit() else ''
        tmdb_id = tmdb_id or _td._resolve_tmdb_from_search(name, '', kind)
        if not tmdb_id:
            return ctx
        imdb_id = ''
        try:
            imdb_id = _td.imdb_id_for(tmdb_id, media_type='series' if is_ep else 'movie', timeout=4) or ''
        except Exception:
            imdb_id = ''
    except Exception as exc:
        xbmc.log('[DexHub] panel search: name lookup failed: %s' % exc, xbmc.LOGDEBUG)
        return ctx
    if is_ep:
        ctx['show_tmdb_id'] = tmdb_id
        ctx['show_imdb_id'] = imdb_id
    else:
        ctx['tmdb_id'] = tmdb_id
        ctx['imdb_id'] = imdb_id
    xbmc.log('[DexHub] panel search: "%s" %s found on TMDb as %s %s'
             % (name, year, tmdb_id, imdb_id), xbmc.LOGINFO)
    return ctx


def osd_rescan(ctx, on_progress=None):
    """v5.10.252: the player's Sources panel searches again in place.

    The same silent search as the next-episode pre-cache (no loader, no
    picker, no notice): every source for the playing title, by its own ids
    (a server play searches by the show's or movie's ids, safe_helpers
    _search_ctx). The rows go into the source index the panel lists, under
    the search's key and the playing session's key. Returns the entries."""
    from .safe_helpers import _search_ctx
    sctx = _search_ctx(_named_ids(ctx or {}))
    media_type = sctx.get('media_type') or 'movie'
    canonical_id = sctx.get('canonical_id') or ''
    if not canonical_id:
        return []
    season, episode = sctx.get('season'), sctx.get('episode')
    is_ep = (_is_series_media(media_type) and season not in (None, '', 0, '0')
             and episode not in (None, '', 0, '0'))
    season_i = int(season) if is_ep else None
    episode_i = int(episode) if is_ep else None
    video_id = (sctx.get('video_id') or canonical_id) if is_ep else ''
    title = sctx.get('show_title') or sctx.get('title') or canonical_id
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id='')
    best_meta, _has = _fast_meta_for_sources(media_type, canonical_id, providers,
                                             title=title, source_provider_id='')
    ids = _merge_seed_ids(extract_ids(best_meta), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id,
                             title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    targets_all = list(_stream_provider_targets(media_type, canonical_id, meta=stream_meta,
                                                season=season_i, episode=episode_i))
    if is_ep:
        direct_targets = []
        for provider in store.list_providers():
            if not _get_bool_setting('stremio_sources_enabled', True):
                break
            if provider.get('enabled') is False or _source_left_out(provider):
                continue
            if supports_resource(provider, 'stream', media_type=media_type, item_id=video_id):
                direct_targets.append((provider, video_id))
        from .search.episode_route import merge_targets
        targets_all = merge_targets(targets_all, direct_targets)
    targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name='')
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id='', source_mode='')
    poster = (ctx or {}).get('poster') or ''
    playing = ctx or {}
    keys = [(canonical_id, season_i, episode_i)]
    if playing.get('canonical_id') and playing.get('canonical_id') != canonical_id:
        keys.append((playing.get('canonical_id'), playing.get('season'), playing.get('episode')))

    def _publish(found):
        for cid, s_, e_ in keys:
            try:
                _publish_last_streams_index(cid, s_, e_, found, poster=poster)
            except Exception as exc:
                xbmc.log('[DexHub] panel search: index failed: %s' % exc, xbmc.LOGWARNING)

    shown = {'n': -1, 't': 0.0}

    def _progress(done, total, so_far):
        # v5.10.253: each provider's answer reaches the open panel (at most
        # every 0.8 s, and only when the list grew)
        if on_progress is None:
            return
        now = time.monotonic()
        grew = len(so_far) != shown['n']
        if grew and now - shown['t'] >= 0.8:
            try:
                _publish(_finalize_stream_entries(list(so_far), media_type=media_type,
                                                  canonical_id=canonical_id, video_id=video_id))
            except Exception:
                _publish(list(so_far))
            shown['n'], shown['t'] = len(so_far), now
        on_progress(done, total, len(so_far))

    entries = []
    for group in (targets, fallback_targets):
        if entries or not group:
            continue
        entries = _collect_stream_entries(
            group, media_type, canonical_id, best_meta, {}, '', ids,
            title=title, video_id=video_id, season=season_i, episode=episode_i,
            show_title=best_meta.get('name') or title,
            resume_seconds=0.0, resume_percent=0.0,
            show_loader=False, stop_after_first=False, processed_targets=None,
            progress=_progress,
        ) or []
    if entries:
        entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id,
                                           video_id=video_id)
    _publish(entries)
    xbmc.log('[DexHub] panel search: %d source(s) for %s s%s e%s'
             % (len(entries), canonical_id, season_i, episode_i), xbmc.LOGINFO)
    return entries


def _publish_last_streams_index(canonical_id, season, episode, entries, poster=''):
    """Keep a one-slot index of the LAST rendered source list (v3.9.151).

    Written after every row append so live-filling providers are captured;
    last-writer-wins on a single Window(10000) property, so memory stays
    bounded to one item.  switch_source() reads this to offer an instant
    overlay of the previous search instead of re-scraping.
    """
    rows = []
    for e in entries:
        k = e.get('stream_key')
        if not k:
            continue
        rows.append({'k': k,
                     'l': e.get('name') or e.get('stream_title') or '?',
                     'l2': _entry_second_line(e),
                     # v5.10.294: what the sources window shows on the row, so
                     # the player's Sources panel reads the same
                     'id': str(e.get('source_identity_line') or e.get('origin_line')
                               or e.get('provider') or ''),
                     # v5.10.296: the add-on name the sources window shows
                     'p': str(e.get('provider') or e.get('provider_name_raw') or ''),
                     's': str(e.get('size_label') or ''),
                     # v5.10.297: Nuvio-style row and sort keys
                     'n': str(e.get('stream_name_raw') or ''),
                     'd': str(e.get('stream_desc_raw') or ''),
                     'q': str(e.get('quality') or ''),
                     'c': e.get('cached') if e.get('cached') in (True, False) else None,
                     'lib': bool(e.get('in_library'))})
    payload = {
        'item': _streams_item_key(canonical_id, season, episode),
        'poster': poster or '',
        'rows': rows,
        'ts': int(time.time()),
    }
    data = json.dumps(payload)
    xbmcgui.Window(WINDOW_ID).setProperty('dexhub.last_streams', data)
    # Window properties can disappear when Kodi replaces the player or starts a
    # fresh plugin invocation. Keep the exact same list in the lightweight
    # SQLite cache so source switching never needs to scrape providers again.
    try:
        cache_store.update('source_index', payload['item'], payload)
    except Exception:
        pass

_SOURCE_SWITCH_HANDOFF_PROP = 'dexhub.source_switch_handoff.v2'

def _dispatch():
    params = dict(parse_qsl(sys.argv[2].lstrip('?')))
    action = params.get('action')
    # v5.10.156 (issue #5): the user's refresh setting back before real playback
    try:
        from . import refresh_guard
        refresh_guard.restore()
    except Exception:
        pass
    if action == 'tmdb_player':
        # Helper no longer loads/scans the unrelated account/catalog dispatcher.
        # The supplied runtime remains explicit until source adapters are split.
        from .helper_entry import dispatch as _helper_dispatch
        return _helper_dispatch(params, sys.modules[__name__])
    if action == 'native_resume':
        from . import native_continue
        return native_continue.play(sys.modules[__name__], params.get('key', ''))
    if action == 'cw_resume':
        from . import continue_playback
        keys = ('media_type', 'canonical_id', 'video_id', 'season', 'episode',
                'title', 'position', 'resume_percent', 'provider_name', 'direct',
                'source_provider_id', 'ui_poster', 'ui_fanart', 'ui_clearlogo',
                'studio', 'ui_seed_key')
        return continue_playback.resume(sys.modules[__name__],
                                         **{k: params[k] for k in keys if k in params})
    if action == 'jellyfin_play':
        servers = jellyfin_client.servers()
        if not servers:
            return error(tr('تعذر العثور على العنصر'))
        return emby_play(params.get('key', ''), server=servers[0], backend='jellyfin',
                         ui_seed_key=params.get('ui_seed_key', ''))
    if action == 'emby_play':
        return emby_play(params.get('item_id', ''), ui_seed_key=params.get('ui_seed_key', ''))
    if action == 'silo_play':
        return silo_play(params.get('item_id', ''), ui_seed_key=params.get('ui_seed_key', ''))
    if action == 'plex_play':
        return plex_play(params.get('server_id', ''), params.get('rating_key', ''),
                         ui_seed_key=params.get('ui_seed_key', ''))
    if action == 'streams':
        from . import playback_choices
        return playback_choices.route(sys.modules[__name__], params, episodic=False)
    if action == 'play_item':
        return play_item(media_type=params.get('media_type', 'movie'), canonical_id=params.get('canonical_id', ''), title=params.get('title', ''), video_id=params.get('video_id', ''), season=params.get('season', ''), episode=params.get('episode', ''), resume_seconds=params.get('resume_seconds', '0'), resume_percent=params.get('resume_percent', ''), preferred_provider_name=params.get('preferred_provider_name', ''), tmdb_id=params.get('tmdb_id', ''), imdb_id=params.get('imdb_id', ''), tvdb_id=params.get('tvdb_id', ''), source_provider_id=params.get('source_provider_id', ''), source_mode=params.get('source_mode', ''), ui_poster=params.get('ui_poster', ''), ui_fanart=params.get('ui_fanart', ''), ui_clearlogo=params.get('ui_clearlogo', ''), ui_seed_key=params.get('ui_seed_key', ''))
    if action == 'play_next_same_source':
        return play_next_episode_same_source(
            canonical_id=params.get('canonical_id', ''),
            video_id=params.get('video_id', ''),
            season=params.get('season', ''),
            episode=params.get('episode', ''),
            title=params.get('title', ''),
            source_provider_id=params.get('source_provider_id', ''),
            source_server_id=params.get('source_server_id', ''),
            preferred_provider_name=params.get('preferred_provider_name', ''),
            preferred_binge_group=params.get('preferred_binge_group', ''),
            preferred_source_addon=params.get('preferred_source_addon', ''),
            preferred_source_indexer=params.get('preferred_source_indexer', ''),
            preferred_source_service=params.get('preferred_source_service', ''),
            preferred_source_type=params.get('preferred_source_type', ''),
        )
    if action == 'episode_streams':
        from . import playback_choices
        return playback_choices.route(sys.modules[__name__], params, episodic=True)
    if action == 'play':
        try:
            fallback_keys = json.loads(params.get('fallback_keys') or '[]')
            if not isinstance(fallback_keys, list):
                fallback_keys = []
        except Exception:
            fallback_keys = []
        return play(params.get('stream_key', ''), resume_seconds=params.get('resume_seconds', ''), resume_percent=params.get('resume_percent', ''), fallback_keys=fallback_keys, switch_subtitle_path=params.get('switch_subtitle_path', ''), switch_subtitle_enabled=params.get('switch_subtitle_enabled', ''), switch_subtitle_name=params.get('switch_subtitle_name', ''))
    if action == 'switch_source':
        from . import source_switch
        return source_switch.run(sys.modules[__name__], params)
    raise ValueError("Unsupported player action")

def run():
    # v3.9.53: defensive wrapper around the entire dispatcher. If ANY
    # action fails with an uncaught exception, the traceback is logged
    # before re-raising. Previously a silent error in a handler could
    # make a home button appear to "do nothing", with no diagnostic
    # trace in kodi.log. Now every failure leaves a full traceback that
    # identifies the failing function and line.
    #
    # v3.9.71: also surface the traceback in a textviewer dialog so the
    # user can read and screenshot it on TV/mobile without diving into
    # kodi.log. Crash before playback is the canonical case where this
    # is critical — silent failures here just look like "nothing
    # happens" to the user.
    _reset_invocation_state()
    try:
        return _dispatch()
    except Exception as _exc:
        try:
            import traceback as _tb
            _trace = _tb.format_exc()
            xbmc.log('[DexHub] DISPATCHER ERROR: %s\n%s' % (_exc, _trace),
                     xbmc.LOGERROR)
        except Exception:
            _trace = str(_exc)
        try:
            _action_for_dialog = ''
            try:
                _action_for_dialog = dict(parse_qsl(sys.argv[2].lstrip('?'))).get('action', '')
            except Exception:
                pass
            xbmcgui.Dialog().textviewer(
                tr('Dex Hub — حدث خطأ غير متوقع'),
                ('Action: %s\nArgv: %s\n\nError:\n%s\n\n%s') % (
                    _action_for_dialog or '?',
                    sys.argv[2] if len(sys.argv) > 2 else '?',
                    str(_exc),
                    _trace,
                ),
            )
        except Exception:
            pass
        # Don't re-raise — the user has seen the diagnostic dialog
        # already, and re-raising adds Kodi's own less-useful crash
        # notification on top. Returning None keeps the addon alive so
        # the next click works.
        return
